        STA2E.MoveDefs["R" .. i] = STA2E.MoveDefs["R" .. i] or {forward = -distance, side = 0, rotate = 0}
        STA2E.MoveDefs["GL" .. i] = STA2E.MoveDefs["GL" .. i] or {forward = 0, side = distance, rotate = 0}
        STA2E.MoveDefs["GR" .. i] = STA2E.MoveDefs["GR" .. i] or {forward = 0, side = -distance, rotate = 0}
    end

    -- Borg spin maneuvers move straight, then rotate 90 degrees.
    for i, distance in ipairs(reverse) do
        STA2E.MoveDefs["SL" .. i] = STA2E.MoveDefs["SL" .. i] or {forward = distance, side = 0, rotate = 90, finishRotateOnly = true}
        STA2E.MoveDefs["SR" .. i] = STA2E.MoveDefs["SR" .. i] or {forward = distance, side = 0, rotate = -90, finishRotateOnly = true}
    end

    -- Come About: first-pass implementation. Tune later with your actual templates.
    STA2E.MoveDefs.CA1 = STA2E.MoveDefs.CA1 or {forward = 3.10, side = 0, rotate = 180}
    STA2E.MoveDefs.CA2 = STA2E.MoveDefs.CA2 or {forward = 4.60, side = 0, rotate = 180}
    STA2E.MoveDefs.CA3 = STA2E.MoveDefs.CA3 or {forward = 6.30, side = 0, rotate = 180}
    STA2E.MoveDefs.CA4 = STA2E.MoveDefs.CA4 or {forward = 7.90, side = 0, rotate = 180}

    -- DS9 / station-style entries from the dial database.
    STA2E.MoveDefs.STOP0 = STA2E.MoveDefs.STOP0 or {forward = 0, side = 0, rotate = 0}
    STA2E.MoveDefs.ROTL0 = STA2E.MoveDefs.ROTL0 or {rotate = -90}
    STA2E.MoveDefs.ROTR0 = STA2E.MoveDefs.ROTR0 or {rotate = 90}
    STA2E.MoveDefs.PIVOTL0 = STA2E.MoveDefs.PIVOTL0 or {rotate = -45}
    STA2E.MoveDefs.PIVOTR0 = STA2E.MoveDefs.PIVOTR0 or {rotate = 45}
    STA2E.MoveDefs.DL1 = STA2E.MoveDefs.DL1 or {forward = -3.10, side = 3.10, rotate = 0}
    STA2E.MoveDefs.DR1 = STA2E.MoveDefs.DR1 or {forward = -3.10, side = -3.10, rotate = 0}
    STA2E.MoveDefs.DL2 = STA2E.MoveDefs.DL2 or {forward = -4.60, side = 4.60, rotate = 0}
    STA2E.MoveDefs.DR2 = STA2E.MoveDefs.DR2 or {forward = -4.60, side = -4.60, rotate = 0}
end


STA2E.EnsureMoveDefs()
MOVE_DEFS = STA2E.MoveDefs
-- STA2E 0.4: persistent ship-instance development slice.
-- CATALOG, MEMBER_SCRIPT, GALAXY_DIAL and MOVE_DEFS are bundled by build.mjs.
STA2E = {ships={}, pending={}, imports={}, ready=false}
local function copy(value) return JSON.decode(JSON.encode(value)) end
local function decode(text)
    local ok, value = pcall(JSON.decode, text or "")
    if ok and type(value) == "table" then return value end
    return nil
end
local function tell(color, message)
    if color == "Blue" or color == "Red" or color == "Black" then
        broadcastToColor(message, color, {0.65,0.85,1})
    else print(message) end
end
local function xml(text)
    return tostring(text or ""):gsub("&", "&amp;"):gsub('"', "&quot;"):gsub("<", "&lt;"):gsub(">", "&gt;")
end
local function defaultXmlAttribute(markup,tag,attribute,value)
    local needle="<"..tag.." ";local output={};local cursor=1
    while true do
        local first,last=markup:find(needle,cursor,true)
        if not first then table.insert(output,markup:sub(cursor));break end
        table.insert(output,markup:sub(cursor,first-1))
        local close=markup:find(">",last+1,true)
        if not close then table.insert(output,markup:sub(first));break end
        local node=markup:sub(first,close)
        if not node:find(" "..attribute.."=",1,true) then node=needle..attribute..'="'..value..'" '..node:sub(#needle+1) end
        table.insert(output,node);cursor=close+1
    end
    return table.concat(output)
end
local function obj(guid) return guid and getObjectFromGUID(guid) or nil end
local PLAYER_COLORS={"Blue","Red","Green","Purple","Orange","Yellow"}
local PLAYER_COLOR_SET={Blue=true,Red=true,Green=true,Purple=true,Orange=true,Yellow=true}
local FLEET_STAGING_BOARD_GUID="3b5e31"
local FLEET_HAND_GUIDS={Blue="14a077",Red="7e36ee",Green="52a30b",Purple="a418ef",Orange="657947",Yellow="7e86d6"}
local function own(color) return PLAYER_COLOR_SET[color]==true end
local function nextId()
    STA2E.game.nextId = STA2E.game.nextId + 1
    return "sta2e-" .. tostring(STA2E.game.nextId)
end
local function metadata(object) return object and object.getTable("memory") or nil end
local function member(s, role)
    local object = obj(s.refs[role])
    local m = metadata(object)
    local roleMatches=m and (m.role==role or (m.role=="baseModel" and (role=="base" or role=="model")))
    if roleMatches and m.instanceId == s.instanceId and m.cardGUID == s.cardGUID then return object end
    return nil
end
local function commit(s)
    local card = obj(s.cardGUID)
    if card then card.call("STA2E_SetMemory", copy(s)) end
end
local function maneuverReference(id)
    return CATALOG_DATA.maneuverReferences and CATALOG_DATA.maneuverReferences[id] or nil
end
local function complete(s)
    return member(s,"base") and member(s,"model") and member(s,"dial") and (not maneuverReference(s.definitionId) or member(s,"reference"))
end
local ACTION_KEYS={evade="EVA",scan="SCN",battlestations="BS",["target-lock"]="TL",cloak="CLK",["sensor-echo"]="ECHO",regenerate="REG"}
local function definition(id)
    local ship=SHIP_DEFINITIONS[id]
    return ship and SHIP_DATA.classes[ship.profile] or nil,ship
end
local function capabilities(id)
    local class,ship=definition(id);local actions={}
    for _,name in ipairs(ship and ship.actions or {}) do if ACTION_KEYS[name] then table.insert(actions,ACTION_KEYS[name]) end end
    return {dialId=ship and ship.class or "Unknown",actions=actions,arcs=class and {class.arc} or {},prototype=ship==nil}
end
local ALL_ACTION_CHOICES={"EVA","BS","TL","SCN","CLK","REG","ECHO"}
local function actionChoices(s)
    local actions={}
    for _,key in ipairs(ALL_ACTION_CHOICES) do table.insert(actions,key) end
    return actions
end
local function dialFor(s) local class=definition(s.definitionId);return class and class.dial or GALAXY_DIAL end
local function shipFor(object)
    local m = metadata(object)
    if not m then return nil end
    local s = STA2E.ships[m.instanceId]
    if not s then return nil end
    if m.role == "card" then
        if s.cardGUID == object.getGUID() then return s end
    elseif m.role=="baseModel" then
        if member(s,"base")==object then return s end
    elseif member(s, m.role) == object then return s end
    return nil
end
local function button(id, text, x, y, color)
    return '<Button id="'..id..'" onClick="STA2E_UI" position="'..x..' '..y..' 0" width="205" height="50" fontSize="18" color="'..(color or '#284A66')..'">'..xml(text)..'</Button>'
end
local MANEUVER_FAMILY_ORDER={TL=1,BL=2,S=3,BR=4,TR=5,CA=6,FAL=7,FAR=7,IRL=8,IRR=8,R=9,GENERAL=10,ECO=11,BORG=12,STATION=13}
local function maneuverDisplayName(key,fallback)
    local echoSide,echoSpeed,echoPosition=tostring(key or ""):match("^Eco([LR])(%d+)_([FSB])$")
    if echoSide then
        local positionName=({F="Forward",S="Lateral",B="Back"})[echoPosition]
        return "Evasive "..(echoSide=="L" and "Left " or "Right ")..echoSpeed.." — "..positionName
    end
    local prefix,speed=tostring(key or ""):match("^([A-Za-z]+)(%d+)$")
    local n=tonumber(speed)
    local general={R180="Rotate 180°",R90L="Rotate 90° Left",R90R="Rotate 90° Right"}
    if general[key] then return general[key] end
    local common={TL="Left Turn",BL="Left Bank",S="Straight",BR="Right Bank",TR="Right Turn",CA="Come About",FAL="Full About Left",FAR="Full About Right",IRL="Impulse Roll Left",IRR="Impulse Roll Right",R="Reverse"}
    if common[prefix] then return common[prefix]..(n and (" "..n) or "") end
    if prefix=="GL" or prefix=="GR" then return "Borg "..(prefix=="GL" and "L" or "R")..tostring(n or "") end
    if prefix=="SL" or prefix=="SR" then return "Borg Spin "..(prefix=="SL" and "Left " or "Right ")..tostring(n or "") end
    if prefix=="EcoL" or prefix=="EcoR" then return "Evasive "..(prefix=="EcoL" and "Left " or "Right ")..tostring(n or "") end
    local station={STOP0="Station Stop",ROTL0="Station Rotate Left",ROTR0="Station Rotate Right",PIVOTL0="Station Pivot Left",PIVOTR0="Station Pivot Right",DL1="Station Drift Left 1",DR1="Station Drift Right 1",DL2="Station Drift Left 2",DR2="Station Drift Right 2"}
    return station[key] or general[key] or fallback or tostring(key or "Unknown")
end
local function maneuverFamily(key)
    local prefix=tostring(key or ""):match("^([A-Za-z]+)") or ""
    if prefix=="TL" or prefix=="BL" or prefix=="S" or prefix=="BR" or prefix=="TR" or prefix=="CA" or prefix=="FAL" or prefix=="FAR" or prefix=="IRL" or prefix=="IRR" or (prefix=="R" and key~="R180") then return MANEUVER_FAMILY_ORDER[prefix] end
    if prefix:match("^Eco") then return MANEUVER_FAMILY_ORDER.ECO end
    if prefix=="GL" or prefix=="GR" or prefix=="SL" or prefix=="SR" then return MANEUVER_FAMILY_ORDER.BORG end
    if prefix=="STOP" or prefix=="ROTL" or prefix=="ROTR" or prefix=="PIVOTL" or prefix=="PIVOTR" or prefix=="DL" or prefix=="DR" then return MANEUVER_FAMILY_ORDER.STATION end
    return MANEUVER_FAMILY_ORDER.GENERAL
end
local function orderedManeuvers(values)
    local result={}
    for _,value in ipairs(values or {}) do table.insert(result,value) end
    table.sort(result,function(a,b)
        local ak=type(a)=="table" and a.key or a
        local bk=type(b)=="table" and b.key or b
        local af,bf=maneuverFamily(ak),maneuverFamily(bk)
        if af~=bf then return af<bf end
        local as=tonumber(tostring(ak):match("(%d+)$")) or 0
        local bs=tonumber(tostring(bk):match("(%d+)$")) or 0
        if as~=bs then return as<bs end
        return tostring(ak)<tostring(bk)
    end)
    return result
end
local function maneuverLabel(s,key)
    local entry=maneuver and maneuver(s,key) or nil
    if entry then return maneuverDisplayName(key,entry.label) end
    for _,candidate in ipairs(dialFor(s)) do if candidate.key==key then return maneuverDisplayName(key,candidate.label) end end
    return key and maneuverDisplayName(key,key) or "No maneuver selected"
end
-- Object XML tooltips rotate with the dial. Display hover help in the flat HUD.
STA2E.DialHover={objects={},players={},colors={"White","Brown","Red","Orange","Yellow","Green","Teal","Blue","Purple","Pink","Grey","Black"}}
function STA2E.DialHover.clear(guid)
    for color,row in pairs(STA2E.DialHover.players) do
        if not guid or row.guid==guid then
            STA2E.DialHover.players[color]=nil
            UI.setAttribute("sta2e_hover_"..color,"active","false")
        end
    end
end
function STA2E.DialHover.decode(value)
    return tostring(value or ""):gsub("&quot;",'"'):gsub("&apos;","'"):gsub("&lt;","<"):gsub("&gt;",">"):gsub("&amp;","&")
end
function STA2E.DialHover.allowed(restrictions,color)
    for _,targets in ipairs(restrictions) do
        local match=false
        for target in targets:gmatch("[^|]+") do if target==color then match=true end end
        if not match then return false end
    end
    return true
end
function STA2E.DialHover.find(guid,id,color)
    local registry=STA2E.DialHover.objects[guid]
    for _,button in ipairs(registry and registry.buttons[id] or {}) do
        if STA2E.DialHover.allowed(button.restrictions,color) then return button,registry end
    end
end
function STA2E.DialHover.panels()
    local parts={}
    for _,color in ipairs(STA2E.DialHover.colors) do
        local row=STA2E.DialHover.players[color]
        local shown=row and row.shown==true
        table.insert(parts,'<Panel id="sta2e_hover_'..color..'" visibility="'..color..'" active="'..tostring(shown==true)..'" rectAlignment="LowerCenter" offsetXY="0 110" width="560" height="72" color="#D9D9D9E8" raycastTarget="false">'..
            '<Panel width="558" height="70" color="#111111F5" raycastTarget="false">'..
            '<Text id="sta2e_hover_text_'..color..'" text="'..xml(shown and row.text or "")..'" width="532" height="58" fontSize="18" alignment="MiddleCenter" horizontalOverflow="Wrap" verticalOverflow="Truncate" color="#FFFFFF" raycastTarget="false"/>'..
            '</Panel></Panel>')
    end
    return table.concat(parts)
end
function STA2E_SetDialXml(dial,markup)
    local guid=dial.getGUID()
    STA2E.DialHover.clear(guid)
    local registry={buttons={}}
    STA2E.DialHover.objects[guid]=registry
    -- Track parent visibility so a hover never exposes another player's controls.
    local panels={}
    for closing,tag,attributes in markup:gmatch('<(/?)([%w]+)([^>]*)>') do
        if tag=="Panel" then
            if closing=="/" then table.remove(panels)
            elseif not attributes:match('/%s*$') then panels[#panels+1]=attributes:match('visibility="([^"]+)"') or "" end
        elseif tag=="Button" and closing=="" then
            local id=attributes:match('id="([^"]+)"')
            local help=attributes:match('tooltip="([^"]*)"')
            if id and help and help~="" then
                local restrictions={}
                for _,targets in ipairs(panels) do if targets~="" then restrictions[#restrictions+1]=targets end end
                local ownTargets=attributes:match('visibility="([^"]+)"')
                if ownTargets then restrictions[#restrictions+1]=ownTargets end
                registry.buttons[id]=registry.buttons[id] or {}
                table.insert(registry.buttons[id],{text=STA2E.DialHover.decode(help),restrictions=restrictions})
            end
        end
    end
    markup=markup:gsub('<Button%s+([^>]+)>',function(attributes)
        if not attributes:find('tooltip="',1,true) then return '<Button '..attributes..'>' end
        attributes=attributes:gsub('%s+tooltip="[^"]*"',"")
        return '<Button '..attributes..' onMouseEnter="STA2E_DialHoverEnter" onMouseExit="STA2E_DialHoverExit" onMouseDown="STA2E_DialHoverExit">'
    end)
    dial.UI.setXml(markup)
end
function STA2E_DialHover(params)
    local object=params and params.object
    local color=params and params.color
    if not object or not color then return end
    local guid=object.getGUID()
    if params.enter~=true then
        local row=STA2E.DialHover.players[color]
        if row and row.guid==guid and row.id==params.id then
            STA2E.DialHover.players[color]=nil;UI.setAttribute("sta2e_hover_"..color,"active","false")
        end
        return
    end
    local button,registry=STA2E.DialHover.find(guid,params.id,color)
    if not button then return end
    local row={guid=guid,id=params.id,text=button.text,registry=registry}
    STA2E.DialHover.players[color]=row
    UI.setAttribute("sta2e_hover_"..color,"active","false")
    hud()
    Wait.time(function()
        if STA2E.DialHover.players[color]~=row or not obj(guid) or STA2E.DialHover.objects[guid]~=registry then return end
        row.shown=true
        UI.setAttribute("sta2e_hover_text_"..color,"text",row.text)
        UI.setAttribute("sta2e_hover_"..color,"active","true")
    end,0.35)
end

local function dialButtonTooltip(id,text)
    local descriptions={
        lock="Lock in your selected maneuver for this round.",
        change="Unlock your maneuver so you can choose another during Planning.",
        reveal="Reveal your selected maneuver to all players.",
        move="Execute the revealed maneuver and move this ship.",
        modify_toggle="Open the maneuver modifier to choose a template or adjust speed.",
        undo="Undo this ship's most recent movement this round.",
        finish="Finish this ship's activation without taking another action.",
        tool_home=text=="BACK" and "Return to the main ship tools menu." or "Open this ship's tools and manual controls.",
        tool_moves="Choose an immediate maneuver without changing the planned maneuver.",
        tool_tokens="Open the action and status token menu for this ship.",
        tool_damage="Open damage tools and the critical token control.",
        tool_arcs="Open range guides, firing arcs, and ship measurements.",
        tool_undo="Undo this ship's most recent movement this round.",
        tool_phase="Return to this ship's controls for the current game phase.",
        tool_prev="Show the previous page of immediate maneuvers.",
        tool_next="Show the next page of immediate maneuvers.",
        tool_arc_toggle=text=="HIDE ARCS" and "Hide this ship's firing arc guides." or "Show this ship's firing arc guides.",
        tool_clear_guides="Hide this ship's range and firing arc guides.",
        tool_measure="Report distances and firing arcs between ships.",
        card_close="Close the ship card's action and token menu.",
        card_echo="Open Sensor Echo movement choices for this ship.",
        ai_engage="Set the AI intent to Engage, then Evaluate to choose a maneuver.",
        ai_chase="Set the AI intent to Chase, then Evaluate to choose a maneuver.",
        ai_escape="Set the AI intent to Escape, then Evaluate to choose a maneuver.",
        ai_evaluate="Evaluate the current situation and choose an AI maneuver.",
        ai_execute="Execute the evaluated AI maneuver during Activation.",
        ai_auto="Let the AI determine the toward direction automatically.",
        ai_port="Set the AI toward direction to port (left).",
        ai_starboard="Set the AI toward direction to starboard (right).",
        ai_finish="Finish this AI ship's activation after executing its maneuver.",
        ai_undo="Undo this AI ship's most recent movement this round.",
        ai_aux="Add an Auxiliary Power token to this ship.",
        ai_side="Switch this AI ship between the allied and enemy sides.",
        ai_toggle="Return this ship to player control.",
        modify_restore="Restore the originally revealed maneuver.",
        modify_down="Reduce the maneuver's speed by one where supported.",
        modify_up="Increase the maneuver's speed by one where supported.",
        modify_close="Close the maneuver modifier.",
    }
    if descriptions[id] then return descriptions[id] end
    local key=id:match("^select_(.+)$")
    if key then return "Select "..maneuverDisplayName(key,key).." as your planned maneuver." end
    key=id:match("^tool_move_(.+)$")
    if key then return "Execute "..maneuverDisplayName(key,key).." immediately; keep the planned maneuver." end
    key=id:match("^modify_(.+)$")
    if key then return "Change the revealed maneuver to "..maneuverDisplayName(key,key).."." end
    local range=id:match("^tool_range_([123])$")
    if range then return "Show range guides from this ship out to Range "..range.."." end
    local tokenNames={EVA="Evade",SCN="Scan",BS="Battle Stations",TL="Target Lock",CLK="Cloak",REG="Regenerate",AUX="Auxiliary Power",SHIELD="Shield",TIME="Time",DISABLED="Disabled",CRIT="Critical Hit",DRONE="Drone",MISSION="Mission",REINFORCE="Reinforce",LATINUM="Latinum",ECHO="Sensor Echo"}
    key=id:match("^tool_token_(.+)$") or id:match("^card_token_(.+)$")
    if key then return "Add a "..(tokenNames[key] or key).." token for this ship." end
    key=id:match("^action_(.+)$") or id:match("^ai_action_(.+)$")
    if key then
        if key=="ECHO" then return "Open Sensor Echo movement choices for this ship." end
        return "Perform the "..(tokenNames[key] or key).." action for this ship."
    end
    return tostring(text or id)
end

local function dialButton(id,text,x,y,color,width,tooltip)
    text=STA2E_Playtest.actionLabel(id,text)
    return '<Button id="'..id..'" onClick="STA2E_UI" tooltip="'..xml(tooltip or dialButtonTooltip(id,text))..'" position="'..x..' '..y..' 0" width="'..(width or 205)..'" height="50" fontSize="18" color="'..(color or '#284A66')..'">'..xml(text)..'</Button>'
end

local function publicVisibility(owner,s)
    local visible={"Grey","White","Brown","Teal","Pink"}
    if not s or not STA2E_Playtest.canManage(s,"Black") then table.insert(visible,"Black") end
    for _,color in ipairs(PLAYER_COLORS) do if color~=owner and not (s and STA2E_Playtest.canManage(s,color)) then table.insert(visible,color) end end
    return table.concat(visible,"|")
end
local function render(s)
    local dial=member(s,"dial")
    if dial then
        local state=s.state.status or "planning"
        local chosen=maneuverLabel(s,s.state.maneuver)
        local private={'<Panel '..((state=="planning" or state=="locked") and ('visibility="'..STA2E_Playtest.visibility(s)..'" ') or "")..'width="700" height="820" color="#102432F2">',
            '<Text text="'..xml(s.name)..'" position="0 375 0" width="680" height="35" fontSize="24"/>'}
        if state=="planning" then
            table.insert(private,'<Text text="PLAN MANEUVER" position="0 335 0" width="680" height="32" fontSize="18"/>')
            table.insert(private,'<Text text="'..xml(chosen)..'" position="0 300 0" width="680" height="32" fontSize="20" color="#FFD86B"/>')
            local ordered=orderedManeuvers(dialFor(s))
            local commonColumns={{prefix="TL",label="LEFT TURN",x=-240},{prefix="BL",label="LEFT BANK",x=-120},{prefix="S",label="STRAIGHT",x=0},{prefix="BR",label="RIGHT BANK",x=120},{prefix="TR",label="RIGHT TURN",x=240}}
            local common={}
            local special={}
            for _,move in ipairs(ordered) do
                local prefix=move.key:match("^([A-Z]+)")
                if prefix=="TL" or prefix=="BL" or prefix=="S" or prefix=="BR" or prefix=="TR" then common[move.key]=move
                else table.insert(special,move) end
            end
            table.insert(private,'<Text text="SPEED" position="-323 250 0" width="65" height="28" fontSize="13" color="#C8D9E8"/>')
            for _,column in ipairs(commonColumns) do
                table.insert(private,'<Text text="'..column.label..'" position="'..column.x..' 250 0" width="112" height="28" fontSize="12" color="#C8D9E8"/>')
            end
            for speed=6,1,-1 do
                local y=198-(6-speed)*47
                table.insert(private,'<Text text="'..speed..'" position="-323 '..y..' 0" width="55" height="38" fontSize="18" color="#FFFFFF"/>')
                for _,column in ipairs(commonColumns) do
                    local move=common[column.prefix..speed]
                    if move then
                        local shade=({green="#256348",white="#526777",red="#863B3B"})[move.difficulty] or "#526777"
                        if move.key==s.state.maneuver then shade="#C69A2B" end
                        table.insert(private,dialButton("select_"..move.key,tostring(speed),column.x,y,shade,108,"Select "..maneuverDisplayName(move.key,move.label).." ("..tostring(move.difficulty or "white")..")."))
                    end
                end
            end
            table.insert(private,'<Text text="SPECIAL MANEUVERS" position="0 -88 0" width="650" height="25" fontSize="14" color="#C8D9E8"/>')
            for i,move in ipairs(special) do
                local column=(i-1)%5
                local row=math.floor((i-1)/5)
                local x=-240+column*120
                local y=-128-row*49
                local shade=({green="#256348",white="#526777",red="#863B3B"})[move.difficulty] or "#526777"
                if move.key==s.state.maneuver then shade="#C69A2B" end
                table.insert(private,dialButton("select_"..move.key,maneuverDisplayName(move.key,move.label),x,y,shade,112,"Select "..maneuverDisplayName(move.key,move.label).." ("..tostring(move.difficulty or "white")..")."))
            end
            table.insert(private,dialButton("lock","LOCK MANEUVER",0,-260,"#256348",430))
        elseif state=="locked" then
            table.insert(private,'<Text text="MANEUVER LOCKED" position="0 330 0" width="680" height="32" fontSize="18"/>')
            table.insert(private,'<Text text="'..xml(chosen)..'" position="0 280 0" width="680" height="45" fontSize="28" color="#FFD86B"/>')
            if STA2E.game.phase=="planning" then table.insert(private,dialButton("change","CHANGE MANEUVER",0,205,"#526777",430))
            else table.insert(private,dialButton("reveal","REVEAL MANEUVER",0,205,"#9A792B",430)) end
        elseif state=="revealed" then
            table.insert(private,'<Text text="REVEALED: '..xml(chosen)..'" position="0 315 0" width="680" height="45" fontSize="27" color="#FFD86B"/>')
            table.insert(private,dialButton("move","EXECUTE",-115,225,"#256348",205))
            table.insert(private,dialButton("modify_toggle","MODIFY MANEUVER",115,225,"#9A792B",205))
        elseif state=="action" then
            table.insert(private,'<Text text="'..xml(chosen)..' EXECUTED" position="0 330 0" width="680" height="38" fontSize="23"/>')
            table.insert(private,'<Text text="PERFORM ACTION" position="0 285 0" width="680" height="35" fontSize="20" color="#FFD86B"/>')
            for i,key in ipairs(actionChoices(s)) do table.insert(private,dialButton("action_"..key,key,((i-1)%2==0 and -115 or 115),210-math.floor((i-1)/2)*62,"#284A66")) end
            table.insert(private,dialButton("undo","UNDO MOVEMENT",-115,-65,"#526777"))
            table.insert(private,dialButton("finish","SKIP / FINISH",115,-65,"#863B3B"))
        else
            table.insert(private,'<Text text="ACTIVATION COMPLETE" position="0 320 0" width="680" height="40" fontSize="24"/>')
            table.insert(private,'<Text text="'..xml(chosen)..'" position="0 270 0" width="680" height="35" fontSize="20"/>')
        end
        table.insert(private,dialButton("quick_range","RANGE",-175,-350,"#375A78",300))
        table.insert(private,dialButton("tool_home","SHIP TOOLS",175,-350,"#375A78",300))
        table.insert(private,'</Panel>')
        local publicState=(state=="planning" and "PLANNING") or (state=="locked" and "MANEUVER ASSIGNED") or (state=="revealed" and ("REVEALED: "..chosen)) or (state=="action" and (chosen.." EXECUTED · ACTION")) or (chosen.." · COMPLETE")
        if state=="planning" or state=="locked" then
        table.insert(private,'<Panel visibility="'..publicVisibility(s.owner,s)..'" width="620" height="240" color="#102432F2"><Text text="'..xml(s.name)..'" position="0 45 0" width="600" height="35" fontSize="24"/><Text text="'..xml(publicState)..'" position="0 -10 0" width="600" height="40" fontSize="21"/><Button id="tool_home" onClick="STA2E_UI" tooltip="Open this ship&apos;s tools and manual controls." position="0 -80 0" width="340" height="36" fontSize="16">SHIP CONTROLS</Button></Panel>')
        end
        -- Object XML uses canvas coordinates, not physical-button coordinates.
        -- Keep the canvas plane unrotated; lift in canvas Z, not world Y.
        local markup=table.concat(private)
        markup=defaultXmlAttribute(markup,"Text","color","#FFFFFF")
        markup=defaultXmlAttribute(markup,"Button","textColor","#FFFFFF")
        local root='<Panel id="sta2e_dashboard" width="700" height="820" position="0 0 -120" rotation="0 0 180" scale="0.4 0.4 1" color="#00000000" raycastTarget="false">'
        STA2E_SetDialXml(dial,s.state.dialOpen==true and (root..markup..'</Panel>') or "")
        if dial.call then dial.call("STA2E_SetDisplay",{dialOpen=s.state.dialOpen==true,status=state,maneuver=s.state.maneuver}) end
    end
    local card=obj(s.cardGUID)
    if card then card.UI.setXml("") end
end
local function refresh(s)
    if STA2E.loading and STA2E.startupRefreshQueue and not STA2E.startupFlushing then
        STA2E.startupRefreshQueue[s.instanceId]=s
        return
    end
    commit(s);render(s)
end
local function sync(s)
    local base, model = member(s,"base"),member(s,"model")
    if not base or not model then return end
    if base.getGUID()==model.getGUID() then return end
    local p, r = base.getPosition(),base.getRotation()
    local ship=SHIP_DEFINITIONS[s.definitionId]
    model.setPosition({p.x,p.y+(ship and ship.model.offsetY or -1.2),p.z}); model.setRotation({r.x,r.y,r.z})
end
function STA2E_Register(params)
    if not STA2E.ready and not (STA2E.startupRegistering and STA2E.startupThread and coroutine.running()==STA2E.startupThread) then return end
    local object = params.object
    local m = metadata(object)
    if not m or m.schemaVersion ~= 1 then return end
    if m.role == "card" then
        if not own(m.owner) or not CATALOG[m.definitionId] or CATALOG[m.definitionId].type~="ship" then return end
        local guid = object.getGUID()
        local existing = m.instanceId and STA2E.ships[m.instanceId]
        -- Keep the same runtime record while asynchronous deployment callbacks hold it.
        if existing and existing.cardGUID==guid then if not STA2E.reconciling then render(existing) end;return end
        -- Copied cards must never inherit another card's component references.
        if (m.cardGUID and m.cardGUID ~= guid) or not m.instanceId then
            m.instanceId = nextId(); m.refs = {}; m.upgrades = {}; m.fleetId = "copy-"..m.instanceId
            m.state = {status="planning"}; m.deployedOnce = false
        end
        m.cardGUID=guid; m.refs=m.refs or {}; m.upgrades=m.upgrades or {}; m.state=m.state or {status="planning"}
        m.capabilities=capabilities(m.definitionId)
        STA2E.ships[m.instanceId] = m
        if not STA2E.reconciling then refresh(m) end
    elseif not STA2E.reconciling and m.instanceId and STA2E.ships[m.instanceId] then
        render(STA2E.ships[m.instanceId])
    end
end
function STA2E_Reconcile()
    -- One snapshot and one metadata read per object, including missing references.
    local roots, components = {}, {}
    STA2E.reconciling=true
    for _,object in ipairs(getAllObjects()) do
        local m=metadata(object)
        if m and m.role=="pending" and m.transaction then object.destruct()
        elseif m then
            if m.role=="card" then table.insert(roots,object) end
            if m.instanceId and m.cardGUID then
                components[m.instanceId]=components[m.instanceId] or {}
                local byCard=components[m.instanceId]
                byCard[m.cardGUID]=byCard[m.cardGUID] or {}
                local byRole=byCard[m.cardGUID]
                local roles=m.role=="baseModel" and {"base","model"} or {m.role}
                for _,role in ipairs(roles) do
                    byRole[role]=byRole[role] or {}
                    table.insert(byRole[role],object)
                end
            end
        end
        STA2E_StartupYield("objects")
    end
    for _,object in ipairs(roots) do STA2E_Register({object=object});STA2E_StartupYield("registered") end
    for _,s in pairs(STA2E.ships) do
        s.conflicts={}
        local byCard=components[s.instanceId] or {}
        local byRole=byCard[s.cardGUID] or {}
        for _,role in ipairs({"base","model","dial","reference"}) do
            if not member(s,role) then
                local candidates=byRole[role] or {}
                if #candidates==1 then s.refs[role]=candidates[1].getGUID()
                else s.refs[role]=nil;if #candidates>1 then s.conflicts[role]=true end end
            end
        end
        sync(s);refresh(s);STA2E_StartupYield("linked")
    end
    STA2E.reconciling=false
end
local function primitive(name, scale, tint)
    return {Name="BlockSquare",Nickname=name,Transform={posX=0,posY=2,posZ=0,rotX=0,rotY=0,rotZ=0,scaleX=scale[1],scaleY=scale[2],scaleZ=scale[3]},ColorDiffuse={r=tint[1],g=tint[2],b=tint[3]},Locked=false,Grid=false,Snap=false}
end
