local function STA2E_BaseTexture(owner,arc,large,ai)
    if ai then
        if arc=="360" then return ALLIANCE_AI_BASE_TEXTURES["360"] end
        if arc=="90+rear90" then return ALLIANCE_AI_BASE_TEXTURES["90+rear90"] end
        if arc=="180+rear90" then return ALLIANCE_AI_BASE_TEXTURES["180+rear90"] end
        if tostring(arc or ""):match("^180") then return ALLIANCE_AI_BASE_TEXTURES["180"] end
        return ALLIANCE_AI_BASE_TEXTURES["90"]
    end
    local set=ARC_BASE_TEXTURES[owner]
    if set and set[arc] then return set[arc] end
    if arc=="360" then return BORG_BASE_TEXTURES[owner] end
    return (large and LARGE_BASE_TEXTURES[owner]) or PLAYER_BASE_TEXTURES[owner]
end
local function playerSideTransform(owner,anchor,offset)
    offset=offset or {}
    local board=obj(FLEET_STAGING_BOARD_GUID)
    if board then
        -- The staging-board orientation is authoritative. Hand zones only
        -- determine ownership and may be moved without shifting fleet layouts.
        local yaw=board.getRotation().y
        local angle=math.rad(yaw)
        local forwardX,forwardZ=-math.sin(angle),-math.cos(angle)
        local rightX,rightZ=math.cos(angle),-math.sin(angle)
        return {position={x=anchor.x+rightX*(offset.side or 0)+forwardX*(offset.forward or 0),y=anchor.y+(offset.up or 0),z=anchor.z+rightZ*(offset.side or 0)+forwardZ*(offset.forward or 0)},rotation={0,yaw,0},facing=yaw,side=1}
    end
    local side=owner=="Blue" and 1 or -1
    return {position={x=anchor.x+side*(offset.side or 0),y=anchor.y+(offset.up or 0),z=anchor.z+side*(offset.forward or 0)},rotation={0,owner=="Blue" and 0 or 180,0},side=side}
end
STA2E.PlayerTransform=playerSideTransform
local function deploy(s)
    local class,ship=definition(s.definitionId)
    if s.physicalReady==false or not class or not ship then return "Cards are ready. This ship does not have a physical definition yet." end
    if not s.deployedOnce then s.state.dialOpen=true end
    if not s.state.maneuver and STA2E.game.phase~="planning" then s.state.status="neutral";s.state.toolsPage="home" end
    if STA2E.pending[s.instanceId] then return "Deployment is already running." end
    if s.conflicts and next(s.conflicts) then return "Duplicate component identities found. Remove the unwanted copies and reload before repair." end
    if complete(s) then sync(s);render(s);return "Ship is already deployed." end
    local missing={}
    if ship.integratedBase then
        if not member(s,"base") then table.insert(missing,"baseModel") end
    else
        for _,role in ipairs({"base","model"}) do if not member(s,role) then table.insert(missing,role) end end
    end
    if not member(s,"dial") then table.insert(missing,"dial") end
    if maneuverReference(s.definitionId) and not member(s,"reference") then table.insert(missing,"reference") end
    local card=obj(s.cardGUID)
    if not card then return "Ship card is missing." end
    local p=card.getPosition()
    local sign=s.owner=="Blue" and 1 or -1
    local base=member(s,"base")
    local bp=base and base.getPosition() or s.spawnPosition or {x=p.x,y=1.3,z=sign*12}
    s.spawnPosition={x=bp.x,y=bp.y,z=bp.z}
    local ticket={left=#missing}
    local isLargeBase=class.base=="large"
    STA2E.pending[s.instanceId]=ticket
    for _,roleValue in ipairs(missing) do
        local role=roleValue
        local data
        if role=="baseModel" then local integrated=ship.integratedBase;data={Name="Custom_Model",Nickname=s.name,Description=s.definitionId,Transform={posX=0,posY=2,posZ=0,rotX=0,rotY=0,rotZ=0,scaleX=integrated.scale[1],scaleY=integrated.scale[2],scaleZ=integrated.scale[3]},ColorDiffuse={r=1,g=1,b=1},Locked=false,Grid=false,Snap=false,CustomMesh={MeshURL=integrated.mesh,DiffuseURL=(integrated.diffuseByOwner and integrated.diffuseByOwner[s.owner]) or integrated.diffuse,NormalURL=integrated.normal or "",ColliderURL=integrated.collider,Convex=integrated.convex,MaterialIndex=integrated.material,TypeIndex=integrated.type,CustomShader=integrated.shader or {SpecularColor={r=0.87,g=0.81,b=0.75},SpecularIntensity=0,SpecularSharpness=3,FresnelStrength=0.1},CastShadows=integrated.castShadows~=false}}
        elseif role=="base" then
            data=copy(isLargeBase and LARGE_BASE or STANDARD_BASE)
            data.Nickname=s.name.." Base"
            data.Transform.scaleX=isLargeBase and 2.3 or 1.174999
            data.Transform.scaleZ=isLargeBase and 2.3 or 1.174999
            data.Tags={"ship",isLargeBase and "Large" or "Small"}
            data.CustomMesh.DiffuseURL=STA2E_BaseTexture(s.owner,class.arc,isLargeBase,s.ai~=nil) or class.baseTexture
        elseif role=="model" then data={Name="Custom_Model",Nickname=s.name,Description=s.definitionId,Transform={posX=0,posY=2,posZ=0,rotX=0,rotY=0,rotZ=0,scaleX=ship.model.scale[1],scaleY=ship.model.scale[2],scaleZ=ship.model.scale[3]},ColorDiffuse={r=1,g=1,b=1},Locked=true,Grid=false,Snap=false,CustomMesh={MeshURL=ship.model.mesh,DiffuseURL=(ship.model.diffuseByOwner and ship.model.diffuseByOwner[s.owner]) or ship.model.diffuse,NormalURL=ship.model.normal or "",ColliderURL=ship.model.collider,Convex=ship.model.convex,MaterialIndex=ship.model.material,TypeIndex=ship.model.type,CustomShader=ship.model.shader or {SpecularColor={r=0.87,g=0.81,b=0.75},SpecularIntensity=0,SpecularSharpness=3,FresnelStrength=0.1},CastShadows=ship.model.castShadows~=false}}
        elseif role=="dial" then data={Name="Custom_Tile",Nickname=s.name.." Dial",Description=s.definitionId,Transform={posX=0,posY=1.5,posZ=0,rotX=0,rotY=180,rotZ=0,scaleX=1,scaleY=1,scaleZ=1},ColorDiffuse={r=1,g=1,b=1},Locked=false,Grid=false,Snap=false,CustomImage={ImageURL="https://steamusercontent-a.akamaihd.net/ugc/2262557817130200206/51C06856AA96E8D0C03E27D19478F4C5EEF0D8F8/",ImageSecondaryURL="https://steamusercontent-a.akamaihd.net/ugc/2262557817130200966/1EFF15C23CE48FA914F5DEE9DCE5EE77D00BAF94/",ImageScalar=1,WidthScale=0,CustomTile={Type=2,Thickness=0.12,Stackable=false,Stretch=true}}}
        else local reference=maneuverReference(s.definitionId);data={Name="Custom_Tile",Nickname=s.name.." Maneuver Reference",Description=reference.name,Transform={posX=0,posY=1.2,posZ=0,rotX=0,rotY=0,rotZ=0,scaleX=1,scaleY=1,scaleZ=1},ColorDiffuse={r=1,g=1,b=1},Locked=false,Grid=false,Snap=false,CustomImage={ImageURL=reference.image,ImageSecondaryURL=reference.back or reference.image,ImageScalar=1,WidthScale=0,CustomTile={Type=0,Thickness=0.08,Stackable=false,Stretch=true}}} end
        data.LuaScript=MEMBER_SCRIPT
        data.LuaScriptState=JSON.encode({schemaVersion=1,role=role,instanceId=s.instanceId,cardGUID=s.cardGUID})
        local dialTransform=playerSideTransform(s.owner,p,{side=6.0,forward=0.1,up=0.3})
        local referenceTransform=playerSideTransform(s.owner,p,{side=3.15,up=0.15})
        local position=role=="dial" and dialTransform.position or role=="reference" and referenceTransform.position or {bp.x,bp.y+(role=="model" and ship.model.offsetY or 0),bp.z}
        local rotation=role=="dial" and dialTransform.rotation or role=="reference" and referenceTransform.rotation or {0,(s.spawnRotation or (sign==1 and 0 or 180)),0}
        local ok,err=pcall(function()
            spawnObjectData({data=data,position=position,rotation=rotation,callback_function=function(object)
                if STA2E.pending[s.instanceId]~=ticket or not obj(s.cardGUID) then object.destruct();return end
                object.call("STA2E_SetMemory",{schemaVersion=1,role=role,instanceId=s.instanceId,cardGUID=s.cardGUID})
                if role=="baseModel" then s.refs.base=object.getGUID();s.refs.model=object.getGUID() else s.refs[role]=object.getGUID() end
                if role=="base" then
                    local scale=object.getScale()
                    local footprintScale=isLargeBase and 2.3 or 1.174999
                    object.setScale({footprintScale,scale.y,footprintScale})
                end
                if role=="model" then object.interactable=false;object.setLock(true) end
                ticket.left=ticket.left-1
                if ticket.left==0 then STA2E.pending[s.instanceId]=nil;s.deployedOnce=true;STA2E_FollowModel(s) end
                refresh(s)
            end})
        end)
        if not ok then tell(s.owner,"Component spawn failed: "..tostring(err)) end
        STA2E_StartupYield("componentRequests")
    end
    Wait.time(function()
        if STA2E.pending[s.instanceId]==ticket then STA2E.pending[s.instanceId]=nil;STA2E_Reconcile();tell(s.owner,"Deployment timed out. Any recovered components were relinked; use Deploy / Repair for missing parts.") end
    end,15)
    return "Deploying missing components."
end
local function maneuver(s,key)
    for _,entry in ipairs(dialFor(s)) do if entry.key==key then return entry end end
    return nil
end
