local ALLIANCE_SHIP_CARDS=ALLIANCE_SHIP_CARD_DATA.cards or {}
local ALLIANCE_SHIP_CARDS_BY_CLASS={}
for id,card in pairs(ALLIANCE_SHIP_CARDS) do
    local className=tostring(card.className or "Alliance Ship")
    ALLIANCE_SHIP_CARDS_BY_CLASS[className]=ALLIANCE_SHIP_CARDS_BY_CLASS[className] or {}
    table.insert(ALLIANCE_SHIP_CARDS_BY_CLASS[className],tostring(id))
end
for _,ids in pairs(ALLIANCE_SHIP_CARDS_BY_CLASS) do table.sort(ids) end
local ALLIANCE_SPAWN_POINTS={
    {position={-17.46,1.3,-6.04},rotation=270},
    {position={17.46,1.3,-6.04},rotation=90},
    {position={-6.10,1.3,17.50},rotation=0},
    {position={6.10,1.3,17.50},rotation=0},
    {position={17.46,1.3,5.95},rotation=90},
    {position={-17.46,1.3,5.95},rotation=270},
}
local ALLIANCE_CARD_SLOTS={}
-- Use the full Alliance staging strip beside the table. Four columns keep the
-- common four-ship setup on one row, while three generously spaced rows leave
-- room for each ship's dial and maneuver reference without stacking them.
for _,z in ipairs({-12.5,4.0,20.5}) do
    for _,x in ipairs({23.0,30.5,38.0,45.5}) do
        table.insert(ALLIANCE_CARD_SLOTS,{x,1.2,z})
    end
end

local function allianceState() return STA2E.game and STA2E.game.alliance or nil end
local function alliancePosition(value)
    local p=value.position or value
    return {x=p.x or p[1],y=p.y or p[2] or 1.3,z=p.z or p[3]}
end
local function allianceBlocked(position)
    for _,s in pairs(STA2E.ships) do
        local base=member(s,"base")
        if base then
            local p=base.getPosition()
            if (p.x-position.x)^2+(p.z-position.z)^2<10.25 then return true end
        end
    end
    for _,object in ipairs(getAllObjects()) do
        local name=string.lower((object.getName and object.getName()) or "")
        if name:find("planet",1,true) or name:find("asteroid",1,true) or name:find("obstacle",1,true) then
            local p=object.getPosition()
            if (p.x-position.x)^2+(p.z-position.z)^2<12.25 then return true end
        end
    end
    return false
end
local function allianceFormation(anchor,count)
    local result={}
    local yaw=math.rad(anchor.rotation)
    local rightX,rightZ=math.cos(yaw),-math.sin(yaw)
    for i=1,count do
        local lane=count==1 and 0 or (((count-i)%2)-0.5)*3.15
        local depth=(math.floor((count-1)/2)-math.floor((count-i)/2))*3.15
        local p=alliancePosition(anchor)
        p.x=p.x+rightX*lane-math.sin(yaw)*depth;p.z=p.z+rightZ*lane-math.cos(yaw)*depth
        if allianceBlocked(p) then return nil end
        table.insert(result,{position=p,rotation=anchor.rotation})
    end
    return result
end
local function allianceRandomFormation(count)
    local start=math.random(1,6)
    for attempt=0,5 do
        local anchor=ALLIANCE_SPAWN_POINTS[((start+attempt-1)%6)+1]
        local formation=allianceFormation(anchor,count)
        if formation then return formation,((start+attempt-1)%6)+1 end
    end
    return nil,nil
end
local function allianceCardSlot(index)
    return ALLIANCE_CARD_SLOTS[index] or {23+((index-1)%4)*7.5,1.2,37+math.floor((index-1)/4)*16.5}
end
local function allianceSpawnShields(s,count)
    local card=obj(s.cardGUID);local bag=obj(ACTION_BAGS.SHIELD)
    if not card or not bag then return end
    local p=card.getPosition()
    for i=1,(tonumber(count) or 0) do
        bag.takeObject({position={p.x-1.2+(i-1)*0.55,p.y+0.6,p.z+2.15},callback_function=function(token)
            if token then token.setGMNotes("STA2E_ALLIANCE_SHIELD|"..s.instanceId) end
        end})
    end
end
local function allianceProfile(definition,key)
    local profiles=definition.profiles or {}
    return profiles[key] or profiles.generic
end
local function allianceDrawShipCard(state,className,fallbackId)
    local ids=ALLIANCE_SHIP_CARDS_BY_CLASS[className] or {}
    if #ids==0 and fallbackId and ALLIANCE_SHIP_CARDS[tostring(fallbackId)] then
        return ALLIANCE_SHIP_CARDS[tostring(fallbackId)],tostring(fallbackId)
    end
    if #ids==0 then return nil,nil end
    state.cardDrawBags=state.cardDrawBags or {}
    local bag=state.cardDrawBags[className]
    if not bag or #bag==0 then
        bag={}
        for _,id in ipairs(ids) do table.insert(bag,id) end
        for i=#bag,2,-1 do local j=math.random(i);bag[i],bag[j]=bag[j],bag[i] end
        state.cardDrawBags[className]=bag
    end
    local id=table.remove(bag)
    return ALLIANCE_SHIP_CARDS[id],id
end
