        Transform={posX=0,posY=1.2,posZ=0,rotX=0,rotY=180,rotZ=0,scaleX=1.2,scaleY=1.2,scaleZ=1.2},
        ColorDiffuse={r=1,g=1,b=1},Locked=false,Grid=false,Snap=false,CardID=deckId*100+sheetIndex,
        CustomDeck={[tostring(deckId)]={FaceURL=cardFace,BackURL=cardBack,NumWidth=sheetWidth,NumHeight=sheetHeight,BackIsHidden=true,UniqueBack=sheet.uniqueBack~=false,Type=0}},
        LuaScript=MEMBER_SCRIPT,XmlUI=""}
