        state={status="planning",dialOpen=true},spawnPosition=p,spawnRotation=rotation,physicalReady=true,allianceCardSlot=slotIndex,allianceCardId=cardId,allianceCardFaceDown=not isAdvanced}
    if definition.book2 then
