        local stats=SHIP_COMBAT_STATS[s.definitionId] or {}
        s.combat={hull=profile.hull,maxHull=profile.hull,shields=profile.shields,maxShields=profile.shields,
            agility=stats.agility or 1,destroyed=false,statsVersion=1}
        if definition.book3 and definition.book3Settings.penumbra and className:find("Jem'Hadar",1,true) and definition.act==9 then s.combat.hull=math.max(0,s.combat.hull-1) end
    end
