local function allianceSpawnGroup(profile,count)
    local formation,anchor=allianceRandomFormation(count)
    if not formation then
        broadcastToAll("Alliance reinforcement could not find a legal edge point after checking all six anchors. Resolve this spawn manually.",{1,0.45,0.2})
        return false
    end
    for i=1,count do allianceSpawnShip({profile=profile},formation[i]) end
    broadcastToAll("Alliance reinforcement point "..anchor.." selected (1d6 edge deployment).",{0.75,0.58,1})
    return true
end
local function allianceSpawnToken(name,image,position,scale,rotation)
