local function allianceRotateOffset(offset,yaw)
    local angle=math.rad(yaw or 0);local x,z=offset.x or offset[1],offset.z or offset[3]
    return {x=x*math.cos(angle)-z*math.sin(angle),y=offset.y or offset[2] or 1,z=x*math.sin(angle)+z*math.cos(angle)}
end
local function allianceSetupObjects(definition)
    local board=obj("ae9c49");local boardPosition=board and board.getPosition() or {x=0,y=0,z=0}
    local boardYaw=board and board.getRotation().y or 0
    if definition.mapImage then
        if board then local custom=board.getCustomObject();custom.diffuse=definition.mapImage;board.setCustomObject(custom);board.reload() end
    end
