    while #asteroidPositions<asteroidCount and attempts<1000 do
        attempts=attempts+1
        local candidate={x=boardPosition.x+(math.random()*2-1)*halfZone,y=boardPosition.y+0.48,z=boardPosition.z+(math.random()*2-1)*halfZone}
        local clear=true
        for _,other in ipairs(asteroidPositions) do
            local dx,dz=other.x-candidate.x,other.z-candidate.z
            if math.sqrt(dx*dx+dz*dz)<minimum then clear=false;break end
        end
        if clear then table.insert(asteroidPositions,candidate) end
