    for _,position in ipairs(asteroidPositions) do allianceSpawnToken("Alliance Asteroid",definition.asteroidImage,position,0.54,0) end
    if #asteroidPositions<asteroidCount then broadcastToAll("Alliance setup placed only "..#asteroidPositions.." of "..asteroidCount.." asteroids.",{1,0.55,0.2}) end
    for _,token in ipairs(definition.objectives or {}) do
        local position=token.position
