            CustomPDF={PDFUrl=definition.missionBook.url,PDFPassword="",PDFPage=definition.missionBook.page or 0,PDFPageOffset=0}}
        spawnObjectData({data=data,position={49,1,-14},rotation={0,180,0}})
    end
end
function STA2E_AllianceStart(params)
    if not STA2E.ready then return {ok=false,error="Fleet systems are still loading."} end
    if allianceState() and allianceState().active then return {ok=false,error="An Alliance mission is already active in this save."} end
    local definition=params and params.definition
    local players=math.max(2,math.min(6,tonumber(params and params.playerCount) or 2))
    if type(definition)~="table" or not definition.id then return {ok=false,error="Mission chip did not supply a valid scenario definition."} end
