    STA2E.game.round=0;STA2E.game.phase="setup"
    STA2E.game.alliance={active=true,missionId=definition.id,playerCount=players,difficulty=difficulty,round=0,
        eventsTriggered={},spawnedShips={},classCounts={},cardDrawBags={},definition=definition}
    allianceSetupObjects(definition)
    local setup=(definition.setup or {})[players] or (definition.setup or {})[tostring(players)] or {}
    for _,entry in ipairs(setup) do
        allianceSpawnShip({profile=entry.profile or "generic",definitionId=entry.definitionId},entry)
    end
    broadcastToAll(definition.name.." started for "..players.." players on "..difficulty.." difficulty. Round 0 Setup; advance once when setup is complete to begin Round 1 Planning.",{0.75,0.58,1})
    hud();return {ok=true}
end
function STA2E_AllianceProcessRound()
    local state=allianceState();if not state or not state.active or STA2E.game.phase~="planning" then return end
    state.round=STA2E.game.round
    for index,event in ipairs(state.definition.events or {}) do
        local key=tostring(index)..":"..tostring(event.round)
        if event.round==state.round and not state.eventsTriggered[key] then
            local counts=event.counts or {};local count=tonumber(counts[state.playerCount] or counts[tostring(state.playerCount)] or event.count or 0) or 0
            if count<=0 or allianceSpawnGroup(event.profile or "generic",count) then state.eventsTriggered[key]=true end
        end
    end
end
local function allianceTarget(s)
    local base=member(s,"base");if not base then return nil end
    local p=base.getPosition();local best,bestDistance
    for _,candidate in pairs(STA2E.ships) do
        local mission=allianceState()
        local hostile=mission and mission.definition and mission.definition.book3 and candidate.instanceId~=s.instanceId and (candidate.side or (candidate.ai and "enemy" or "allied"))~=(s.side or "enemy") and not (candidate.combat and candidate.combat.destroyed)
        if hostile or (not (mission and mission.definition and mission.definition.book3) and not candidate.ai) then
            local other=member(candidate,"base")
            if other then local q=other.getPosition();local d=(q.x-p.x)^2+(q.z-p.z)^2
                if not bestDistance or d<bestDistance then best,bestDistance=candidate,d end end
        end
    end
    return best
end
local function angleDistance(a,b) return math.abs(((a-b+180)%360)-180) end
local function allianceManeuver(s,target)
    local base,targetBase=member(s,"base"),member(target,"base");if not base or not targetBase then return nil end
    local p,r=base.getPosition(),base.getRotation();local q=targetBase.getPosition();local start={x=p.x,z=p.z,yaw=r.y}
    local obstacles={}
    for id,other in pairs(STA2E.ships) do if id~=s.instanceId then local o=member(other,"base");if o then local op,orr=o.getPosition(),o.getRotation();table.insert(obstacles,{pose={x=op.x,z=op.z,yaw=orr.y},shape=baseShape(o)}) end end end
    local best,bestScore
    for _,entry in ipairs(dialFor(s)) do
        local move=MOVE_DEFS[entry.key]
        if move then
            local stop=latestLegal(start,move,baseShape(base),obstacles);local finish=pose(start,move,stop,baseShape(base).z)
            local dx,dz=q.x-finish.x,q.z-finish.z;local distance=math.sqrt(dx*dx+dz*dz)
            local desired=math.deg(math.atan2(-dx,-dz));local score=distance+angleDistance(finish.yaw,desired)*0.025+(stop<0.98 and 3 or 0)
            if not bestScore or score<bestScore or (score==bestScore and entry.key<best) then best,bestScore=entry.key,score end
        end
    end
    return best
end
function STA2E_AllianceChooseAction(params) return nil end
function STA2E_AllianceActivateAI(params)
    local s=params and STA2E.ships[params.instanceId]
    if not s or not s.ai then return end
    if STA2E.game.phase~="activation" then tell(params.color or "Black","AI ships activate during the Activation phase.");return end
    if s.aiActivatedRound==STA2E.game.round or s.state.status=="complete" or s.state.status=="action" then tell(params.color or "Black",s.name.." has already moved this round.");return end
    if STA2E.pendingMoves[s.instanceId] then return end
    -- The AI Prototype v0.4 controller owns the dial UI and maneuver chart. Use
    -- that exact control path when installed; the local selector below remains
    -- a safe fallback for saves that only have the mission framework.
    if STA2E.AllianceAI and type(s.ai)=="table" and s.ai.enabled then
        local card=obj(s.cardGUID)
        if not card then return end
        STA2E_Command({object=card,color=params.color or "Red",command="ai_evaluate"})
        if not s.ai.plan then return end
        broadcastToAll("[AI] "..s.name..": "..tostring(s.ai.message or "maneuver evaluated"),{0.75,0.58,1})
        STA2E_Command({object=card,color=params.color or "Red",command="ai_execute"})
        local checks=0
        local function report()
            checks=checks+1
            if STA2E.pendingMoves[s.instanceId] and checks<180 then Wait.frames(report,1);return end
            if not STA2E.ships[s.instanceId] then return end
            s.aiActivatedRound=STA2E.game.round;commit(s);refresh(s)
            if s.state.status=="action" then broadcastToAll("[AI] "..s.name..": maneuver complete; resolve its action from the AI dial.",{0.75,0.58,1}) end
        end
        Wait.frames(report,1);return
    end
    local target=allianceTarget(s)
    if not target then broadcastToAll(s.name.." cannot activate: no deployed player ship target is available.",{1,0.45,0.2});return end
    local key=allianceManeuver(s,target)
    if not key then broadcastToAll(s.name.." cannot activate: no maneuver is available.",{1,0.45,0.2});return end
    broadcastToAll(s.name.." activates. Target: "..target.name..". Maneuver: "..maneuverLabel(s,key)..".",{0.75,0.58,1})
    executeMove(s,s.owner,key)
    local checks=0
    local function finish()
        checks=checks+1
        if STA2E.pendingMoves[s.instanceId] and checks<180 then Wait.frames(finish,1);return end
        if not STA2E.ships[s.instanceId] then return end
        local action=STA2E_AllianceChooseAction({ship=s,target=target})
        s.aiActivatedRound=STA2E.game.round;s.state.status="complete";commit(s);refresh(s)
        broadcastToAll(s.name.." activation complete. Action: "..(action or "manual / no evaluator installed")..".",{0.75,0.58,1})
    end
    Wait.frames(finish,1)
end

local phaseReconcile=STA2E_Reconcile
function STA2E_Reconcile()
    phaseReconcile()
    for _,s in pairs(STA2E.ships) do
        if normalizeDialPhase(s) then refresh(s) end
        if s.state.guideArc or (s.state.guideRange or 0)>0 then drawShipGuides(s) end
        STA2E_StartupYield("normalized")
    end
end

local phaseAdvance=STA2E_PhaseUI
function STA2E_PhaseUI(player,value)
    local before=STA2E.game.phase
    phaseAdvance(player,value)
    if STA2E.game.phase==before then return end
    for _,s in pairs(STA2E.ships) do
        normalizeDialPhase(s)
        refresh(s)
    end
    if STA2E.game.phase=="planning" then STA2E_AllianceProcessRound() end
end

-- Physical dice detection with a logical result lock. Once captured, incidental
-- movement of the physical die cannot alter the recorded combat result.
local DICE_ZONE_COLORS={d1ce01="Blue",d1ce02="Red"}
local ATTACK_FACES={"Blank","Hit","Crit","Battle Stations"}
local DEFENSE_FACES={"Blank","Evade","Battle Stations"}
local DiceManager={byGuid={},watching={}}

local function dieType(object)
    if not object or (object.type~="Custom_Dice" and object.type~="Dice") then return nil end
    local values=object.getRotationValues and object.getRotationValues() or {}
    local hasAttack,hasDefense=false,false
    for _,entry in ipairs(values or {}) do
        local value=string.lower(tostring(entry.value or entry.Value or ""))
        if value=="hit" or value=="crit" or value=="critical" then hasAttack=true end
        if value=="evade" then hasDefense=true end
    end
    if hasAttack then return "attack" end
    if hasDefense then return "defense" end
    local tags=object.getTags and object.getTags() or {}
    for _,tag in ipairs(tags) do
        if tag=="STA2E_ATTACK_DIE" then return "attack" end
        if tag=="STA2E_DEFENSE_DIE" then return "defense" end
    end
    return nil
end

local function normalizeDieResult(value,kind)
    local text=tostring(value or "Blank")
    local lower=string.lower(text):gsub("[%s_-]","")
    local numeric={
        attack={ ["1"]="Crit",["2"]="Blank",["3"]="Hit",["4"]="Blank",["5"]="Battle Stations",["6"]="Hit",["7"]="Battle Stations",["8"]="Hit" },
        defense={ ["1"]="Evade",["2"]="Blank",["3"]="Evade",["4"]="Battle Stations",["5"]="Blank",["6"]="Evade",["7"]="Battle Stations",["8"]="Blank" },
    }
    if numeric[kind] and numeric[kind][text] then return numeric[kind][text] end
    local names={blank="Blank",hit="Hit",crit="Crit",critical="Crit",evade="Evade",battlestation="Battle Stations",battlestations="Battle Stations"}
    local result=names[lower] or text
    local legal=kind=="attack" and ATTACK_FACES or DEFENSE_FACES
    for _,face in ipairs(legal) do if face==result then return result end end
    return "Blank"
end

local function setDieSelected(die,selected)
    if not die then return end
    die.selected=selected==true
    local object=obj(die.guid)
    if not object then return end
    if die.selected then object.highlightOn({1.0,0.82,0.12},0)
    else object.highlightOff() end
end

local function clearDiceSelection(pool)
    for _,guid in ipairs(pool.order or {}) do setDieSelected(pool.dice[guid],false) end
end

local function dicePool(color)
    STA2E.dice=STA2E.dice or {}
    STA2E.dice[color]=STA2E.dice[color] or {dice={},order={},rolling={},revision=0,finalized=false}
    STA2E.dice[color].rolling=STA2E.dice[color].rolling or {}
    return STA2E.dice[color]
end

function DiceManager.remove(color,guid)
    local pool=dicePool(color)
    local die=pool.dice[guid]
    if die then setDieSelected(die,false) end
    local object=obj(guid)
    if object then object.setLock(false) end
    pool.dice[guid]=nil;pool.rolling[guid]=nil
    for i=#pool.order,1,-1 do if pool.order[i]==guid then table.remove(pool.order,i) end end
    if DiceManager.byGuid[guid]==die then DiceManager.byGuid[guid]=nil end
    DiceManager.watching[guid]=nil
    pool.revision=(pool.revision or 0)+1
    if #pool.order==0 then pool.kind=nil;pool.finalized=false end
end

function DiceManager.pending(pool)
    if next(pool.rolling) then return true end
    for _,die in pairs(pool.dice) do if die.awaiting then return true end end
    return false
end

local function diceSummary(color)
    local pool=dicePool(color)
    local values={}
    for _,guid in ipairs(pool.order) do
        local die=pool.dice[guid]
        if die and not die.awaiting then
            local result=die.result=="Battle Stations" and "Battlestation" or die.result
            table.insert(values,result)
        end
    end
    local kind=pool.kind=="defense" and "defense" or "attack"
    local noun=#values==1 and "die" or "dice"
    return color.." rolled "..#values.." "..kind.." "..noun.." and got "..table.concat(values,", ").."."
end

local function rotateDieToResult(die,result)
    local object=die and obj(die.guid)
    if not object then return false end
    for _,entry in ipairs(object.getRotationValues and object.getRotationValues() or {}) do
        local value=entry.value or entry.Value
        if normalizeDieResult(value,die.kind)==result then
            local rotation=entry.rotation or entry.Rotation
            if rotation then object.setRotationSmooth(rotation,false,true);return true end
        end
    end
    return false
end

local function arrangeDicePool(color)
    local pool=dicePool(color)
    local zoneGuid=color=="Blue" and "d1ce01" or "d1ce02"
    local zone=obj(zoneGuid)
    if not zone then return end
    local center,rotation=zone.getPosition(),zone.getRotation()
    local angle=math.rad(rotation.y or 0)
    local rightX,rightZ=math.cos(angle),-math.sin(angle)
    local spacing=1.55
    local count=#pool.order
    local arrangeRevision=pool.revision or 0
    for i,guid in ipairs(pool.order) do
        local object=obj(guid)
        if object then
            local dieGuid=guid
            local offset=(i-(count+1)/2)*spacing
            local current=object.getPosition()
            object.setLock(false)
            object.setPositionSmooth({center.x+rightX*offset,current.y,center.z+rightZ*offset},false,true)
            Wait.frames(function()
                local settled=obj(dieGuid)
                local active=dicePool(color)
                if settled and active.revision==arrangeRevision and active.dice[dieGuid] then settled.setLock(true) end
            end,25)
        end
    end
end

local function finishDiceBatch(color)
    local pool=dicePool(color)
    if next(pool.rolling) then return end
    local revision=pool.revision or 0
    Wait.frames(function()
        local current=dicePool(color)
        if current.revision~=revision or next(current.rolling) or current.finalized then return end
        arrangeDicePool(color)
        broadcastToAll(diceSummary(color),color=="Blue" and {0.25,0.65,1} or {1,0.35,0.35})
        hud()
    end,20)
end

function DiceManager.capture(object,color)
    local kind=dieType(object)
    if not kind or not own(color) then return end
    local guid=object.getGUID()
    local pool=dicePool(color)
    if pool.finalized or not pool.rolling[guid] then return end
    pool.kind=kind
    local die=pool.dice[guid] or {guid=guid,kind=kind,selected=false}
    die.result=normalizeDieResult(object.getValue and object.getValue() or "Blank",kind)
    die.awaiting=false
    die.color=color
    pool.dice[guid]=die
    DiceManager.byGuid[guid]=die
    object.setLock(true)
    pool.rolling[guid]=nil
    pool.revision=(pool.revision or 0)+1
    finishDiceBatch(color)
end

function DiceManager.watch(object,color,attempt)
    if not object or not obj(object.getGUID()) then return end
    local guid=object.getGUID()
    if DiceManager.watching[guid] then return end
    local watchedPool=dicePool(color)
    local watchedDie=watchedPool.dice[guid]
    local ticket={}
    DiceManager.watching[guid]=ticket
    local function poll(count)
        if DiceManager.watching[guid]~=ticket then return end
        local current=obj(guid)
        local pool=dicePool(color)
        if pool~=watchedPool or pool.dice[guid]~=watchedDie or not pool.rolling[guid] then DiceManager.watching[guid]=nil;return end
        if not current then DiceManager.remove(color,guid);finishDiceBatch(color);hud();return end
        if current.resting then
            DiceManager.watching[guid]=nil
            DiceManager.capture(current,color)
            return
        end
        if count>=360 then
            DiceManager.remove(color,guid)
            tell(color,"A die did not settle in time and was removed from the pool. Roll it again to record a result.")
            finishDiceBatch(color)
            hud()
            return
        end
        Wait.frames(function() poll(count+1) end,1)
    end
    -- Randomize events can fire before TTS clears the die's resting flag.
    -- Give physics two frames to start before testing for a settled result.
    Wait.frames(function() poll(attempt or 0) end,2)
end

function DiceManager.beginRoll(object,color)
    local kind=dieType(object)
    if not kind or not own(color) then return end
    local pool=dicePool(color)
    if pool.finalized then return end
    if pool.kind and pool.kind~=kind and #pool.order>0 then tell(color,"Finish or clear the current "..pool.kind.." pool before recording "..kind.." dice.");return end
    local guid=object.getGUID()
    if pool.rolling[guid] then return end
    local previous=DiceManager.byGuid[guid]
    if previous and previous.color~=color then
        if own(previous.color) then DiceManager.remove(previous.color,guid) else DiceManager.byGuid[guid]=nil;DiceManager.watching[guid]=nil end
    end
    pool.kind=kind
    local die=DiceManager.byGuid[guid] or {guid=guid,kind=kind,selected=false}
    setDieSelected(die,false)
    die.kind=kind;die.color=color;die.awaiting=true;die.result="Rolling…"
    if not pool.dice[guid] then table.insert(pool.order,guid) end
    pool.dice[guid]=die;DiceManager.byGuid[guid]=die
    pool.rolling[guid]=true
    pool.revision=(pool.revision or 0)+1
    STA2E.diceOpen=STA2E.diceOpen or {};STA2E.diceOpen[color]=true
    DiceManager.watch(object,color,0)
    hud()
end

function DiceManager.restore(state)
    if type(state)~="table" or state.schemaVersion~=1 then return end
    local savedPools=type(state.dice)=="table" and state.dice or {}
    local savedOpen=type(state.diceOpen)=="table" and state.diceOpen or {}
    local savedSource=type(state.diceSource)=="table" and state.diceSource or {}
    local resume={}
    for _,color in ipairs(PLAYER_COLORS) do
        local saved=savedPools[color]
        local pool=dicePool(color)
        if type(saved)=="table" and array(saved.order) and type(saved.dice)=="table" then
            for _,guid in ipairs(saved.order) do
                local die=type(guid)=="string" and saved.dice[guid]
                local object=type(guid)=="string" and obj(guid)
                local kind=object and dieType(object)
                if type(die)=="table" and kind and not DiceManager.byGuid[guid] and (not pool.kind or pool.kind==kind) then
                    local awaiting=die.awaiting==true or (type(saved.rolling)=="table" and saved.rolling[guid]==true)
                    local restored={guid=guid,kind=kind,color=color,selected=not awaiting and die.selected==true,awaiting=awaiting,result=awaiting and "Rolling…" or normalizeDieResult(die.result,kind)}
                    pool.kind=kind;pool.dice[guid]=restored;table.insert(pool.order,guid)
                    DiceManager.byGuid[guid]=restored
                    object.setLock(not awaiting);setDieSelected(restored,restored.selected)
                    if awaiting then table.insert(resume,{object=object,color=color}) end
                end
            end
            pool.finalized=saved.finalized==true and not DiceManager.pending(pool)
        end
        if type(savedOpen[color])=="boolean" then STA2E.diceOpen[color]=savedOpen[color]
        else STA2E.diceOpen[color]=#pool.order>0 end
        if type(savedSource[color])=="string" then STA2E.diceSource[color]=savedSource[color] end
    end
    for _,pending in ipairs(resume) do
        local pool=dicePool(pending.color)
        pool.rolling[pending.object.getGUID()]=true
        DiceManager.watch(pending.object,pending.color,0)
    end
end

local function diceInZoneColor(object)
    for guid,color in pairs(DICE_ZONE_COLORS) do
        local zone=obj(guid)
        if zone then for _,inside in ipairs(zone.getObjects()) do if inside==object then return color end end end
    end
    return nil
end

function onObjectEnterScriptingZone(zone,object)
    local color=zone and DICE_ZONE_COLORS[zone.getGUID()]
    if color and dieType(object) then DiceManager.beginRoll(object,color) end
end

function STA2E_DieRolled(params)
    local object=params and params.object
    if not dieType(object) then return end
    local color=diceInZoneColor(object)
    if color then DiceManager.beginRoll(object,color) end
end

local function selectedDice(pool,predicate)
    local result={}
    for _,guid in ipairs(pool.order) do
        local die=pool.dice[guid]
        if die and ((predicate and predicate(die)) or (not predicate and die.selected)) then table.insert(result,die) end
    end
    return result
end

local function rerollDice(color,dice)
    for _,die in ipairs(dice) do
        local object=obj(die.guid)
        if object then
            setDieSelected(die,false)
            object.setLock(false)
            object.randomize()
            DiceManager.beginRoll(object,color)
        end
    end
end

local function consumeShipToken(color,key)
    local instance=STA2E.diceSource and STA2E.diceSource[color]
    if not instance then return false end
    local note="STA2E_SHIP_TOKEN|"..instance.."|"..key
    for _,object in ipairs(getAllObjects()) do
        if object.getGMNotes and object.getGMNotes()==note then object.destruct();return true end
    end
    return false
end

function STA2E_DiceAction(player,value,id)
    if not player or not own(player.color) or not id then return end
    local color=player.color
    local prefix="dice_"..color.."_"
    if id:sub(1,#prefix)~=prefix then return end
    local action=id:sub(#prefix+1)
    local pool=dicePool(color)
    if action=="close" then clearDiceSelection(pool);STA2E.diceOpen[color]=false;hud();return end
    if action=="clear" then
        clearDiceSelection(pool)
        for _,guid in ipairs(pool.order) do
            local object=obj(guid)
            if object then object.setLock(false) end
            DiceManager.byGuid[guid]=nil
            DiceManager.watching[guid]=nil
        end
        STA2E.dice[color]={dice={},order={},rolling={},revision=0,finalized=false};hud();return
    end
    if pool.finalized then tell(color,"This dice pool is finalized. Clear it to begin another roll.");return end
    if DiceManager.pending(pool) then tell(color,"Wait for every die to settle before changing or finalizing this pool.");return end
    local guid=action:match("^toggle_(.+)$")
    if guid and pool.dice[guid] then setDieSelected(pool.dice[guid],not pool.dice[guid].selected);hud();return end
    if action=="reroll" then rerollDice(color,selectedDice(pool));hud();return end
    if action=="reroll_blanks" then rerollDice(color,selectedDice(pool,function(die)return die.result=="Blank" end));hud();return end
    if action=="spend_bs" then
        local eligible={};for _,die in ipairs(selectedDice(pool)) do if die.result=="Battle Stations" then table.insert(eligible,die) end end
        if #eligible==0 then tell(color,"Select at least one Battle Stations result.");return end
        if not consumeShipToken(color,"BS") then tell(color,"No Battle Stations token linked to the active ship is available.");return end
        for _,die in ipairs(eligible) do
            die.result=pool.kind=="defense" and "Evade" or "Hit"
            rotateDieToResult(die,die.result)
            setDieSelected(die,false)
        end
        hud();return
    end
    local face=action:match("^set_(.+)$")
    if face then
        face=face:gsub("_"," "):gsub("(%a)([%w']*)",function(a,b)return string.upper(a)..string.lower(b)end)
        local legal=pool.kind=="defense" and DEFENSE_FACES or ATTACK_FACES
        local allowed=false;for _,candidate in ipairs(legal) do if candidate==face then allowed=true end end
        if not allowed then tell(color,"That face is not legal for this die type.");return end
        for _,die in ipairs(selectedDice(pool)) do
            die.result=face
            rotateDieToResult(die,face)
            setDieSelected(die,false)
        end
        hud();return
    end
    if action=="finalize" then
        pool.finalized=true
        clearDiceSelection(pool)
        broadcastToAll(color.." finalized: "..diceSummary(color),color=="Blue" and {0.25,0.65,1} or {1,0.35,0.35})
        hud();return
    end
end

function STA2E_DicePanel()
    local parts={}
    for _,color in ipairs(PLAYER_COLORS) do
        local pool=dicePool(color)
        if STA2E.diceOpen and STA2E.diceOpen[color]==true then
            local height=360+math.ceil(math.max(1,#pool.order)/4)*58
            local top=height/2-30
            table.insert(parts,'<Panel id="dicePanel'..color..'" visibility="'..color..'" rectAlignment="LowerCenter" offsetXY="0 36" scale="0.6 0.6 1" width="760" height="'..height..'" color="#102432F8">')
            table.insert(parts,'<Text text="DICE DASHBOARD · '..string.upper(pool.kind or "WAITING FOR ROLL")..'" position="0 '..top..' 0" width="720" height="32" fontSize="21" color="#FFFFFF"/>')
            for i,guid in ipairs(pool.order) do
                local die=pool.dice[guid]
                local x=-270+((i-1)%4)*180
                local y=top-62-math.floor((i-1)/4)*58
                local shade=die.selected and "#C69A2B" or (die.awaiting and "#48515D" or "#285779")
                table.insert(parts,'<Button id="dice_'..color..'_toggle_'..guid..'" onClick="STA2E_DiceAction" position="'..x..' '..y..' 0" width="166" height="46" fontSize="14" color="'..shade..'" textColor="#FFFFFF">'..i..' · '..xml(die.result)..'</Button>')
            end
            local controlsY=-height/2+128
            if not pool.finalized then
                table.insert(parts,'<Button id="dice_'..color..'_reroll" onClick="STA2E_DiceAction" position="-255 '..controlsY..' 0" width="155" height="38">REROLL SELECTED</Button>')
                table.insert(parts,'<Button id="dice_'..color..'_reroll_blanks" onClick="STA2E_DiceAction" position="-85 '..controlsY..' 0" width="155" height="38">REROLL BLANKS</Button>')
                table.insert(parts,'<Button id="dice_'..color..'_spend_bs" onClick="STA2E_DiceAction" position="85 '..controlsY..' 0" width="155" height="38">SPEND BATTLE STATIONS</Button>')
                table.insert(parts,'<Button id="dice_'..color..'_finalize" onClick="STA2E_DiceAction" position="255 '..controlsY..' 0" width="155" height="38" color="#256348">FINALIZE</Button>')
                local faces=pool.kind=="defense" and DEFENSE_FACES or ATTACK_FACES
                for i,face in ipairs(faces) do
                    local x=(i-(#faces+1)/2)*155
                    local key=string.lower(face):gsub(" ","_")
                    table.insert(parts,'<Button id="dice_'..color..'_set_'..key..'" onClick="STA2E_DiceAction" position="'..x..' '..(controlsY-49)..' 0" width="145" height="36" fontSize="14">SET '..string.upper(xml(face))..'</Button>')
                end
            else table.insert(parts,'<Text text="FINALIZED · physical movement will not change these results" position="0 '..controlsY..' 0" width="700" height="38" fontSize="16" color="#7BE0A8"/>') end
            table.insert(parts,'<Button id="dice_'..color..'_clear" onClick="STA2E_DiceAction" position="-105 '..(-height/2+28)..' 0" width="190" height="38" color="#713839">CLEAR POOL</Button>')
            table.insert(parts,'<Button id="dice_'..color..'_close" onClick="STA2E_DiceAction" position="105 '..(-height/2+28)..' 0" width="190" height="38">CLOSE</Button></Panel>')
        end
    end
    return table.concat(parts)
end

STA2E.DiceManager=DiceManager

-- Shared Sensor Echo workflow used by ship actions, Cloak tokens, and cards.
local SENSOR_ECHO_TEMPLATES={
    {id="BANK_2_FORWARD",label="2 Bank — Forward",distance=4.60,bias=0.83,orientation="forward"},
    {id="BANK_1_FORWARD",label="1 Bank — Forward",distance=3.05,bias=0.83,orientation="forward"},
    {id="STRAIGHT_3",label="3 Straight",distance=6.15,bias=0,orientation="forward"},
    {id="STRAIGHT_2",label="2 Straight",distance=4.60,bias=0,orientation="forward"},
    {id="STRAIGHT_1",label="1 Straight",distance=3.05,bias=0,orientation="forward"},
    {id="BANK_2_REVERSE",label="2 Bank — Reverse",distance=4.60,bias=-0.83,orientation="reverse"},
    {id="BANK_1_REVERSE",label="1 Bank — Reverse",distance=3.05,bias=-0.83,orientation="reverse"},
}
local SENSOR_ECHO_CARD_RULES={}
local SensorEchoController={}

local function echoTemplate(id)
    for _,template in ipairs(SENSOR_ECHO_TEMPLATES) do if template.id==id then return template end end
    return nil
end

local function echoAllowed(session,id)
    for _,allowed in ipairs(session.allowed or {}) do if allowed==id then return true end end
    return false
end

local function isEchoObstacle(object)
    return terrainKind(object)~=nil
end

local function echoCandidateLegal(s,candidate,shape)
    for id,other in pairs(STA2E.ships) do
        if id~=s.instanceId then
            local otherBase=member(other,"base")
            if otherBase then
                local p,r=otherBase.getPosition(),otherBase.getRotation()
                if overlaps(candidate,shape,{x=p.x,z=p.z,yaw=r.y},baseShape(otherBase)) then return false,"ship" end
            end
        end
    end
    local ownBase=member(s,"base")
    for _,object in ipairs(getAllObjects()) do
        if object~=ownBase and isEchoObstacle(object) then
            local p,r=object.getPosition(),object.getRotation()
            if overlaps(candidate,shape,{x=p.x,z=p.z,yaw=r.y},baseShape(object)) then return false,terrainKind(object) or "obstacle" end
        end
    end
    return true,nil
end

local function drawEchoCandidates(s,candidates)
    local base=member(s,"base")
    if not base then return end
    local p,r=base.getPosition(),base.getRotation()
    local shape=baseShape(base)
    local scale=base.getScale()
    local sx=math.max(0.01,math.abs(scale and scale.x or 1))
    local sy=math.max(0.01,math.abs(scale and scale.y or 1))
    local sz=math.max(0.01,math.abs(scale and scale.z or 1))
    local lines={}
    for _,candidate in ipairs(candidates or {}) do
        local lx,lz=rotatePoint(candidate.x-p.x,candidate.z-p.z,-r.y)
        local points={}
        for _,corner in ipairs({{-shape.x,-shape.z},{shape.x,-shape.z},{shape.x,shape.z},{-shape.x,shape.z},{-shape.x,-shape.z}}) do
            local cx,cz=rotatePoint(corner[1]+(shape.offsetX or 0),corner[2]+(shape.offsetZ or 0),candidate.yaw-r.y)
            -- Vector lines use the base's scaled local coordinates. Convert the
            -- world-space landing footprint back into that coordinate system so
            -- the preview exactly matches the position committed below.
            table.insert(points,{(lx+cx)/sx,STA2E_Playtest.guideY(base),(lz+cz)/sz})
        end
        table.insert(lines,{points=points,color=candidate.legal and {0.18,0.90,0.42} or {0.52,0.52,0.56},thickness=0.055})
    end
    base.setVectorLines(lines)
end

function SensorEchoController.calculate(session)
    local s=STA2E.ships[session.instanceId]
    local base=s and member(s,"base")
    local template=echoTemplate(session.template)
    if not s or not base or not template or not session.side then return {} end
    local p,r=base.getPosition(),base.getRotation()
    local scale=base.getScale()
    session.source={guid=base.getGUID(),x=p.x,y=p.y,z=p.z,rx=r.x,yaw=r.y,rz=r.z,sx=scale.x,sy=scale.y,sz=scale.z}
    local shape=baseShape(base)
    local ox,oz=rotatePoint(shape.offsetX or 0,shape.offsetZ or 0,r.y)
    local start={x=p.x+ox,z=p.z+oz,yaw=r.y}
    -- Player-facing left/right is opposite the old local-side assumption.
    local direction=session.side=="Left" and -1 or 1
    local candidates={}
    -- Reverse-bank templates deliberately carry a negative bias; they may share
    -- an asset with forward banks but never share placement semantics in code.
    local turn=0
    if template.id:match("^BANK_") then
        -- TTS yaw runs opposite the template-facing sign used by the lateral
        -- displacement. Mirror the bank facing so the landing side edge, not
        -- the rear guides, aligns with the template's far end.
        turn=session.side=="Left" and 45 or -45
        if template.orientation=="reverse" then turn=-turn end
    end
    local finalYaw=start.yaw+turn
    local startHeading=math.rad(start.yaw)
    local finalHeading=math.rad(finalYaw)
    local destinationOffsetX,destinationOffsetZ=rotatePoint(shape.offsetX or 0,shape.offsetZ or 0,finalYaw)
    local startForward={x=-math.sin(startHeading),z=-math.cos(startHeading)}
    local finalForward={x=-math.sin(finalHeading),z=-math.cos(finalHeading)}
    -- The stored template distance reaches the far template end from the
    -- starting side. Add the destination base's half-width so that end meets
    -- the near edge of the landing base instead of stopping inside its outline.
    local centered=pose(start,{forward=template.bias,side=direction*(template.distance+shape.x),rotate=0},1)
    -- A Forward placement puts the template at the front of the starting side
    -- and attaches its far end at the back of the landing side. Back reverses
    -- that pair. Because a bank changes facing, both attachment offsets must be
    -- applied in their own ship orientations; this also changes the side offset.
    for _,choice in ipairs({{name="Forward",attachment=1},{name="Lateral",attachment=0},{name="Back",attachment=-1}}) do
        local attachment=choice.attachment*shape.z
        local candidate={
            name=choice.name,
            x=centered.x+attachment*(startForward.x+finalForward.x)-destinationOffsetX,
            z=centered.z+attachment*(startForward.z+finalForward.z)-destinationOffsetZ,
            yaw=finalYaw,
            templateOrientation=template.orientation,
        }
        candidate.legal,candidate.blockedBy=echoCandidateLegal(s,candidate,shape)
        table.insert(candidates,candidate)
    end
    return candidates
end

function SensorEchoController.cancel(color,message)
    local session=STA2E.sensorEcho and STA2E.sensorEcho[color]
    if session then
        local s=STA2E.ships[session.instanceId]
        if s then drawShipGuides(s) end
    end
    if STA2E.sensorEcho then STA2E.sensorEcho[color]=nil end
    if message then tell(color,message) end
    hud()
end

function STA2E_InstallCloakEcho(token)
    if not token then return end
    local guid=token.getGUID()
    if token.getLuaScript and token.getLuaScript()~=CLOAK_TOKEN_SCRIPT then
        token.setLuaScript(CLOAK_TOKEN_SCRIPT)
        if token.reload then token=token.reload() or token end
    end
    Wait.frames(function()
        local live=obj(guid)
        if live and live.call then live.call("STA2E_DrawCloakEcho") end
    end,2)
end

function STA2E_CloakEcho(params)
    local token=params and params.source
    local color=params and params.color
    if not token or not color then return end
    local id=(token.getGMNotes() or ""):match("^STA2E_SHIP_TOKEN|([^|]+)|CLK$")
    local s=id and STA2E.ships[id]
    if id and not s then tell(color,"The cloak token's ship is no longer deployed.");return end
    if not id then
        local p=token.getPosition();local best,second=math.huge,math.huge
        for _,ship in pairs(STA2E.ships) do
            local base=member(ship,"base")
            if base and STA2E_Playtest.canManage(ship,color) then
                local b=MeasurementGeometry.boundary(ship)
                local d=math.sqrt((p.x-b.center.x)^2+(p.z-b.center.z)^2)
                if d<best then second=best;best=d;s=ship elseif d<second then second=d end
            end
        end
        if not s or best>RANGE_SEGMENT or second-best<.1 then
            tell(color,"Place the cloak token closer to one of your ship bases, then click ECHO.");return
        end
    end
    if not STA2E_Playtest.canManage(s,color) then tell(color,"Only this ship's owner, host or cooperative teammate can use its cloak token.");return end
    STA2E_StartSensorEcho({color=color,instanceId=s.instanceId,source=token,sourceType="cloak"})
end

function STA2E_StartSensorEcho(params)
    if not params or not params.color then return end
    local s=STA2E.ships[params.instanceId]
    if not s or not member(s,"base") then tell(params.color,"Deploy the ship before using Sensor Echo.");return end
    local allowed=params.allowed or SENSOR_ECHO_CARD_RULES[params.cardId]
    if not allowed then allowed={};for _,template in ipairs(SENSOR_ECHO_TEMPLATES) do table.insert(allowed,template.id) end end
    STA2E.sensorEcho=STA2E.sensorEcho or {}
    STA2E.sensorEcho[params.color]={instanceId=s.instanceId,sourceType=params.sourceType or "ship",cardId=params.cardId,allowed=copy(allowed),stage="side"}
    hud()
end

function STA2E_SensorEchoAction(player,value,id)
    if not player or not player.color or not id then return end
    local color=player.color
    local prefix="echo_"..color.."_"
    if id:sub(1,#prefix)~=prefix then return end
    local action=id:sub(#prefix+1)
    local session=STA2E.sensorEcho and STA2E.sensorEcho[color]
    if not session then return end
    local s=STA2E.ships[session.instanceId]
    if not s then SensorEchoController.cancel(color);return end
    if action=="cancel" then SensorEchoController.cancel(color,"Sensor Echo cancelled.");return end
    local base=member(s,"base")
    if not base then SensorEchoController.cancel(color,"The ship base is missing. Sensor Echo cancelled.");return end
    local side=action:match("^side_(Left)$") or action:match("^side_(Right)$")
    if side then session.side=side;session.stage="template";hud();return end
    local templateId=action:match("^template_(.+)$")
    if templateId then
        if not echoAllowed(session,templateId) then tell(color,"That Sensor Echo source does not permit this template.");return end
        session.template=templateId;session.stage="candidate";session.candidates=SensorEchoController.calculate(session)
        drawEchoCandidates(s,session.candidates)
        local any=false;for _,candidate in ipairs(session.candidates) do if candidate.legal then any=true end end
        if not any then tell(color,"No Legal Sensor Echo Position") end
        hud();return
    end
    local choice=tonumber(action:match("^commit_(%d+)$"))
    local candidate=choice and session.candidates and session.candidates[choice]
    if not candidate then tell(color,"Choose a Sensor Echo landing position first.");return end
    local p,r=base.getPosition(),base.getRotation()
    local scale=base.getScale()
    local source=session.source
    local function changed(a,b,angle)
        if type(a)~="number" or type(b)~="number" then return true end
        local delta=angle and ((a-b+180)%360-180) or (a-b)
        return math.abs(delta)>0.02
    end
    if not source or source.guid~=base.getGUID() or changed(source.x,p.x) or changed(source.y,p.y) or changed(source.z,p.z) or changed(source.rx,r.x,true) or changed(source.yaw,r.y,true) or changed(source.rz,r.z,true) or changed(source.sx,scale.x) or changed(source.sy,scale.y) or changed(source.sz,scale.z) then
        SensorEchoController.cancel(color,"The ship moved or changed after the Sensor Echo preview. Start Sensor Echo again.");return
    end
    if STA2E.pendingMoves and STA2E.pendingMoves[s.instanceId] then tell(color,"Wait for this ship's movement to finish before using Sensor Echo.");return end
    if not echoTemplate(session.template) or not echoAllowed(session,session.template) then
        SensorEchoController.cancel(color,"The Sensor Echo template is no longer available.");return
    end
    -- Recompute against current ship and obstacle positions immediately before
    -- committing. A green preview is only advisory until the actual move.
    session.candidates=SensorEchoController.calculate(session)
    candidate=session.candidates[choice]
    if not candidate or not candidate.legal then
        drawEchoCandidates(s,session.candidates)
        tell(color,"That Sensor Echo landing position is blocked.");hud();return
    end
    s.undo={position={p.x,p.y,p.z},rotation={r.x,r.y,r.z},state=copy(s.state),round=STA2E.game.round}
    base.setPosition({candidate.x,p.y,candidate.z});base.setRotation({r.x,candidate.yaw,r.z});sync(s)
    if session.sourceType=="ship" and s.state.status=="action" then s.state.status="complete" end
    STA2E.sensorEcho[color]=nil
    drawShipGuides(s);refresh(s)
    broadcastToAll(s.name.." completed Sensor Echo: "..candidate.name.." ("..session.side..", "..echoTemplate(session.template).label..").",{0.82,0.90,1})
    hud()
end

function STA2E_SensorEchoPanel()
    local parts={}
    for color in pairs(STA2E.sensorEcho or {}) do
        local session=STA2E.sensorEcho and STA2E.sensorEcho[color]
        local s=session and STA2E.ships[session.instanceId]
        if session and s then
            table.insert(parts,'<Panel id="echoPanel'..color..'" visibility="'..color..'" rectAlignment="LowerCenter" offsetXY="0 36" scale="0.6 0.6 1" width="700" height="520" color="#102432FA">')
            table.insert(parts,'<Text text="SENSOR ECHO · '..xml(s.name)..'" position="0 222 0" width="660" height="38" fontSize="24" color="#FFFFFF"/>')
            table.insert(parts,'<Text text="SOURCE: '..string.upper(xml(session.sourceType or "ship"))..'" position="0 184 0" width="650" height="26" fontSize="14" color="#C8D9E8"/>')
            if session.stage=="side" then
                table.insert(parts,'<Text text="1 · CHOOSE SIDE" position="0 122 0" width="620" height="34" fontSize="20" color="#FFD86B"/>')
                table.insert(parts,'<Button id="echo_'..color..'_side_Left" onClick="STA2E_SensorEchoAction" position="-150 35 0" width="260" height="60">LEFT</Button>')
                table.insert(parts,'<Button id="echo_'..color..'_side_Right" onClick="STA2E_SensorEchoAction" position="150 35 0" width="260" height="60">RIGHT</Button>')
            elseif session.stage=="template" then
                table.insert(parts,'<Text text="2 · CHOOSE TEMPLATE · '..string.upper(xml(session.side))..'" position="0 136 0" width="620" height="34" fontSize="20" color="#FFD86B"/>')
                local visible=0
                for _,template in ipairs(SENSOR_ECHO_TEMPLATES) do
                    if echoAllowed(session,template.id) then
                        visible=visible+1
                        local x=visible%2==1 and -160 or 160
                        local y=75-math.floor((visible-1)/2)*62
                        table.insert(parts,'<Button id="echo_'..color..'_template_'..template.id..'" onClick="STA2E_SensorEchoAction" position="'..x..' '..y..' 0" width="295" height="48">'..xml(template.label)..'</Button>')
                    end
                end
            else
                local any=false;for _,candidate in ipairs(session.candidates or {}) do if candidate.legal then any=true end end
                table.insert(parts,'<Text text="3 · CANDIDATE LANDING POSITIONS" position="0 140 0" width="640" height="34" fontSize="20" color="#FFD86B"/>')
                if not any then table.insert(parts,'<Text text="NO LEGAL SENSOR ECHO POSITION" position="0 92 0" width="620" height="36" fontSize="20" color="#FF8D8D"/>') end
                for i,candidate in ipairs(session.candidates or {}) do
                    local y=any and (75-(i-1)*67) or (35-(i-1)*60)
                    local blockedLabel=candidate.blockedBy=="planet" and "Blocked: Planet" or (candidate.blockedBy=="minefield" and "Blocked: Minefield" or "Blocked: Obstacle")
                    local label=candidate.name.." — "..(candidate.legal and "Legal" or blockedLabel)
                    local disabled=candidate.legal and "" or ' interactable="false"'
                    table.insert(parts,'<Button id="echo_'..color..'_commit_'..i..'" onClick="STA2E_SensorEchoAction" position="0 '..y..' 0" width="430" height="50" color="'..(candidate.legal and "#256348" or "#555A61")..'"'..disabled..'>'..label..'</Button>')
                end
            end
            table.insert(parts,'<Button id="echo_'..color..'_cancel" onClick="STA2E_SensorEchoAction" position="0 -215 0" width="250" height="44" color="#713839">CANCEL</Button></Panel>')
        end
    end
    return table.concat(parts)
end

STA2E.SensorEchoController=SensorEchoController
-- RELEASE_SERIAL_STARTUP_20261012: one physical object/ship per frame.
function STA2E_StartupYield(kind)
    local thread=STA2E.startupThread
    if STA2E.loading and thread and coroutine.running()==thread then
        local stats=STA2E.startupStats
        if stats and kind then stats[kind]=(stats[kind] or 0)+1 end
        coroutine.yield()
    end
end
function onLoad(saved)
    local state=decode(saved)
    if type(state)~="table" then state=nil end
    STA2E.startupEpoch=(STA2E.startupEpoch or 0)+1
    local epoch=STA2E.startupEpoch
    STA2E.game=(state and state.schemaVersion==1 and type(state.game)=="table" and state.game) or {round=0,phase="setup",nextId=100,fleets={}}
    STA2E.game.rulesMode="open"
    STA2E.ships={};STA2E.pending={};STA2E.imports={};STA2E.fleetText={};STA2E.fleetStatus={};STA2E.fleetPlans={};STA2E.fleetColor=nil
    STA2E.dice={};STA2E.diceOpen={};STA2E.diceSource={};STA2E.sensorEcho={};DiceManager.byGuid={};DiceManager.watching={}
    STA2E.ready=false;STA2E.loading=true;STA2E.reconciling=false
    STA2E.startupThread=nil;STA2E.startupRegistering=false;STA2E.startupFlushing=false
    STA2E.startupRefreshQueue={};STA2E.startupStats={jobs=0,cards=0,rendered=0}
    CATALOG={};CATALOG_ORDINAL={}
    UI.setXml('<Panel rectAlignment="UpperLeft" offsetXY="58 -62" width="455" height="50" color="#102432EE"><Text color="#FFFFFF" fontSize="20">Preparing fleets...</Text></Panel>')
    local started=Time.time
    local jobIndex,cardIndex=1,1
    local stage,worker,settleUntil,roundProcessed="data",nil,nil,false
    local done=false
    local function valid() return not done and epoch==STA2E.startupEpoch end
    local step
    local function schedule() if valid() then Wait.frames(step,1) end end
    local function waitingForObjects()
        if next(STA2E.pending or {}) then return true end
        local alliance=STA2E.game and STA2E.game.alliance
        if alliance and alliance.active then
            if alliance.missionObjects and (tonumber(alliance.missionObjects.pending) or 0)>0 then return true end
            for _,record in pairs(alliance.shipRecords or {}) do
                if not record.cancelled and not record.destroyed and ((tonumber(record.pendingObjects) or 0)>0 or (tonumber(record.pendingShields) or 0)>0) then return true end
            end
        end
        return false
    end
    step=function()
        if not valid() then return end
        local ok,err=pcall(function()
            STA2E.startupStage=stage
            if stage=="data" then
                local job=startupJobs and startupJobs[jobIndex]
                -- Completed chunks are retained in their target caches. A reload
                -- can resume the remaining chunks without decoding nil JSON.
                while job and not job.json do jobIndex=jobIndex+1;job=startupJobs[jobIndex] end
                if job then
                    local values=JSON.decode(job.json)
                    for key,value in pairs(values) do job.target[job.offset>=0 and (job.offset+key) or key]=value end
                    job.json=nil;jobIndex=jobIndex+1;STA2E.startupStats.jobs=STA2E.startupStats.jobs+1
                    schedule();return
                end
                stage="catalog";schedule();return
            end
            if stage=="catalog" then
                local cards=CATALOG_DATA.cards or {}
                if cardIndex<=#cards then
                    -- Static table indexing is cheap; bound it to 16 rows. World
                    -- object calls below are strictly serialized one at a time.
                    local last=math.min(cardIndex+15,#cards)
                    for i=cardIndex,last do
                        local card=cards[i]
                        local asset=card.assetSheet and CATALOG_DATA.assetSheets and CATALOG_DATA.assetSheets[card.assetSheet]
                        if asset then
                            card.cardImage=asset.cardImage;card.cardBack=asset.cardBack;card.sheet=card.sheet or {}
                            card.sheet.width=asset.width;card.sheet.height=asset.height;card.sheet.uniqueBack=asset.uniqueBack
                        end
                        if card.publishedFace then card.cardImage=card.publishedFace;card.sheet=nil end
                        CATALOG[card.id]=card;CATALOG_ORDINAL[card.id]=i
                        STA2E.startupStats.cards=STA2E.startupStats.cards+1
                    end
                    cardIndex=last+1;schedule();return
                end
                stage="reconcile";schedule();return
            end
            if stage=="reconcile" then
                if not worker then
                    STA2E.startupRegistering=true
                    -- Run the final wrapper chain: M5 catalog installation,
                    -- identity reconciliation, guides, and mission recovery.
                    worker=coroutine.create(function() DiceManager.restore(state);STA2E_Reconcile() end)
                    STA2E.startupThread=worker
                end
                local resumed,reason=coroutine.resume(worker)
                if not resumed then error(reason) end
                if coroutine.status(worker)=="dead" then
                    STA2E.startupThread=nil;STA2E.startupRegistering=false
                    stage="settle";settleUntil=Time.time+20
                end
                schedule();return
            end
            if stage=="settle" then
                if waitingForObjects() and Time.time<settleUntil then schedule();return end
                if waitingForObjects() then
                    STA2E.startupWarning="Some object callbacks are still pending; use Deploy / Repair if a component is missing."
                    print("STA2E startup: "..STA2E.startupWarning)
                end
                if not roundProcessed then
                    roundProcessed=true;STA2E_AllianceProcessRound();settleUntil=Time.time+20
                    schedule();return
                end
                stage="render";schedule();return
            end
            if stage=="render" then
                local id,ship=next(STA2E.startupRefreshQueue)
                if id then
                    STA2E.startupRefreshQueue[id]=nil
                    if STA2E.ships[id]==ship then
                        STA2E.startupFlushing=true;refresh(ship);STA2E.startupFlushing=false
                        STA2E.startupStats.rendered=STA2E.startupStats.rendered+1
                    end
                    schedule();return
                end
                done=true;STA2E.startupRefreshQueue=nil;STA2E.startupThread=nil;STA2E.startupRegistering=false
                STA2E.loading=false;STA2E.ready=true;STA2E.startupStage="complete"
                startupJobs=nil
                hud()
                print(string.format("STA2E startup: %.3fs elapsed after onLoad (serialized frame work; excludes compilation and asset loading)",Time.time-started))
            end
        end)
        if not ok and valid() then
            done=true;STA2E.ready=false;STA2E.loading=true;STA2E.reconciling=false
            STA2E.startupThread=nil;STA2E.startupRegistering=false;STA2E.startupFlushing=false;STA2E.startupRefreshQueue=nil;STA2E.startupStage="failed"
            print("STA2E startup failed: "..tostring(err))
            UI.setXml('<Panel rectAlignment="UpperLeft" offsetXY="58 -62" width="455" height="70" color="#642B2BEE"><Text color="#FFFFFF" fontSize="18">Fleet startup failed. See scripting log and reload the save.</Text></Panel>')
        end
    end
    Wait.frames(step,1)
end
function onSave() return JSON.encode({schemaVersion=1,game=STA2E.game,dice=STA2E.dice,diceOpen=STA2E.diceOpen,diceSource=STA2E.diceSource}) end

function onObjectDrop(color,object)
    local s=shipFor(object);local m=metadata(object)
    if s and m and (m.role=="base" or m.role=="baseModel" or m.role=="model") then STA2E_FollowModel(s) end
    if s and m and m.role=="card" then Wait.frames(function()refresh(s)end,1) end
    if m and (m.role=="upgrade" or m.role=="fleetCard") and STA2E.manageCard[color]==object.getGUID() then
        Wait.frames(function()hud()end,1)
    end
end
function onObjectDestroy(object)
    if not STA2E.ready then return end
    local die=DiceManager.byGuid[object.getGUID()]
    if die and own(die.color) then DiceManager.remove(die.color,die.guid);finishDiceBatch(die.color);hud() end
    local m=metadata(object)
    if not m then return end
    local s=STA2E.ships[m.instanceId]
    if not s then return end
    if m.role=="card" or m.role=="base" or m.role=="baseModel" then
        for color,session in pairs(STA2E.sensorEcho or {}) do
            if session.instanceId==s.instanceId then SensorEchoController.cancel(color,"The Sensor Echo ship or base was removed.") end
        end
    end
    if m.role=="card" and s.cardGUID==object.getGUID() then STA2E.ships[m.instanceId]=nil;STA2E.pending[m.instanceId]=nil
    elseif m.role=="baseModel" then s.refs.base=nil;s.refs.model=nil;refresh(s)
    elseif m.role=="base" and s.refs.base==object.getGUID() then
        local model=member(s,"model")
        s.refs.base=nil;s.refs.model=nil
        STA2E.pending[m.instanceId]=nil
        if model then model.destruct() end
        refresh(s)
    elseif s.refs[m.role]==object.getGUID() then s.refs[m.role]=nil;refresh(s) end
end


-- Alliance AI prototype v0.1. Behavior table is deliberately editable.
local AllianceAI={version="0.4",boardCenter={x=0,z=0}}
STA2E.AllianceAI=AllianceAI
local aiFallback={"CA","R","T","B","S"}
local function aiInstruction(speed,family,direction)
    return {speed=speed,family=family,direction=direction}
end
local function aiRow(engage,chase,escape) return {engage=engage,chase=chase,escape=escape} end
local function I(speed,family,direction) return aiInstruction(speed,family,direction) end
-- Front and flank groups; port/starboard use the same vector-relative instruction.
AllianceAI.behavior={
 [1]={
  [1]={front=aiRow(I("slow","S"),I("slow","B","toward"),I("slow","B","away")),flank=aiRow(I("slow","B","toward"),I("slow","T","toward"),I("slow","B","away"))},
  [2]={front=aiRow(I("slow","S"),I("slow","S"),I("slow","B","away")),flank=aiRow(I("slow","B","toward"),I("middle","B","toward"),I("slow","B","away"))},
  [3]={front=aiRow(I("fast","S"),I("fast","S"),I("fast","B","away")),flank=aiRow(I("fast","B","toward"),I("fast","B","toward"),I("fast","B","away"))}
 },
 [2]={
  [1]={front=aiRow(I("slow","T","toward"),I("slow","T","toward"),I("slow","B","away")),flank=aiRow(I("slow","T","toward"),I("slow","T","toward"),I("slow","B","away"))},
  [2]={front=aiRow(I("slow","B","toward"),I("slow","T","toward"),I("slow","B","away")),flank=aiRow(I("slow","T","toward"),I("middle","B","toward"),I("slow","B","away"))},
  [3]={front=aiRow(I("fast","B","toward"),I("fast","B","toward"),I("fast","B","away")),flank=aiRow(I("fast","B","toward"),I("fast","B","toward"),I("fast","B","away"))}
 },
 [3]={
  [1]={front=aiRow(I("fast","CA"),I("slow","T","toward"),I("slow","B","away")),flank=aiRow(I("fast","CA"),I("slow","T","toward"),I("slow","B","away"))},
  [2]={front=aiRow(I("fast","CA"),I("slow","T","toward"),I("slow","B","away")),flank=aiRow(I("fast","CA"),I("slow","T","toward"),I("slow","B","away"))},
  [3]={front=aiRow(I("fast","T","toward"),I("fast","T","toward"),I("fast","B","away")),flank=aiRow(I("fast","T","toward"),I("fast","T","toward"),I("fast","B","away"))}
 },
 [4]={}
}
for range=1,3 do
 local row=aiRow(I("fast","CA"),I(range==3 and "fast" or "slow","T","toward"),I("fast","S"))
 AllianceAI.behavior[4][range]={front=row,flank=row}
end
function AllianceAI.resolve(dial,instruction,hand)
 -- Maneuver keys already use pilot-facing left/right; no extra mirror is needed.
 local start
 for i,family in ipairs(aiFallback) do if family==instruction.family then start=i end end
 if not start then return nil,"Unsupported bearing" end
 for index=start,#aiFallback do
  local family=aiFallback[index]
  local candidates={}
  for _,entry in ipairs(dial) do
   local prefix,speed=entry.key:match("^([A-Z]+)(%d+)$")
   local matches=prefix==family
   if family=="T" or family=="B" then
    if not hand then return nil,"Toward/Away is ambiguous: choose Port or Starboard override" end
    matches=prefix==family..hand
   end
   if matches and MOVE_DEFS[entry.key] then table.insert(candidates,{entry=entry,speed=tonumber(speed)}) end
  end
  table.sort(candidates,function(a,b) return a.speed<b.speed end)
  if #candidates>0 then
   local preference=index==start and instruction.speed or "fast"
   local pick=preference=="slow" and 1 or (preference=="middle" and math.floor((#candidates+1)/2) or #candidates)
   return candidates[pick].entry,index>start
  end
 end
 return nil,"No supported maneuver in fallback chain"
end
function AllianceAI.zone(boundary,point)
 local x,z=worldToLocal(boundary,point)
 local hx=boundary.footprint.halfWidth or 1.4
 local hz=boundary.footprint.halfLength or 1.4
 if z>hz then return 4 end
 if z<=-hz and math.abs(x)<=hx then return 1 end
 if z<=-hz and math.abs(x)-hx<=-z-hz then return 2 end
 return 3
end
function AllianceAI.aspect(targetBoundary,aiPoint)
 local x,z=worldToLocal(targetBoundary,aiPoint)
 if -z>=math.abs(x) then return "Front","front" end
 -- Port and Starboard flank sectors wrap around the entire rear.
 return x>=0 and "Port Flank" or "Starboard Flank","flank"
end
function AllianceAI.vectorHand(aiBoundary,targetBoundary,previousHand)
 -- Choose by the target's signed bearing from the AI ship. A small dead zone
 -- retains the prior hand so nearly aligned ships do not alternate left/right.
 local x=worldToLocal(aiBoundary,targetBoundary.center)
 local halfWidth=(aiBoundary.footprint and aiBoundary.footprint.halfWidth) or 1.4
 local deadZone=math.max(0.18,halfWidth*0.12)
 if math.abs(x)<=deadZone then return previousHand end
 return x>0 and "R" or "L"
end
local function aiSide(s) return s.side or (s.ai and s.ai.enabled and "enemy" or "allied") end
local function aiSnapshot(s)
 local b=member(s,"base")
 if not b then return nil end
 local p,r=b.getPosition(),b.getRotation()
 return {x=p.x,z=p.z,yaw=r.y,definitionId=s.definitionId,side=aiSide(s)}
end
local function aiSame(a,b)
 return a and b and math.abs(a.x-b.x)<0.01 and math.abs(a.z-b.z)<0.01 and math.abs(a.yaw-b.yaw)<0.01 and a.definitionId==b.definitionId and a.side==b.side
end
local AI_TARGET_LEAD=3.0
local function aiProjectedMeasure(s,target,measure)
 if not measure or skillFor(target)<=skillFor(s) then return measure,false end
 local source=measure.targetBoundary
 local projected={center={x=source.center.x,z=source.center.z},yaw=source.yaw or 0,points={}}
 local yaw=math.rad(projected.yaw or 0)
 local dx,dz=-math.sin(yaw)*AI_TARGET_LEAD,-math.cos(yaw)*AI_TARGET_LEAD
 projected.center={x=projected.center.x+dx,z=projected.center.z+dz}
 projected.points={}
 for _,point in ipairs(measure.targetBoundary.points or {}) do table.insert(projected.points,{x=point.x+dx,z=point.z+dz}) end
 local nearest=MeasurementGeometry.nearestPoints(measure.attackerBoundary,projected)
 return {range=math.max(1,math.min(3,math.ceil(nearest.distance/RANGE_SEGMENT))),baseEdgeDistance=nearest.distance,
  attackerBoundary=measure.attackerBoundary,targetBoundary=projected,nearest=nearest},true
end
local function aiAngleDistance(a,b) return math.abs(((a-b+180)%360)-180) end
local function aiAssessmentSnapshot(s)
 local base=member(s,"base");if not base then return nil end
 local p,r=base.getPosition(),base.getRotation()
 local snapshot={start={x=p.x,z=p.z,yaw=r.y},shape=baseShape(base),terrain=terrainSnapshot(base),blockers={},boundary=MeasurementGeometry.boundary(s)}
 for id,other in pairs(STA2E.ships) do if id~=s.instanceId then
  local otherBase=member(other,"base");if otherBase then
   local op,orr=otherBase.getPosition(),otherBase.getRotation()
   table.insert(snapshot.blockers,{pose={x=op.x,z=op.z,yaw=orr.y},shape=baseShape(otherBase),reason="ship"})
  end
 end end
 for _,item in ipairs(snapshot.terrain) do if item.kind=="planet" then
  table.insert(snapshot.blockers,{pose=item.pose,shape=item.shape,reason="planet"})
 end end
 return snapshot
end
local function aiAssessMove(s,entry,targetBoundary,preferredKey,snapshot)
 local move=entry and MOVE_DEFS[entry.key]
 snapshot=snapshot or aiAssessmentSnapshot(s)
 if not snapshot or not move then return nil end
 local start,shape,terrain,blockers=snapshot.start,snapshot.shape,snapshot.terrain,snapshot.blockers
 local stop,stopReason=latestLegal(start,move,shape,blockers);local finish=pose(start,move,stop,shape.z)
 local hits=movementTerrainHits(start,move,stop,shape,terrain);local hazards={};local penalty=0
 if stopReason=="planet" then penalty=penalty+100;table.insert(hazards,"planet landing")
 elseif stop<0.999 then penalty=penalty+7+(1-stop)*18;table.insert(hazards,"ship bump") end
 for _,hit in ipairs(hits) do
  local cost=hit.kind=="minefield" and 18 or 11
  if hit.finalOverlap then cost=cost+7 end
  penalty=penalty+cost;table.insert(hazards,hit.label)
 end
 local edgeRisk=STA2E_Playtest.edgeRisk(finish,shape)
 if edgeRisk>0 then penalty=penalty+edgeRisk;table.insert(hazards,"battlefield edge") end
 local target=targetBoundary.center;local dx,dz=target.x-finish.x,target.z-finish.z
 local distance=math.sqrt(dx*dx+dz*dz);local desired=math.deg(math.atan2(-dx,-dz))
 if s.ai.intent=="escape" then desired=desired+180 end
 local startBoundary=snapshot.boundary
 if startBoundary then
  local targetX=worldToLocal(startBoundary,target);local finishX=worldToLocal(startBoundary,{x=finish.x,z=finish.z})
  if s.ai.intent=="escape" then targetX=-targetX end
  if math.abs(targetX)>0.25 and finishX*targetX<0 then penalty=penalty+16;table.insert(hazards,"wrong-way veer") end
 end
 local tactical=STA2E_Playtest.moveScore(s,entry,snapshot,finish,targetBoundary,stop)
 local preference=entry.key==preferredKey and 0 or 0.75
 return {entry=entry,score=tactical+preference+penalty,penalty=penalty,hazards=hazards,stop=stop}
end
local function aiObstacleChoice(s,preferred,targetBoundary)
 local choices={}
 local snapshot=aiAssessmentSnapshot(s)
 for _,candidate in ipairs(dialFor(s)) do
  if MOVE_DEFS[candidate.key] then local result=aiAssessMove(s,candidate,targetBoundary,preferred.key,snapshot);if result then table.insert(choices,result) end end
 end
 table.sort(choices,function(a,b) if math.abs(a.score-b.score)>0.0001 then return a.score<b.score end return a.entry.key<b.entry.key end)
 local selected=choices[1];if not selected then return preferred,nil end
 local preferredResult
 for _,choice in ipairs(choices) do if choice.entry.key==preferred.key then preferredResult=choice;break end end
 -- Score every legal maneuver, including clear paths: the old early return ignored better firing solutions.
 local note
 if selected.entry.key~=preferred.key then
  note=preferredResult and #preferredResult.hazards>0 and ("avoids "..table.concat(preferredResult.hazards,", ")) or "better firing position / spacing"
 elseif selected.penalty>0 then note="accepts "..table.concat(selected.hazards,", ").." as the better route" end
 return selected.entry,note
end
local AI_ACQUISITION_DISTANCE=24.0
local function aiSelect(s)
 return STA2E_Playtest.selectTarget(s)
end
local function aiCenterTarget(s)
 local boundary=MeasurementGeometry.boundary(s)
 if not boundary then return nil end
 local center=AllianceAI.boardCenter
 local point={x=center.x,z=center.z}
 local targetBoundary={center=point,yaw=0,points={point},footprint={halfWidth=0,halfLength=0}}
 local nearest=MeasurementGeometry.nearestPoints(boundary,targetBoundary)
 local distance=nearest.distance
 return {centerTarget=true,target={name="Board Center"},zone=AllianceAI.zone(boundary,point),measure={range=math.max(1,math.min(3,math.ceil(distance/RANGE_SEGMENT))),attackerBoundary=boundary,targetBoundary=targetBoundary}}
end
local function aiEvaluate(s)
 local found=aiSelect(s)
 if not found then s.ai.plan=nil;s.ai.message="No living opponent with a deployed base. Deploy player ships and check allegiance in Ship Controls.";return end
 local m=found.measure
 -- Steering is AI-centric: target facing does not change the maneuver row.
 local aspect=found.centerTarget and "Board Center" or "Direct Approach"
 local group="front"
 local actualRange=math.max(1,m.range)
 local range=math.min(3,actualRange)
 local instruction=AllianceAI.behavior[found.zone][range][group][s.ai.intent]
 local toward=s.ai.hand
 if not toward then
  local marker=string.byte(tostring(s.instanceId or s.name or "AI"),-1) or 0
  local stableHand=s.ai.lastHand or (marker%2==0 and "L" or "R")
  toward=AllianceAI.vectorHand(m.attackerBoundary,m.targetBoundary,stableHand)
 end
 if toward then s.ai.lastHand=toward end
 local hand=toward
 if instruction.direction=="away" then hand=toward and (toward=="L" and "R" or "L") end
 -- Come About/Reverse fallbacks inherit a toward direction.
 local entry,fallback=AllianceAI.resolve(dialFor(s),instruction,hand)
 if not entry then s.ai.plan=nil;s.ai.message="Manual decision: "..fallback;return end
 local avoidance;entry,avoidance=aiObstacleChoice(s,entry,m.targetBoundary)
 s.ai.plan={key=entry.key,targetId=found.target.instanceId,centerTarget=found.centerTarget or false,center=found.centerTarget and copy(AllianceAI.boardCenter) or nil,zone=found.zone,range=actualRange,tacticalRange=range,aspect=aspect,instruction=copy(instruction),hand=hand,fallback=fallback,projected=found.projected or false,avoidance=avoidance,round=STA2E.game.round,intent=s.ai.intent,source=aiSnapshot(s),target=not found.centerTarget and aiSnapshot(found.target) or nil}
 s.ai.message=found.target.name..(found.projected and " | Lead +3" or "").." | Zone "..found.zone.." | Range "..actualRange.." | "..aspect.."\n"..string.upper(s.ai.intent)..": "..instruction.speed.." "..instruction.family.." "..(instruction.direction or "").." → "..maneuverLabel(s,entry.key)..(fallback and " (fallback)" or "")..(avoidance and " · "..avoidance or "")
end
local function aiAuxTokens(s)
 local out={}
 for _,object in ipairs(getAllObjects()) do
  if object.getGMNotes()=="STA2E_SHIP_TOKEN|"..s.instanceId.."|AUX" then table.insert(out,object) end
 end
 table.sort(out,function(a,b)return a.getGUID()<b.getGUID() end)
 return out
end
AllianceAI.actionEvaluators=AllianceAI.actionEvaluators or {}
function AllianceAI.registerActionEvaluator(key,evaluator) AllianceAI.actionEvaluators[key]=evaluator end
local function aiTokenSnapshot()
 local tokens={}
 for _,object in ipairs(getAllObjects()) do
  local note=object.getGMNotes and object.getGMNotes() or ""
  local instance,key=note:match("^STA2E_SHIP_TOKEN|([^|]+)|([^|]+)$")
  if instance then tokens[instance]=tokens[instance] or {};tokens[instance][key]=true end
 end
 return tokens
end
local function aiHasToken(s,key,tokens)
 tokens=tokens or aiTokenSnapshot()
 return tokens[s.instanceId] and tokens[s.instanceId][key]==true or false
end
local function aiActionContext(s)
 local tokens=aiTokenSnapshot()
 local selected=aiSelect(s);local target=selected and selected.target or nil
 local measure=target and MeasurementGeometry.measure(s,target) or nil
 local enemyIn12=target and measure and measure.baseEdgeDistance<=12.0 or false
 local attack=measure and measure.range<=3 and (measure.arcs.primary or measure.arcs.rear or measure.arcs.secondary) or false
 local threats=0
 for id,enemy in pairs(STA2E.ships) do if id~=s.instanceId and aiSide(enemy)~=aiSide(s) then
  local incoming=MeasurementGeometry.measure(enemy,s)
  if incoming and incoming.range<=3 and (incoming.arcs.primary or incoming.arcs.rear or incoming.arcs.secondary) then threats=threats+1 end
 end end
 local cloaked=target and (target.state and target.state.action=="CLK" or aiHasToken(target,"CLK",tokens)) or false
 return {tokens=tokens,target=target,measure=measure,enemyIn12=enemyIn12,meaningfulAttack=attack,threats=threats,cloakedTarget=cloaked,
  higherSkill=target and skillFor(target)>skillFor(s) or false,intent=s.ai.intent or "engage"}
end
AllianceAI.registerActionEvaluator("BS",function(s,c)
 if not c.target then return nil end
 local score=70+(c.meaningfulAttack and 15 or 0)+(c.measure and c.measure.range==1 and 10 or 0)+math.min(c.threats,2)*3
 return score,"attack and defense flexibility"
end)
AllianceAI.registerActionEvaluator("TL",function(s,c)
 if not c.target or not c.enemyIn12 or aiHasToken(s,"TL",c.tokens) then return nil end
 local score=78+((c.measure and c.measure.range>=2) and 10 or 0)+(c.meaningfulAttack and 4 or 0)
 return score,"target available at Range "..tostring(c.measure and c.measure.range or "?")
end)
AllianceAI.registerActionEvaluator("EVA",function(s,c)
 if aiHasToken(s,"EVA",c.tokens) then return nil end
 local score=45+c.threats*12+(c.intent=="escape" and 15 or 0)+(c.higherSkill and 10 or 0)
 return score,c.threats>0 and (tostring(c.threats).." incoming firing solution(s)") or "defensive fallback"
end)
AllianceAI.registerActionEvaluator("SCN",function(s,c)
 if aiHasToken(s,"SCN",c.tokens) then return nil end
 if not c.enemyIn12 then return 38,"no enemy within 12; sensor sweep" end
 return 35+(c.cloakedTarget and 55 or 0)+(c.meaningfulAttack and 5 or 0),c.cloakedTarget and "target is cloaked" or "target acquisition support"
end)
AllianceAI.registerActionEvaluator("CLK",function(s,c)
 if aiHasToken(s,"CLK",c.tokens) then return nil end
 return 50+c.threats*10,"reduce incoming threat"
end)
AllianceAI.registerActionEvaluator("REG",function(s,c)
 if aiHasToken(s,"REG",c.tokens) then return nil end
 return 25,"regeneration available; damage state is manual"
end)
function STA2E_AllianceChooseAction(params)
 local s=params and params.ship;if not s or not (s.ai and s.ai.enabled) then return nil end
 local context=aiActionContext(s);local candidates={}
 for _,key in ipairs((s.capabilities and s.capabilities.actions) or {}) do
  local evaluator=AllianceAI.actionEvaluators[key]
  if evaluator and (key=="ECHO" or obj(ACTION_BAGS[key])) then
   local score,reason=evaluator(s,context)
   if score then table.insert(candidates,{key=key,score=score,reason=reason}) end
  end
 end
 table.sort(candidates,function(a,b) if a.score~=b.score then return a.score>b.score end return a.key<b.key end)
 local selected=candidates[1]
 if selected then selected.target=context.target;selected.context=context end
 return selected
end
function STA2E_AI_AfterMove(s,key)
 if not (s.ai and s.ai.enabled) then return end
 if s.state.lastMoveBlocked then
  s.state.status="complete";s.state.aiSkipAction=true;s.ai.plan=nil
  s.ai.lastAction={key="SKIP",reason="movement contact prevents an action",round=STA2E.game.round}
  broadcastToAll("[AI] "..s.name..": no action after movement contact.",{1,0.7,0.3});return
 end
 local entry=maneuver(s,key)
 if entry and entry.difficulty=="red" then
  local tokens=aiAuxTokens(s)

  s.state.aiSkipAction=true;s.state.status="complete";s.ai.plan=nil
  broadcastToAll("[AI] "..s.name..": red maneuver; "..(#tokens>0 and "existing Aux retained" or "no Aux gained").."; normal action skipped.",{1,0.7,0.3})
  return
 end
 local choice=STA2E_AllianceChooseAction({ship=s})
 if choice then
  spawnActionToken(s,choice.key);s.state.action=choice.key;s.state.status="complete"
  s.ai.lastAction={key=choice.key,score=choice.score,reason=choice.reason,targetId=choice.target and choice.target.instanceId,round=STA2E.game.round}
  if choice.key=="TL" then s.state.targetLockId=choice.target and choice.target.instanceId end
  broadcastToAll("[AI] "..s.name.." action: "..choice.key.." - "..choice.reason..".",{0.75,0.85,1})
 else
  broadcastToAll("[AI] "..s.name..": no useful automatic action; use the dial for manual or card-granted actions.",{1,0.75,0.35})
 end
 s.ai.plan=nil
end
local aiOldRender=render
render=function(s)
 aiOldRender(s)
 if not (s.ai and s.ai.enabled) then return end
 if s.state.toolsPage then return end
 local base=member(s,"base")
 if base then
  s.ai.baseNames=s.ai.baseNames or {}
  local guid=base.getGUID()
  s.ai.baseNames[guid]=s.ai.baseNames[guid] or base.getName()
  base.setName("AI — "..s.name)
 end
 local dial=member(s,"dial")
 if not dial or not s.state.dialOpen then return end
 local p={'<Panel width="700" height="820" position="0 0 -120" rotation="0 0 180" scale="0.4 0.4 1" color="#00000000" raycastTarget="false">',
 '<Panel width="700" height="820" color="#102432F5">',
 '<Text text="AI · '..xml(s.name)..'" position="0 370 0" width="670" height="40" fontSize="24" color="#FFD86B"/>',
 '<Text text="'..xml((s.ai.tacticOverride and "MANUAL TACTIC | " or "AUTO TACTICS | ")..aiSide(s).." | "..s.state.status)..'" position="0 325 0" width="670" height="32" fontSize="20" color="#FFFFFF"/>'}
 local function B(id,label,x,y,color,width) table.insert(p,dialButton(id,label,x,y,color or "#285779",width or 200)) end
 B("ship_settings","SHIP CONTROLS",0,265,"#375A78",420)
 table.insert(p,'<Text text="'..xml(s.ai.message or "Press PLAN to choose a target and maneuver automatically.")..'" position="0 135 0" width="660" height="165" fontSize="19" color="#FFFFFF"/>')
 B("ai_evaluate","PLAN",-170,10,"#256348",300);B("ai_execute","EXECUTE",170,10,"#863B3B",300)
 B("quick_range","RANGE",-220,-60);B("quick_ai_arcs","AI SECTORS",0,-60);B("tool_home","SHIP TOOLS",220,-60)
 local keys=(s.capabilities and s.capabilities.actions) or {}
 for index,key in ipairs(keys) do B("ai_action_"..key,key,-220+((index-1)%3)*220,-135-math.floor((index-1)/3)*55) end
 B("ai_finish","FINISH",-220,-270);B("ai_undo","UNDO",0,-270,"#526777");B("ai_aux","ADD AUX",220,-270)
 B("open_dial","CLOSE DIAL",0,-340,"#375A78",420)
 table.insert(p,'</Panel></Panel>')
 STA2E_SetDialXml(dial,table.concat(p):gsub('<Button ','<Button textColor="#FFFFFF" '))
end
local aiOldCommand=STA2E_Command
function STA2E_Command(params)
 local s=shipFor(params.object)
 local cmd=params.command or ""
 if not s then return aiOldCommand(params) end
 local ai=s.ai and s.ai.enabled
 if cmd:sub(1,3)~="ai_" then
  if ai and s.state.aiSkipAction and cmd:sub(1,7)=="action_" then tell(params.color,"AI normal action skipped after red maneuver.");return end
  return aiOldCommand(params)
 end
 if STA2E.pendingMoves[s.instanceId] then tell(params.color,"Wait for movement to finish.");return end
 if cmd=="ai_toggle" then
  s.ai=s.ai or {intent="engage"};s.ai.intent=s.ai.intent or "engage"
  s.ai.enabled=not ai;s.ai.plan=nil
  s.side=s.ai.enabled and "enemy" or "allied"
  if not s.ai.enabled then
   local base=member(s,"base")
   if base and s.ai.baseNames and s.ai.baseNames[base.getGUID()] then base.setName(s.ai.baseNames[base.getGUID()]) end
  end
  refresh(s);hud();return
 end
 if not ai then return end
 if cmd=="ai_side" then s.side=aiSide(s)=="enemy" and "allied" or "enemy";s.ai.plan=nil
 elseif cmd=="ai_engage" or cmd=="ai_chase" or cmd=="ai_escape" then s.ai.intent=cmd:sub(4);s.ai.plan=nil
 elseif cmd=="ai_auto" or cmd=="ai_port" or cmd=="ai_starboard" then s.ai.hand=cmd=="ai_port" and "L" or (cmd=="ai_starboard" and "R" or nil);s.ai.plan=nil
 elseif cmd=="ai_evaluate" then
  if not complete(s) then tell(params.color,"Deploy / Repair first.");return end
  aiEvaluate(s);tell(params.color,s.ai.message)
 elseif cmd=="ai_execute" then
  if STA2E.game.phase~="activation" then tell(params.color,"Execute AI during Activation.");return end
  if s.state.status=="complete" or s.state.status=="action" then tell(params.color,"Already activated; use Undo before another execution.");return end
  local plan=s.ai.plan
  local target=plan and STA2E.ships[plan.targetId]
  local selected=aiSelect(s)
  local validTarget=false
  if plan and plan.centerTarget then
   validTarget=not selected and plan.center and plan.center.x==AllianceAI.boardCenter.x and plan.center.z==AllianceAI.boardCenter.z
  elseif plan then
   validTarget=target and aiSame(plan.target,aiSnapshot(target)) and selected and selected.target.instanceId==plan.targetId
  end
  if not plan or plan.round~=STA2E.game.round or plan.intent~=s.ai.intent or not aiSame(plan.source,aiSnapshot(s)) or not validTarget then
   s.ai.plan=nil;s.ai.message="Situation changed or no evaluation: press Evaluate again.";refresh(s);return
  end
  local before=copy(s.state)
  s.state.maneuver=plan.key;s.state.status="revealed";s.state.aiSkipAction=nil
  executeMove(s,params.color)
  if s.undo then s.undo.state=before end
 elseif cmd=="ai_undo" then
  if not s.undo or s.undo.round~=STA2E.game.round then tell(params.color,"No movement undo this round.");return end
  local removed=s.undo.aiRemovedAux
  aiOldCommand({object=params.object,color=params.color,command="undo"})
  if removed then removed.GUID=nil;spawnObjectData({data=removed}) end
  s.ai.plan=nil
 elseif cmd=="ai_aux" then spawnActionToken(s,"AUX")
 elseif cmd=="ai_finish" then
  if s.state.status~="action" then tell(params.color,"Finish is available after executing a maneuver.");return end
  s.state.status="complete"
 elseif cmd:sub(1,10)=="ai_action_" then
  if s.state.status~="action" or s.state.aiSkipAction then tell(params.color,"No normal action available.");return end
  return aiOldCommand({object=params.object,color=params.color,command="action_"..cmd:sub(11)})
 end
 refresh(s);hud()
end

-- Route every normal undo through Aux restoration; card-granted immediate
