 if s and s.ai and s.ai.enabled then
  if cmd=="undo" or cmd=="tool_undo" then
   return aiUndoCommand({object=params.object,color=params.color,command="ai_undo"})
  end
  if cmd=="move" then return aiUndoCommand({object=params.object,color=params.color,command="ai_execute"}) end
 end
 return aiUndoCommand(params)
end
local aiOldPhase=STA2E_PhaseUI
