local function basePose(s)
    local base=member(s,"base")
    if not base then return nil end
    local p,r=base.getPosition(),base.getRotation()
    return {x=p.x,z=p.z,yaw=r.y,object=base}
end
local function distance(a,b)
    local dx,dz=b.x-a.x,b.z-a.z
    return math.sqrt(dx*dx+dz*dz)
end
local function forwardDot(poseValue,target)
    local dx,dz=target.x-poseValue.x,target.z-poseValue.z;local length=math.sqrt(dx*dx+dz*dz)
    if length<0.001 then return 1 end
    local heading=math.rad(poseValue.yaw)
    return ((-math.sin(heading))*dx+(-math.cos(heading))*dz)/length
end
local function enemies(s,requireArc)
    local origin=basePose(s);local result={}
    if not origin then return result end
    for _,candidate in pairs(STA2E.ships) do
        if candidate.instanceId~=s.instanceId and candidate.owner~=s.owner then
            local target=basePose(candidate)
            if target then
                local range=distance(origin,target);local dot=forwardDot(origin,target)
                if range<=18.0 and (not requireArc or dot>=0.7071) then
                    table.insert(result,{ship=candidate,range=range,dot=dot})
                end
            end
        end
    end
    table.sort(result,function(a,b)
        local focus=m5State().fleetFocus[s.owner]
        if (a.ship.instanceId==focus)~=(b.ship.instanceId==focus) then return a.ship.instanceId==focus end
        local ah=a.ship.combat and a.ship.combat.hull or 99
        local bh=b.ship.combat and b.ship.combat.hull or 99
        if ah~=bh then return ah<bh end
        return a.range<b.range
    end)
    return result
end
function M5.selectTarget(s,requireArc)
    local list=enemies(s,requireArc)
    return list[1] and list[1].ship or nil,list[1]
end

-- Uses the newer Remodulated candidate-pose evaluator. The printed 2024 chart
-- is not consulted. Collision truncation remains owned by executeMove().
function M5.chooseManeuver(s)
    local start=basePose(s);if not start then return nil,"Deploy the M5 ship first." end
    local target=M5.selectTarget(s,false);local targetPose=target and basePose(target) or {x=0,z=0,yaw=0}
    local best=nil
    for _,entry in ipairs(dialFor(s) or {}) do
        local move=MOVE_DEFS[entry.key]
        if move then
            local finish=STA2E.Movement.pose(start,move,1,baseShape(member(s,"base")).z)
            local range=distance(finish,targetPose);local dot=forwardDot(finish,targetPose)
            local desired=range>=5 and range<=11 and 32 or -math.abs(range-8)*3
            local arc=dot>=0.7071 and 45 or dot*18
            local close=distance(start,targetPose)>12 and (distance(start,targetPose)-range)*2 or 0
            local edge=math.max(0,math.abs(finish.x)-34)*20+math.max(0,math.abs(finish.z)-34)*20
            local difficulty=entry.difficulty=="red" and -8 or (entry.difficulty=="green" and 3 or 0)
            if s.state and s.state.auxiliary and entry.difficulty=="green" then difficulty=difficulty+12 end
            local score=desired+arc+close+difficulty-edge
            if not best or score>best.score or (score==best.score and entry.key<best.key) then
                best={key=entry.key,score=score,range=range,dot=dot,target=target and target.instanceId or nil}
            end
        end
    end
    if not best then return nil,"No supported maneuver exists on this dial." end
    return best
end
function M5.planShip(s)
    if not isControlled(s) then return nil,"Ship is not M5 controlled." end
    local choice,err=M5.chooseManeuver(s);if not choice then return nil,err end
    s.state=s.state or {};s.state.maneuver=choice.key;s.state.status="ready"
    s.m5.navigationTarget=choice.target;s.m5.intent=choice
    M5.Events.emit(M5.TIMING.MANEUVER_SELECTED,{ship=s,choice=choice})
    refresh(s);return choice
end

local function hasAction(s,key) return contains(s.capabilities and s.capabilities.actions,key) end
function M5.runActionTree(s)
    if not isControlled(s) or not s.state or s.state.status~="action" then return nil end
    local target=M5.selectTarget(s,false);local chosen=nil
    for _,node in ipairs(s.m5.actionTree or {}) do
        local valid=node.condition=="always" or (node.condition=="has_aux" and s.state.auxiliary) or (node.condition=="has_target" and target~=nil)
        if valid and (node.action=="CLEAR_AUX" or hasAction(s,node.action)) then chosen=node.action;break end
    end
    if s.m5.preferredAction and target and hasAction(s,s.m5.preferredAction) then chosen=s.m5.preferredAction end
    M5.Events.emit(M5.TIMING.ACTION_STEP,{ship=s,target=target,action=chosen})
    if chosen=="CLEAR_AUX" then s.state.auxiliary=false;s.state.action="CLEAR_AUX";s.state.status="complete";refresh(s)
    elseif chosen then STA2E_Command({object=obj(s.cardGUID),color=s.owner,command="action_"..chosen})
    else s.state.status="complete";refresh(s) end
    s.m5.preferredAction=nil
    return chosen
end

local previousRefresh=refresh
refresh=function(s)
    previousRefresh(s)
    if isControlled(s) and s.state and s.state.status=="action" and not s.state.m5ActionPending then
        s.state.m5ActionPending=true;commit(s)
        Wait.frames(function()
            if STA2E.ships[s.instanceId] and s.state and s.state.status=="action" then
                s.state.m5ActionPending=nil
                M5.Events.emit(M5.TIMING.AFTER_MOVE,{ship=s,target=M5.selectTarget(s,false)})
                M5.runActionTree(s)
            end
        end,1)
    end
end

local function ensureCombat(s)
    if s.combat then return s.combat end
    local profile=isControlled(s) and M5.SHIP_PROFILES[s.m5.profileId] or SHIP_COMBAT_STATS[s.definitionId]
    if not profile then return nil,"No verified combat stats for "..tostring(s.definitionId).."; resolve damage manually." end
    local shields=tonumber(profile.shields)
    local hull,agility=tonumber(profile.hull),tonumber(profile.agility)
    if not hull or not agility or not shields then return nil,"Incomplete combat stats; resolve damage manually." end
    s.combat={hull=hull,maxHull=hull,shields=shields,maxShields=shields,agility=agility,destroyed=false,statsVersion=1}
    return s.combat
end
local function attackDie()
    local face=math.random(1,8)
    if face<=3 then return "hit" elseif face==4 then return "critical" elseif face<=6 then return "battlestations" else return "blank" end
end
local function defenseDie()
    local face=math.random(1,8)
    if face<=3 then return "evade" elseif face<=5 then return "battlestations" else return "blank" end
end
local function count(values,key)local n=0;for _,value in ipairs(values) do if value==key then n=n+1 end end;return n end
function M5.primaryAttack(s)
    if not isControlled(s) then return nil,"Ship is not M5 controlled." end
    local defender,geometry=M5.selectTarget(s,true)
    if not defender then return nil,"No enemy is in primary arc at Range 1-3." end
    local defense,statsError=ensureCombat(defender);if not defense then return nil,statsError end
    local profile=M5.SHIP_PROFILES[s.m5.profileId];if not profile then return nil,"Unknown M5 combat profile." end
    local context={attacker=s,defender=defender,weapon="primary",attackDice=profile.attack,range=geometry.range,effects={}}
    M5.Events.emit(M5.TIMING.ATTACK_DECLARE,context)
    context.attackResults={};for _=1,context.attackDice do table.insert(context.attackResults,attackDie()) end
    M5.Events.emit(M5.TIMING.ATTACK_ROLL,context)
    if s.state and s.state.action=="BS" then
        for i,value in ipairs(context.attackResults) do if value=="battlestations" then context.attackResults[i]="hit" end end
    end
    M5.Events.emit(M5.TIMING.ATTACK_MODIFY,context)
    context.defenseResults={}
    for _=1,defense.agility do table.insert(context.defenseResults,defenseDie()) end
    M5.Events.emit(M5.TIMING.DEFENSE_ROLL,context)
    if defender.state and defender.state.action=="EVA" then table.insert(context.defenseResults,"evade") end
    M5.Events.emit(M5.TIMING.DEFENSE_MODIFY,context)
    local hits=count(context.attackResults,"hit")+count(context.attackResults,"critical")
    local evades=count(context.defenseResults,"evade")
    local damage=math.max(0,hits-evades);local shields=math.min(defense.shields,damage)
    defense.shields=defense.shields-shields;defense.hull=defense.hull-(damage-shields)
    defense.destroyed=defense.hull<=0;context.hits=hits;context.evades=evades;context.damage=damage
    s.state.fired=true;s.m5.combatTarget=defender.instanceId
    M5.Events.emit(M5.TIMING.ATTACK_RESOLVED,context)
    refresh(s);refresh(defender)
    broadcastToAll(s.name.." attacks "..defender.name.." with its primary weapon: "..hits.." hit/critical, "..evades.." evade, "..damage.." damage.",{0.90,0.72,0.30})
    return context
end

local function orderedControlled(phase)
    local result={};for _,s in pairs(STA2E.ships) do if isControlled(s) then table.insert(result,s) end end
    table.sort(result,function(a,b)
        local x,y=skillFor(a),skillFor(b)
        if x~=y then if phase=="combat" then return x>y else return x<y end end
        return a.instanceId<b.instanceId
    end)
    return result
end
function M5.run(color)
    local phase=STA2E.game.phase
    if phase=="planning" then
        M5.Events.emit(M5.TIMING.PLANNING_START,{color=color})
        local planned=0;for _,s in ipairs(orderedControlled(phase)) do if not s.state.maneuver then local choice=M5.planShip(s);if choice then planned=planned+1 end end end
        return "M5 planned "..planned.." ship(s)."
    elseif phase=="activation" then
        for _,s in ipairs(orderedControlled(phase)) do
            if s.state.status=="planning" then M5.planShip(s) end
            if s.state.status=="ready" then
                s.state.status="revealed";s.state.revealedOriginal=s.state.maneuver
                M5.Events.emit(M5.TIMING.MANEUVER_REVEALED,{ship=s,maneuver=s.state.maneuver})
                refresh(s);executeMove(s,s.owner);return "M5 activated "..s.name.."."
            end
        end
        return "All M5 ships have activated."
    elseif phase=="combat" then
        M5.Events.emit(M5.TIMING.COMBAT_START,{color=color})
        for _,s in ipairs(orderedControlled(phase)) do
            if not s.state.fired then local result,err=M5.primaryAttack(s);if result then return "M5 resolved "..s.name.."'s attack." else s.state.fired=true;refresh(s);return s.name..": "..err end end
        end
        return "All M5 ships have attacked."
    else
        M5.Events.emit(M5.TIMING.END_PHASE,{color=color});return "M5 end-phase events resolved."
    end
end

local function programCardData(program,profile)
    local back=CATALOG[profile.shipCardId] and CATALOG[profile.shipCardId].cardBack or "https://i.imgur.com/21bhPTi.jpg"
    return {Name="Custom_Tile",Transform={posX=0,posY=1.2,posZ=0,rotX=0,rotY=180,rotZ=0,scaleX=1.45,scaleY=1,scaleZ=1.0},
        Nickname="M5 · "..program.name,Description="M5 PROGRAM\nCS "..signed(program.csModifier).." · Threat +"..program.threat.." · Slots "..program.slots.."\n"..program.text,
        GMNotes="M5_PROGRAM:"..program.id,ColorDiffuse={r=0.22,g=0.26,b=0.30},Locked=false,Grid=true,Snap=true,Hands=true,
        CustomImage={ImageURL=back,ImageSecondaryURL="",ImageScalar=1,WidthScale=0,CustomTile={Type=0,Thickness=0.1,Stackable=false,Stretch=true}},LuaScript="",LuaScriptState="",XmlUI=""}
end

M5.CATALOG=JSON.decode([====[{"version":1,"status":"prototype","ships":[{"id":"M5S001","profileId":"neghvar","name":"Neg'Var","faction":"Klingon","class":"Negh'var Class","physicalShipId":"S193","baseCaptainSkill":4,"baseThreat":6,"slotCapacity":4}],"programs":[{"id":"focused_barrage","name":"Focused Barrage","faction":"Klingon","classes":["Negh'var Class","Vor'cha Class"],"csModifier":3,"threat":3,"slots":2,"status":"prototype adaptation","text":"When declaring a primary attack, select the defender as fleet focus and add one attack die."},{"id":"hunters_algorithm","name":"Hunter's Algorithm","faction":"Klingon","classes":["Negh'var Class","K'Vort Class","B'Rel Class"],"csModifier":-2,"threat":1,"slots":1,"status":"prototype proof program","text":"After moving, prefer Target Lock when a legal enemy is available. Lower CS lets this ship activate earlier."}]}]====])
-- Integration with the user's October 4 Remodulated save.
-- Call the actual current navigation evaluator, including target acquisition,
-- intent, center approach, terrain avoidance, and public-position snapshots.
function M5.chooseManeuver(s)
    if not complete(s) then return nil,"Deploy the M5 ship first." end
    s.ai=s.ai or {};s.ai.enabled=true;s.ai.intent=s.ai.intent or "engage"
    s.side=s.side or "enemy"
    aiEvaluate(s)
    local plan=s.ai.plan
    if not plan then return nil,s.ai.message end
    return {key=plan.key,target=plan.targetId,range=plan.range,reason=s.ai.message}
end

function M5.selectTarget(s,requireArc)
    local candidates={}
    for _,target in pairs(STA2E.ships) do
        if target~=s and aiSide(s)~=aiSide(target) and not (target.combat and target.combat.destroyed) then
            local measure=MeasurementGeometry.measure(s,target)
            if measure and measure.range>=1 and measure.range<=3 and (not requireArc or measure.arcs.primary) then
                table.insert(candidates,{ship=target,range=measure.range,distance=measure.baseEdgeDistance})
            end
        end
    end
    local state=m5State();local focus=state.fleetFocusRound[s.owner]==STA2E.game.round and state.fleetFocus[s.owner] or nil
    table.sort(candidates,function(a,b)
        if (a.ship.instanceId==focus)~=(b.ship.instanceId==focus) then return a.ship.instanceId==focus end
        if a.distance~=b.distance then return a.distance<b.distance end
        return a.ship.instanceId<b.ship.instanceId
    end)
    return candidates[1] and candidates[1].ship or nil,candidates[1]
end

-- Existing movement already calls this hook. Use one action path for M5;
-- other AI ships retain their existing action evaluation.
local originalAfterMove=STA2E_AI_AfterMove
function STA2E_AI_AfterMove(s,key)
    if not isControlled(s) then return originalAfterMove(s,key) end
    M5.Events.emit(M5.TIMING.AFTER_MOVE,{ship=s,key=key})
    M5.runActionTree(s)
    s.ai.plan=nil
end

-- Remove the older refresh-based after-move hook: this save supplies an exact
-- movement completion callback, including terrain and movement cancellation.
refresh=previousRefresh

local originalM5Run=M5.run
function M5.run(color)
    if next(STA2E.pendingMoves) then return "Wait for movement to finish." end
    for _,s in pairs(STA2E.ships) do
        if isControlled(s) then
            s.ai=s.ai or {intent="engage"};s.ai.enabled=true;s.side=s.side or "enemy"
        end
    end
    return originalM5Run(color)
end

-- Website-owned fleet construction. TTS consumes IDs and recomputes totals;
-- imported JSON cannot install executable effects or override profile values.
local function profileById(id)
    for _,p in ipairs(M5.CATALOG.ships or {}) do if p.id==id then return p end end
end
local function installCatalog()
    for _,p in ipairs(M5.CATALOG.ships or {}) do
        local original=CATALOG[p.physicalShipId]
        if original then
            local card=copy(original);card.id=p.id;card.name="M5 "..p.name;card.cost=p.baseThreat;card.m5Profile=p.profileId
            CATALOG[p.id]=card;CATALOG_ORDINAL[p.id]=CATALOG_ORDINAL[p.physicalShipId]
            SHIP_DEFINITIONS[p.id]=SHIP_DEFINITIONS[p.physicalShipId]
        end
        for _,program in ipairs(M5.CATALOG.programs or {}) do
            if original then
                CATALOG[program.id]={id=program.id,name=program.name,type="m5-program",cost=program.threat,
                    cardImage=original.cardBack,cardBack=original.cardBack,m5Program=true}
            end
        end
    end
end
local priorReconcile=STA2E_Reconcile
function STA2E_Reconcile()
    installCatalog()
    return priorReconcile()
end
local originalCardData=cardData
cardData=function(card)
    if card and card.m5Program then return programCardData(M5.PROGRAMS[card.id],M5.SHIP_PROFILES.neghvar) end
    return originalCardData(card)
end

local function validateM5(fleet)
    if type(fleet)~="table" or not array(fleet.ships) then return nil end
    if fleet.source~=nil and type(fleet.source)~="table" then return "Invalid fleet source." end
    local isM5=fleet.source and fleet.source.kind=="remodulated-m5"
    local anyM5=false
    for _,ship in ipairs(fleet.ships) do if type(ship)=="table" and profileById(ship.shipCardId) then anyM5=true end end
    if not isM5 and not anyM5 then return nil end
    if not isM5 or fleet.source.m5Version~=1 then return "Use an M5 version 1 JSON export from staw-remodulated." end
    if type(fleet.fleetId)~="string" or not fleet.fleetId:match('^m5%-[%w%-]+$') or #fleet.fleetId>83 then return "Invalid M5 fleet identity." end
    if #fleet.ships<1 or #fleet.ships>3 then return "Provide 1–3 M5 ships, one per row." end
    if not array(fleet.resources or {}) or #(fleet.resources or {})>0 then return "Normal resources are not supported in M5 fleets." end
    for _,ship in ipairs(fleet.ships) do
        if type(ship)~="table" then return "Invalid M5 ship." end
        local p=profileById(ship.shipCardId)
        if not p or not array(ship.cards) then return "Unknown M5 ship or invalid program list." end
        local programs,seen={},{}
        for _,entry in ipairs(ship.cards) do
            if type(entry)~="table" or not M5.PROGRAMS[entry.cardId] then return "Unknown M5 program." end
            if seen[entry.cardId] or entry.hidden then return "Duplicate or hidden M5 programs are not supported." end
            seen[entry.cardId]=true;table.insert(programs,entry.cardId)
        end
        local profile,err=M5.profile({profileId=p.profileId,programs=programs})
        if not profile then return err end
    end
end
local originalReview=reviewFleet
reviewFleet=function(fleet)
    local err=validateM5(fleet);if err then return nil,err end
    return originalReview(fleet)
end
local originalLayout=fleetLayout
fleetLayout=function(fleet)
    if not (fleet.source and fleet.source.kind=="remodulated-m5") then return originalLayout(fleet) end
    local rows={}
    for index,ship in ipairs(fleet.ships) do
        local entries={{cardId=ship.shipCardId,role="ship"}}
        for _,entry in ipairs(ship.cards) do table.insert(entries,entry) end
        table.insert(rows,{used=#entries,groups={{entries=entries,shipIndex=index,start=1}}})
    end
    return rows
end
function STA2E_M5Attach(s,input)
    local p=profileById(input.shipCardId);if not p then return end
    local programs={};for _,entry in ipairs(input.cards) do table.insert(programs,entry.cardId) end
    local profile=assert(M5.profile({profileId=p.profileId,programs=programs}))
    s.m5={controlled=true,shipId=p.id,profileId=p.profileId,faction=profile.faction,class=profile.class,
        baseCaptainSkill=profile.baseCaptainSkill,finalCaptainSkill=profile.captainSkill,
        baseThreat=profile.baseThreat,threat=profile.threat,slotCapacity=profile.slotCapacity,slotsUsed=profile.slotsUsed,
        programs=programs,actionTree=copy(profile.actionTree)}
    s.ai={enabled=true,intent="engage"};s.side="enemy"
end

function STA2E_M5TrackerButton(s,y)
    local phase=STA2E.game.phase;local label="M5"
    if phase=="planning" then label="PLAN"
    elseif phase=="activation" then label=(s.state.status=="complete" or s.state.status=="action") and "DONE" or "ACT M5"
    elseif phase=="combat" then label=s.state.fired and "FIRED" or "ATTACK" end
    return '<Button id="m5_step_'..xml(s.instanceId)..'" onClick="STA2E_SidebarClick" position="215 '..y..' 0" width="68" height="38" fontSize="12" color="#2B7651" textColor="#FFFFFF">'..label..'</Button>'
end
function STA2E_M5TrackerStep(s,player)
    if not isControlled(s) or not player then return end
    if not STA2E_Playtest.canManage(s,player.color) then tell(player.color,"Only the owner or host can run this M5 ship.");return end
    if next(STA2E.pendingMoves) or next(STA2E.imports) or next(STA2E.pending) then tell(player.color,"Wait for spawning or movement to finish.");return end
    if not complete(s) then tell(player.color,"Deploy / Repair this ship first.");return end
    if s.combat and s.combat.destroyed then tell(player.color,"This ship is destroyed.");return end
    local phase=STA2E.game.phase
    if phase=="planning" then
        local result,err=M5.planShip(s);tell(player.color,result and "M5 maneuver planned." or err)
    elseif phase=="activation" then
        if s.state.status=="complete" or s.state.status=="action" then tell(player.color,"This ship already activated.");return end
        local choice,err=M5.planShip(s);if not choice then tell(player.color,err);return end
        s.state.status="revealed";s.state.revealedOriginal=s.state.maneuver;s.state.aiSkipAction=nil
        M5.Events.emit(M5.TIMING.MANEUVER_REVEALED,{ship=s,maneuver=s.state.maneuver})
        executeMove(s,s.owner)
    elseif phase=="combat" then
        if s.state.fired then tell(player.color,"This ship already attacked.");return end
        local result,err=M5.primaryAttack(s)
        if not result then tell(player.color,err) end
    else tell(player.color,"M5 controls are available during Planning, Activation and Combat.") end
    refresh(s)
end
local priorSidebarClick=STA2E_SidebarClick
function STA2E_SidebarClick(player,value,id)
    local instance=id and (id:match('^m5_step_(.+)$') or id:match('^activate_ai_(.+)$'))
    if instance and isControlled(STA2E.ships[instance]) then return STA2E_M5TrackerStep(STA2E.ships[instance],player) end
    return priorSidebarClick(player,value,id)
end
-- All M5 turn execution lives in the tracker. Normal ship tools remain usable.
local priorCommand=STA2E_Command
function STA2E_Command(params)
    local s=shipFor(params.object)
    if isControlled(s) and ({ai_execute=true,move=true,ai_evaluate=true,ai_toggle=true})[params.command] then
        tell(params.color,"Use this M5 ship's tracker row to plan, activate or attack.");return
    end
    return priorCommand(params)
end
local priorRender=render
render=function(s)
    priorRender(s)
    if isControlled(s) then
        local dial=member(s,"dial")
        if dial and s.state.dialOpen then
            STA2E_SetDialXml(dial,'<Panel width="700" height="200" position="0 0 -120" rotation="0 0 180" scale="0.4 0.4 1" color="#102432F5"><Text text="M5 · Use the ship tracker to plan, activate and attack" width="670" height="180" fontSize="25" color="#FFD86B"/></Panel>')
        end
    end
end

 end)()

