-- RELEASE_PERFORMANCE_20261011: coalesce complete HUD rebuilds per frame.
local immediateHud=hud
function hud()
    if STA2E.loading or STA2E.reconciling or not STA2E.game then return end
    if STA2E.hudScheduled then return end
    STA2E.hudScheduled=true
    local epoch=STA2E.hudEpoch or 0
    Wait.frames(function()
        if epoch~=(STA2E.hudEpoch or 0) then return end
        STA2E.hudScheduled=nil
        if not STA2E.loading and not STA2E.reconciling and STA2E.game then immediateHud() end
    end,1)
end

-- Old boxed helpers render against the selected object's local coordinates.
-- Every helper owns its own contribution, so clearing one doesn't clear another.
local legacy={}
local function dimensions(object)
    local bounds=object.getBoundsNormalized();local size=bounds and bounds.size or {x=2.8,y=0.4,z=2.8}
    local scale=object.getScale();local sx=math.max(0.01,math.abs(scale.x));local sy=math.max(0.01,math.abs(scale.y));local sz=math.max(0.01,math.abs(scale.z))
    local visual=object.getVisualBoundsNormalized and object.getVisualBoundsNormalized() or bounds
    local visualSize=visual and visual.size or size
    local y=STA2E_Playtest.guideY(object)
    return size.x/2,size.z/2,y,1
end
local function append(lines,more)
    for _,line in ipairs(more or {}) do table.insert(lines,line) end
end
local function guideLines(object,mode)
    local hx,hz,y,scale=dimensions(object);local lines={};local ranges={}
    for i=1,3 do ranges[i]=i*RANGE_SEGMENT/scale end
    local color=GUIDE_COLORS.forShip(object)
    if mode:match('^range') or mode=='all' or mode=='ai' then
        local selected=tonumber(mode:match('^range([123])$'))
        for i=1,3 do if not selected or selected==i then table.insert(lines,edgeRoundedRange(hx,hz,ranges[i],y,color[i])) end end
    end
    if mode=='front90' or mode=='all' then append(lines,arcProjection(45,0,ranges,y,color,hx,hz)) end
    if mode=='rear90' or mode=='all' then append(lines,arcProjection(45,180,ranges,y,color,hx,hz)) end
    if mode=='front180' then append(lines,arcProjection(90,0,ranges,y,color,hx,hz,nil,0)) end
    if mode=='ai' then
        -- These are the existing AllianceAI.zone boundaries, not a new chart.
        local extent=ranges[3]
        local function segment(a,b)table.insert(lines,{points={a,b},color=color[3],thickness=ARC_LINE_THICKNESS})end
        segment({-hx,y,-hz},{-hx,y,-hz-extent});segment({hx,y,-hz},{hx,y,-hz-extent})
        segment({-hx,y,-hz},{-hx-extent,y,-hz-extent});segment({hx,y,-hz},{hx+extent,y,-hz-extent})
        segment({-hx-extent,y,hz},{hx+extent,y,hz})
    end
    return MeasurementGeometry.guideToObject(object,lines)
end
local function drawLegacy(guid)
    local entry=legacy[guid];local object=obj(guid)
    if not entry or not object then legacy[guid]=nil;return end
    local lines={};append(lines,entry.original)
    local owners={};for owner in pairs(entry.owners) do table.insert(owners,owner) end;table.sort(owners)
    for _,owner in ipairs(owners) do append(lines,guideLines(object,entry.owners[owner])) end
    object.setVectorLines(lines)
    if #owners==0 then legacy[guid]=nil end
end
function STA2E_LegacyGuide(params)
    if type(params)~='table' or type(params.guid)~='string' then return false end
    local guid,owner,mode=params.guid,tostring(params.owner or 'legacy'),params.mode or 'range123'
    if mode=='clear' then
        if legacy[guid] then legacy[guid].owners[owner]=nil;drawLegacy(guid) end
        return true
    end
    if not ({range1=true,range2=true,range3=true,range123=true,front90=true,rear90=true,front180=true,ai=true,all=true})[mode] then return false end
    local object=obj(guid);if not object then return false end
    legacy[guid]=legacy[guid] or {original=object.getVectorLines and object.getVectorLines() or {},owners={}}
    legacy[guid].owners[owner]=mode;drawLegacy(guid);return true
end

-- Nor station bases have three primary 90-degree sectors, 120 degrees apart.
local standardValidate=MeasurementGeometry.validateArc
function MeasurementGeometry.validateArc(attacker,target,profile)
    if profile~='three-primary-90' then return standardValidate(attacker,target,profile) end
    local result={primary=false,rear=false,secondary=false,profile=profile}
    if not attacker or not target then return result end
    for _,point in ipairs(targetSamples(target)) do
        local x,z=worldToLocal(attacker,point)
        if math.abs(x)+math.abs(z)>0.001 then
            local bearing=math.deg(math.atan2(-x,-z))
            for _,center in ipairs({0,120,240}) do
                if math.abs(((bearing-center+180)%360)-180)<=45.001 then result.primary=true;return result end
            end
        end
    end
    return result
end
local standardDraw=drawShipGuides
drawShipGuides=function(s)
    local class=definition(s.definitionId)
    if not class or class.arc~='three-primary-90' then return standardDraw(s) end
    local base=member(s,'base');if not base then return end
    local hx,hz,y,scale=dimensions(base);local lines={};local state=s.state or {};local colors=GUIDE_COLORS.forShip(s)
    local ranges={};for i=1,3 do ranges[i]=i*RANGE_SEGMENT/scale end
    for i=1,math.min(3,tonumber(state.guideRange) or 0) do table.insert(lines,edgeRoundedRange(hx,hz,ranges[i],y,colors[i])) end
    if state.guideArc then
        for _,angle in ipairs({0,120,240}) do
            local sector=arcProjection(45,0,ranges,y,colors,hx,hz,0,0)
            for _,line in ipairs(sector) do for _,point in ipairs(line.points) do point[1],point[3]=rotatePoint(point[1],point[3],angle) end end
            append(lines,sector)
        end
    end
    base.setVectorLines(MeasurementGeometry.guideToObject(base,lines))
end
-- Refresh the baseline after every modern guide or Echo preview redraw before
-- restoring helper contributions. Clearing a helper restores current guides.
local function mergeModern(s)
    local base=member(s,'base');local guid=base and base.getGUID()
    if guid and legacy[guid] then
        legacy[guid].original=base.getVectorLines() or {};drawLegacy(guid)
    end
end
local modernDraw=drawShipGuides
drawShipGuides=function(s) modernDraw(s);mergeModern(s) end
local modernEcho=drawEchoCandidates
drawEchoCandidates=function(s,candidates) modernEcho(s,candidates);mergeModern(s) end
STA2E_DrawShipGuides=drawShipGuides

local load=onLoad
function onLoad(saved)
    STA2E.hudEpoch=(STA2E.hudEpoch or 0)+1;STA2E.hudScheduled=nil;legacy={}
    return load(saved)
end
local destroyed=onObjectDestroy
function onObjectDestroy(object)
    local guid=object and object.getGUID()
    if guid then
        legacy[guid]=nil
        local affected={};for target,entry in pairs(legacy) do if entry.owners[guid] then entry.owners[guid]=nil;table.insert(affected,target) end end
        for _,target in ipairs(affected) do drawLegacy(target) end
    end
    return destroyed(object)
end
end)()

