":false,"HideWhenFaceDown":false,"Hands":false,"CustomMesh":{"MeshURL":"https://steamusercontent-a.akamaihd.net/ugc/2027231506468368882/1599A97B3F6CC43EC509124C2CDF3B48577308CB/","DiffuseURL":"https://steamusercontent-a.akamaihd.net/ugc/2027231506468377017/177B76170DC20ACBD8F8CB55F18A8225099BAC1D/","NormalURL":"","ColliderURL":"https://steamusercontent-a.akamaihd.net/ugc/270596815979410422/6DBFC15BF81343705BE1FA4A440D36A9BEF2C3C8/","Convex":false,"MaterialIndex":1,"TypeIndex":1,"CustomShader":{"SpecularColor":{"r":0.8745098,"g":0.8117647,"b":0.745098054},"SpecularIntensity":0.0,"SpecularSharpness":3.0,"FresnelStrength":0.1},"CastShadows":true},"LuaScript":"---------------------------\n--  Attack Wing AI V2.0  --\n--   Freighter Script    --\n--   Antares Shipyard    --\n---------------------------\n\n-- Variables --\nBSTokenGUID = '655fff'\nBSToken = getObjectFromGUID(BSTokenGUID)\n\nfunction onLoad()\n  self.addContextMenuItem(' - MOVEMENT - ', function(arguement) self.call('click_dummy') end, true)\n  self.addContextMenuItem('[b]2\\u{2191}[/b]', function(arguement) self.call('click_S2') end, true)\n  self.addContextMenuItem('[b]3\\u{2191}[/b]', function(arguement) self.call('click_S3') end, true)\n  self.addContextMenuItem('[b]2\\u{2196}[/b]', function(arguement) self.call('click_BL2') end, true)\n  self.addContextMenuItem('[b]2\\u{2197}[/b]', function(arguement) self.call('click_BR2') end, true)\n  self.addContextMenuItem('[b]UNDO[/b]', function(arguement) self.call('click_Undo') end, true)\nend\n\n\nfunction click_dummy()\n  print(\"\")\nend\n\nlocal undoHistory = {}\nlocal function rememberPose(object)\n    local p, r = object.getPosition(), object.getRotation()\n    undoHistory[#undoHistory+1] = {position={p.x,p.y,p.z}, rotation={r.x,r.y,r.z}}\n    if #undoHistory > 32 then table.remove(undoHistory,1) end\nend\nlocal function restorePose(object)\n    local pose = table.remove(undoHistory)\n    if not pose then print(\"No movement to undo.\"); return false end\n    object.setPosition(pose.position)\n    object.setRotation(pose.rotation)\n    return true\nend\n\nfunction click_Undo()\n    restorePose(self)\nend\nfunction UpdateUndo()\n    rememberPose(self)\nend\n\nfunction click_S2()\n\n\tlocal pos = self.getPosition()\n\tlocal angle = self.getRotation()\n\tlocal distance = 4.6\n\n\t--Set up UndoSetupSetup\n\tself.call('UpdateUndo')\n\n\tposX= math.sin(math.rad(angle.y))*distance\n\n\tposZ= math.cos(math.rad(angle.y))*distance\n\n\tself.setPosition({pos.x-posX,pos.y+0.5,pos.z-posZ})\n\n  local pos = self.getPosition()\n  local angle = self.getRotation()\n  local forward = 0\n  local side = 0\n\n  local forX= math.sin(math.rad(angle.y))*forward\n  local forZ= math.cos(math.rad(angle.y))*forward\n  local sideX= math.sin(math.rad(angle.y+90))*side\n  local sideZ= math.cos(math.rad(angle.y+90))*side\n\n  local BST =  BSToken.takeObject ({\n      position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n    })\n\nend\n\nfunction click_S3()\n\n\tlocal pos = self.getPosition()\n\tlocal angle = self.getRotation()\n\tlocal distance = 6.3\n\n\t--Set up UndoSetupSetup\n\tself.call('UpdateUndo')\n\n\tposX= math.sin(math.rad(angle.y))*distance\n\n\tposZ= math.cos(math.rad(angle.y))*distance\n\n\tself.setPosition({pos.x-posX,pos.y+0.5,pos.z-posZ})\n\n  local pos = self.getPosition()\n  local angle = self.getRotation()\n  local forward = 0\n  local side = 0\n\n  local forX= math.sin(math.rad(angle.y))*forward\n  local forZ= math.cos(math.rad(angle.y))*forward\n  local sideX= math.sin(math.rad(angle.y+90))*side\n  local sideZ= math.cos(math.rad(angle.y+90))*side\n\n  local BST =  BSToken.takeObject ({\n      position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n    })\n\nend\n\nfunction click_BL2()\n\n\tlocal pos = self.getPosition()\n\tlocal angle = self.getRotation()\n\tlocal forward = 5.28\n\tlocal side = 2.08\n\t--Set up UndoSetupSetup\n\tself.call('UpdateUndo')\n\n\tlocal forX= math.sin(math.rad(angle.y))*forward\n\tlocal forZ= math.cos(math.rad(angle.y))*forward\n\tlocal sideX= math.sin(math.rad(angle.y+90))*side\n\tlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\tself.setPosition({pos.x-forX,pos.y+0.5,pos.z-forZ})\n\tlocal pos = self.getPosition()\n\tself.setPosition({pos.x+sideX,pos.y+0.5,pos.z+sideZ})\n\tself.setRotation({angle.x, angle.y-45, angle.z})\n\n  local pos = self.getPosition()\n  local angle = self.getRotation()\n  local forward = 0\n  local side = 0\n\n  local forX= math.sin(math.rad(angle.y))*forward\n  local forZ= math.cos(math.rad(angle.y))*forward\n  local sideX= math.sin(math.rad(angle.y+90))*side\n  local sideZ= math.cos(math.rad(angle.y+90))*side\n\n  local BST =  BSToken.takeObject ({\n      position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n    })\nend\n\nfunction click_BR2()\n\n\tlocal pos = self.getPosition()\n\tlocal angle = self.getRotation()\n\t--Set up UndoSetupSetup\n\tself.call('UpdateUndo')\n\n\tlocal forward = 5.28\n\tlocal side = 2.08\n\tlocal forX= math.sin(math.rad(angle.y))*forward\n\tlocal forZ= math.cos(math.rad(angle.y))*forward\n\tlocal sideX= math.sin(math.rad(angle.y+90))*side\n\tlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\tself.setPosition({pos.x-forX,pos.y+0.5,pos.z-forZ})\n\tlocal pos = self.getPosition()\n\tself.setPosition({pos.x-sideX,pos.y+0.5,pos.z-sideZ})\n\tself.setRotation({angle.x, angle.y+45, angle.z})\n\n  local pos = self.getPosition()\n  local angle = self.getRotation()\n  local forward = 0\n  local side = 0\n\n  local forX= math.sin(math.rad(angle.y))*forward\n  local forZ= math.cos(math.rad(angle.y))*forward\n  local sideX= math.sin(math.rad(angle.y+90))*side\n  local sideZ= math.cos(math.rad(angle.y+90))*side\n\n  local BST =  BSToken.takeObject ({\n      position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n    })\nend","LuaScriptState":"","XmlUI":""},"attackShip":{"Name":"Custom_Model","Transform":{"posX":6.9989996,"posY":3.78183246,"posZ":11.1569614,"rotX":0.0105146766,"rotY":0.00211401423,"rotZ":-0.00130127766,"scaleX":1.02499962,"scaleY":1.02499962,"scaleZ":1.02499962},"Nickname":"Jem'Hadar Attack Ship","Description":"","GMNotes":"","AltLookAngle":{"x":0.0,"y":0.0,"z":0.0},"ColorDiffuse":{"r":0.9999998,"g":0.992160261,"b":0.9999998},"LayoutGroupSortIndex":0,"Value":0,"Locked":false,"Grid":true,"Snap":true,"IgnoreFoW":false,"MeasureMovement":false,"DragSelectable":true,"Autoraise":true,"Sticky":true,"Tooltip":true,"GridProjection":false,"HideWhenFaceDown":false,"Hands":false,"CustomMesh":{"MeshURL":"https://steamusercontent-a.akamaihd.net/ugc/5983665599856169072/7696772C7D10ACB8236B327B2AB5CE4588F2AA73/","DiffuseURL":"https://steamusercontent-a.akamaihd.net/ugc/2071150099989246327/82E7F5583ED1E03926B281B3DB95BB1E7D2481E7/","NormalURL":"","ColliderURL":"https://steamusercontent-a.akamaihd.net/ugc/270596815979410422/6DBFC15BF81343705BE1FA4A440D36A9BEF2C3C8/","Convex":false,"MaterialIndex":1,"TypeIndex":1,"CustomShader":{"SpecularColor":{"r":0.8745098,"g":0.8117647,"b":0.745098054},"SpecularIntensity":0.0,"SpecularSharpness":3.0,"FresnelStrength":0.1},"CastShadows":true},"LuaScript":"-- Spawn Movement Template\n-- Action Tokens --\nfunction onLoad()\n  self.addContextMenuItem('[b] - RANGES - [/b]', function() end, true)\n  self.addContextMenuItem('Range 1', function(arguement) self.call('click_Range1') end, false)\n  self.addContextMenuItem('Range 2', function(arguement) self.call('click_Range2') end, false)\n  self.addContextMenuItem('Range 3', function(arguement) self.call('click_Range3') end, false)\n  self.addContextMenuItem('Clear measurement', function() click_ClearRange() end, false)\n  self.addContextMenuItem('All Ranges', function(arguement) self.call('click_Range123') end, false)\n  self.addContextMenuItem('[b] - AI ARC - [/b]', function() end, true)\n  self.addContextMenuItem('AI ARC', function(arguement) self.call('click_AIArc') end, false)\n  self.addContextMenuItem('[b] - TOKENS - [/b]', function() end, true)\n    self.addContextMenuItem('Evade', function(arguement) self.call('click_Evade') end, false)\n    self.addContextMenuItem('Target Lock', function(arguement) self.call('click_TargetLock') end, false)\n    self.addContextMenuItem(\"Scan\", function(argument) self.call('click_Scan') end, false)\n    self.addContextMenuItem(\"Battlestations\", function(argument) self.call('click_Battlestations') end, false)\n    self.addContextMenuItem('AUX Power', function(arguement) self.call('click_AUXPower') end, false)\n\n    --Variables --\n    EvadeTokenGUID = 'f087d1'\n    TargetLockTokenGUID = '1649f4'\n    ScanTokenGUID = 'b36f7f'\n    BattlestationsTokenGUID = '655fff'\n    CloakTokenGUID = '8d45a9'\n    RegenTokenGUID ='0afb47'\n    AUXPowerTokenGUID = 'a50797'\n    isShip = false\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n-- Token Clones --\nEvadeToken = getObjectFromGUID(EvadeTokenGUID)\nTargetLockToken = getObjectFromGUID(TargetLockTokenGUID)\nScanToken = getObjectFromGUID(ScanTokenGUID)\nBattlestationsToken = getObjectFromGUID(BattlestationsTokenGUID)\nCloakToken = getObjectFromGUID(CloakTokenGUID)\nRegenToken = getObjectFromGUID(RegenTokenGUID)\nAUXPowerToken = getObjectFromGUID(AUXPowerTokenGUID)\n\n-- Collision event\nfunction onCollisionEnter(collision_info)\n  target = collision_info.collision_object\n  if target.getVar(\"isShip\") !=nil then\n    if target.getVar(\"isShip\") == true and isShip == true then\n        broadcastToAll(\"Collision with \" .. self.getName() .. \" !\")\n    end\n  end\nend\n\nfunction click_Collide()\n  if isShip != true then\n    isShip = true\n    broadcastToAll(self.getName() .. \" collision detection enabled.\")\n  else\n    isShip = false\n    broadcastToAll(self.getName() .. \" collision silenced\")\n  end\nend\n\n-- Evade Token --\nfunction click_Evade()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = 0.8\nlocal side = 1.2\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nEvadeToken.takeObject ({\n  position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\nend\n\n-- Target Lock Token --\nfunction click_TargetLock(obj, playerColor)\nlocal shipName = self.getName()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = 1.1\nlocal side = 0\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nlocal newLock = TargetLockToken.takeObject ({\n  position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\nprint(shipName)\nnewLock.setName(shipName)\nend\n\n-- Scan Token --\nfunction click_Scan()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = 0\nlocal side = 1.2\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nScanToken.takeObject ({\nposition = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\nend\n\n-- Battlestations Token --\nfunction click_Battlestations ()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = -0.9\nlocal side = 1.2\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nBattlestationsToken.takeObject ({\n  position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\n\nend\n\n-- Cloak Token --\nfunction click_Cloak ()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = 0.8\nlocal side = -1.2\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nCloakToken.takeObject ({\n  position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\n\nend\n\n-- AUX Power Token --\nfunction click_AUXPower ()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = -0.8\nlocal side = -1.2\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nAUXPowerToken.takeObject ({\n  position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\n\nend\n\n-- Regenerate Token --\nfunction click_Regen ()\nlocal pos = self.getPosition()\nlocal angle = self.getRotation()\nlocal forward = -0.8\nlocal side = -1.2\n\nlocal forX= math.sin(math.rad(angle.y))*forward\nlocal forZ= math.cos(math.rad(angle.y))*forward\nlocal sideX= math.sin(math.rad(angle.y+90))*side\nlocal sideZ= math.cos(math.rad(angle.y+90))*side\n\nRegenToken.takeObject ({\n  position = {pos.x-forX-sideX, pos.y+1, pos.z-sideZ-forZ}\n})\n\nend\n\n------------------------\n-- Range Finder Start --\n------------------------\n-- Shared vector guides replace the missing legacy mesh objects.\nlocal function legacyGuide(mode)\n    local ship = self\n    if mode ~= \"clear\" and (not ship or not ship.getGUID) then\n        print(\"Sync a ship before measuring.\"); return false\n    end\n    local ok, result = pcall(function()\n        return Global.call(\"STA2E_LegacyGuide\", {guid=ship and ship.getGUID and ship.getGUID() or nil,\n            owner=self.getGUID(), mode=mode})\n    end)\n    if not ok or result ~= true then print(\"Measurement unavailable; check the linked ship.\"); return false end\n    return true\nend\nfunction click_FindRange() return legacyGuide(\"all\") end\nfunction click_Range1() return legacyGuide(\"range1\") end\nfunction click_Range2() return legacyGuide(\"range2\") end\nfunction click_Range3() return legacyGuide(\"range3\") end\nfunction click_Range123() return legacyGuide(\"range123\") end\nfunction click_180Arc() return legacyGuide(\"front180\") end\nfunction click_90FArc() return legacyGuide(\"front90\") end\nfunction click_90RArc() return legacyGuide(\"rear90\") end\nfunction click_AIArc() return legacyGuide(\"ai\") end\nfunction click_ClearRange() return legacyGuide(\"clear\") end\n\n------------------------\n--  Range Finder End  --\n------------------------\n\nend","LuaScriptState":"","XmlUI":""},"pulsar":{"Name":"Custom_Token","Transform":{"posX":83.09523,"posY":2.02113485,"posZ":9.536553,"rotX":1.28674833e-06,"rotY":180.0459,"rotZ":8.77417051e-07,"scaleX":0.54,"scaleY":1.0,"scaleZ":0.54},"Nickname":"Pulsar","Description":"","GMNotes":"","AltLookAngle":{"x":0.0,"y":0.0,"z":0.0},"ColorDiffuse":{"r":1.0,"g":1.0,"b":1.0},"LayoutGroupSortIndex":0,"Value":0,"Locked":false,"Grid":true,"Snap":true,"IgnoreFoW":false,"MeasureMovement":false,"DragSelectable":true,"Autoraise":true,"Sticky":true,"Tooltip":true,"GridProjection":false,"HideWhenFaceDown":false,"Hands":false,"CustomImage":{"ImageURL":"https://steamusercontent-a.akamaihd.net/ugc/2027231506441644591/5340E26A90F2DB719CE4C13D2C5D1BC995598DCF/","ImageSecondaryURL":"","ImageScalar":1.0,"WidthScale":0.0,"CustomToken":{"Thickness":0.1,"MergeDistancePixels":15.0,"StandUp":false,"Stackable":false}},"LuaScript":"","LuaScriptState":"","XmlUI":""},"shipyard":{"Name":"Custom_Token","Transform":{"posX":22.1058273,"posY":1.02121592,"posZ":31.6208878,"rotX":-6.09123026e-06,"rotY":180.0014,"rotZ":-1.51184968e-05,"scaleX":0.54,"scaleY":1.0,"scaleZ":0.54},"Nickname":"Dominion Shipyard","Description":"","GMNotes":"","AltLookAngle":{"x":0.0,"y":0.0,"z":0.0},"ColorDiffuse":{"r":1.0,"g":1.0,"b":1.0},"LayoutGroupSortIndex":0,"Value":0,"Locked":false,"Grid":true,"Snap":true,"IgnoreFoW":false,"MeasureMovement":false,"DragSelectable":true,"Autoraise":true,"Sticky":true,"Tooltip":true,"GridProjection":false,"HideWhenFaceDown":false,"Hands":false,"CustomImage":{"ImageURL":"https://steamusercontent-a.akamai