    local assets=JSON.decode(ASSET_JSON)
    local RANGE=tonumber(RANGE_SEGMENT) or 3.94
    local ASTEROID_RADIUS=1.155
    local BLUE={0.10,0.78,1.0}
    local PURPLE={0.65,0.40,0.90}
    local WHITE={0.78,0.83,0.92}

    local layouts={
        patrol={asteroidCount=6,zone={uMin=-5/9,uMax=5/9,vMin=-5/9,vMax=5/9},edgeClearance=2,
            sensors={{u=-5/9,v=5/9,parity="odd"},{u=5/9,v=5/9,parity="even"}}},
        evacuation={asteroidCount=6,zone={uMin=-5/9,uMax=5/9,vMin=-5/9,vMax=5/9},edgeClearance=2,
            planet={u=0,v=0}},
        search={asteroidCount=6,zone={uMin=-7/9,uMax=7/9,vMin=-5/9,vMax=7/9},
            search={{u=-5/9,v=5/9},{u=3/9,v=5/9},{u=-3/9,v=1/9},
                {u=3/9,v=-3/9},{u=1/9,v=1/9},{u=-1/9,v=5/9},
                {u=5/9,v=1/9},{u=-5/9,v=-3/9},{u=-1/9,v=-3/9}}},
        escort={asteroidCount=4,zone={uMin=-7/9,uMax=7/9,vMin=-5/9,vMax=5/9},
            planet={u=0,v=0},runabouts={{u=0,v=8/9,minPlayers=2},
                {u=4/9,v=8/9,minPlayers=3},{u=-4/9,v=8/9,minPlayers=5}}},
        listening={asteroidCount=4,zone={uMin=-7/9,uMax=7/9,vMin=-7/9,vMax=7/9},
            polygon={{-7/9,7/9},{7/9,7/9},{7/9,-7/9},{3/9,-7/9},{-7/9,3/9}},
            posts={{u=-5/9,v=-1/9},{u=-1/9,v=-5/9}}},
        finale={asteroidCount=0,planet={u=0,v=4/9},
            platforms={{u=-3/9,v=3/9},{u=3/9,v=3/9},{u=-5/9,v=1/9},{u=5/9,v=1/9}}},
    }

    -- A bearing identifies a marked deployment position, not a board edge.
    -- These are transcribed separately because the book changes its vectors.
    local bearingLayouts={
        standard={{-1,-3/9,"left",270},{-1,3/9,"left",270},
            {-3/9,1,"top",0},{3/9,1,"top",0},{1,3/9,"right",90},{1,-3/9,"right",90}},
        escort={{-1,-6/9,"left",270},{-1,0,"left",270},{-1,6/9,"left",270},
            {1,6/9,"right",90},{1,0,"right",90},{1,-6/9,"right",90}},
        listening={{-7/9,1,"top",0},{-1/9,1,"top",0},{5/9,1,"top",0},
            {1,5/9,"right",90},{1,-1/9,"right",90},{1,-7/9,"right",90}},
        finale={{-1,-2/9,"left",270},{-4/9,1,"top",0},{4/9,1,"top",0},
            {1,-2/9,"right",90},{4/9,-1,"bottom",180},{-4/9,-1,"bottom",180}},
    }

    local function clone(value)
        if type(value)~="table" then return value end
        local result={};for key,item in pairs(value) do result[key]=clone(item) end;return result
    end

    local function planKey(value)
        local number=tonumber(value)
        return number and tostring(math.floor(number)) or tostring(value)
    end

    local function kindOf(definition)
        local kind=definition and definition.geometry and definition.geometry.kind
        if kind then return kind end
        local ids={A1M1="patrol",A2M1="evacuation",A2M2="search",A2M3="escort",A2M4="listening",A3M1="finale"}
        return ids[definition and definition.id] or "patrol"
    end

    local function boardFrame()
        local board=getObjectFromGUID("ae9c49")
        local position=board and board.getPosition() or {x=0,y=0.53,z=0}
        local rotation=board and board.getRotation() or {y=90}
        local scale=board and board.getScale() or {x=1.89,z=1.89}
        return {x=position.x or position[1],y=(position.y or position[2])+0.50,z=position.z or position[3],
            yaw=(rotation.y or rotation[2] or 90)-90,
            halfX=18.1*(scale.x or scale[1] or 1.89)/1.89,
            halfZ=18.1*(scale.z or scale[3] or 1.89)/1.89}
    end

    local function point(frame,u,v,height)
        local angle=math.rad(frame.yaw)
        local x,z=u*frame.halfX,v*frame.halfZ
        return {x=frame.x+x*math.cos(angle)+z*math.sin(angle),
            y=frame.y+(height or 0),z=frame.z-x*math.sin(angle)+z*math.cos(angle)}
    end

    local function makeAnchors(definition,frame)
        local kind=kindOf(definition)
        local source=bearingLayouts[kind] or bearingLayouts.standard
        local result={}
        for index,item in ipairs(source) do
            local u,v=item[1],item[2]
            -- Ship centers are inset from the edge by a base half-width.
            if item[3]=="left" then u=u+1.55/frame.halfX
            elseif item[3]=="right" then u=u-1.55/frame.halfX
            elseif item[3]=="top" then v=v-1.55/frame.halfZ
            else v=v+1.55/frame.halfZ end
            result[index]={position=point(frame,u,v,0.3),rotation=(item[4]+frame.yaw)%360,
                edge=item[3],bearing=index,u=item[1],v=item[2]}
        end
        return result
    end

    function M.anchors(subject)
        subject=subject or {}
        if subject.missionObjects and subject.missionObjects.anchors then return clone(subject.missionObjects.anchors) end
        return makeAnchors(subject.definition or subject,boardFrame())
    end

    local function currentRun(state,registry)
        if registry.cancelled or state.missionObjects~=registry then return false end
        if type(allianceState)=="function" then
            local current=allianceState()
            return current==state and current.runId==registry.runId and current.active~=false
        end
        return state.active~=false and state.runId==registry.runId
    end

    local function ownership(registry,kind,metadata)
        return "STA2E_MISSION_OBJECT|"..tostring(registry.runId).."|"..tostring(registry.missionId).."|"..kind.."|"..JSON.encode(metadata or {})
    end

    local function primitive(name,shape)
        return {Name=shape or "BlockSquare",Nickname=name,Description="Alliance mission piece",
            Transform={posX=0,posY=1,posZ=0,rotX=0,rotY=0,rotZ=0,scaleX=1,scaleY=0.1,scaleZ=1},
            ColorDiffuse={r=0.23,g=0.35,b=0.48},Locked=false,Grid=false,Snap=false,LuaScript="",XmlUI=""}
    end

    local function asset(key,name)
        local data=assets[key] and clone(assets[key]) or primitive(name,"BlockCylinder")
        data.GUID=nil;data.Nickname=name;data.LuaScript="";data.LuaScriptState="";data.XmlUI=""
        data.Locked=false;data.Grid=false;data.Snap=false;data.States=nil
        return data
    end

    local function addPlan(plans,data,position,rotation,metadata)
        plans[#plans+1]={data=data,position=position,rotation=rotation or {0,0,0},metadata=metadata or {}}
    end

    local function label(data,text)
        -- Existing token art provides its own label; fallback primitives remain
        -- usable through both their name and an on-object text label.
        if data.Name=="BlockCylinder" or data.Name=="BlockSquare" then data.Nickname=text end
        return data
    end

    local function cardToken(number,name)
        local numbered=assets["token"..number] or assets.token1
        local front=numbered and numbered.CustomImage and numbered.CustomImage.ImageURL
        local back=assets.tokenBack and assets.tokenBack.CustomImage.ImageURL
        if not front or not back then return primitive(name,"Chip") end
        local deck=8200+number
        -- Cards have distinct faces and backs. A custom token's mirrored back
        -- can expose the number, so search uses the same existing art on cards.
        return {Name="CardCustom",Nickname=name,Description="Flip only when this search location is examined.",
            Transform={posX=0,posY=1,posZ=0,rotX=0,rotY=180,rotZ=180,scaleX=0.35,scaleY=0.35,scaleZ=0.35},
            ColorDiffuse={r=1,g=1,b=1},Locked=false,Grid=false,Snap=false,CardID=deck*100,
            CustomDeck={[tostring(deck)]={FaceURL=front,BackURL=back,NumWidth=1,NumHeight=1,
                BackIsHidden=true,UniqueBack=false,Type=0}},LuaScript="",LuaScriptState="",XmlUI=""}
    end

    local function shuffle(values)
        for i=#values,2,-1 do local j=math.random(i);values[i],values[j]=values[j],values[i] end
        return values
    end

    local function inPolygon(u,v,polygon)
        if not polygon then return true end
        local inside=false
        local j=#polygon
        for i=1,#polygon do
            local a,b=polygon[i],polygon[j]
            if (a[2]>v)~=(b[2]>v) and u<(b[1]-a[1])*(v-a[2])/(b[2]-a[2])+a[1] then inside=not inside end
            j=i
        end
        return inside
    end

    local function obstacles(plans,registry,layout,blocked)
        if not layout.zone or layout.asteroidCount==0 then return end
        local frame=registry.frame
        local zone=layout.zone
        local minU,maxU,minV,maxV=zone.uMin,zone.uMax,zone.vMin,zone.vMax
        if layout.edgeClearance then
            local gap=layout.edgeClearance*RANGE+ASTEROID_RADIUS
            minU=math.max(minU,-1+gap/frame.halfX);maxU=math.min(maxU,1-gap/frame.halfX)
            minV=math.max(minV,-1+gap/frame.halfZ);maxV=math.min(maxV,1-gap/frame.halfZ)
        end
        local best={}
        -- Try independent layouts, retaining the largest legal candidate set.
        -- A constrained random layout never relaxes the spacing silently.
        for restart=1,40 do
            local placed={}
            for attempt=1,1000 do
                local u=minU+math.random()*(maxU-minU)
                local v=minV+math.random()*(maxV-minV)
                if inPolygon(u,v,layout.polygon) then
                    local p=point(frame,u,v)
                    local legal=true
                    for _,other in ipairs(blocked) do
                        local dx,dz=p.x-other.position.x,p.z-other.position.z
                        local required=RANGE*(layout.separationRanges or 1)+ASTEROID_RADIUS+other.radius
                        if dx*dx+dz*dz<required*required then legal=false;break end
                    end
                    if legal then
                        for _,other in ipairs(placed) do
                            local dx,dz=p.x-other.position.x,p.z-other.position.z
                            local required=RANGE*(layout.separationRanges or 1)+2*ASTEROID_RADIUS
                            if dx*dx+dz*dz<required*required then legal=false;break end
                        end
                    end
                    if legal then placed[#placed+1]={position=p,u=u,v=v} end
                    if #placed>=layout.asteroidCount then break end
                end
            end
            if #placed>#best then best=placed end
            if #best>=layout.asteroidCount then break end
        end
        registry.asteroidCount=#best
        if #best<layout.asteroidCount then
            registry.layoutWarnings[#registry.layoutWarnings+1]="Only "..#best.." of "..layout.asteroidCount..
                " asteroids fit the rolled layout. Add the remainder manually using the physical Range ruler."
        end
        for index,item in ipairs(best) do
            local pulsar=layout.pulsarCount and index>layout.asteroidCount-layout.pulsarCount
            local data=asset(pulsar and "pulsar" or "asteroid",(pulsar and "Pulsar Obstacle " or "Alliance Asteroid ")..index)
            data.Description=pulsar and "Pulsar: asteroid overlap rules. Within Range 1, attacks are limited to Range 1 in both directions. Spend Scan when choosing an attack to ignore effects until round end. In Behind the Lines, roll each pulsar at start Combat: critical deals a face-up card to every ship within Range 1, ignoring shields. Resolve manually." or "Mission obstacle. Maintain at least Range 1 from other obstacles and mission tokens."
            data.Locked=true
            addPlan(plans,data,item.position,{0,math.random(0,359),0},{kind=pulsar and "pulsar" or "asteroid",index=index})
        end
    end

    local function hullPiece(plans,registry,kind,index,site)
        local isPost=kind=="listeningPost"
        local title=(isPost and "Listening Post " or "Weapon Platform ")..index
        local rules=isPost and "Attack - | Agility 0 | Hull 8 | Shields 0. Critical hits become two hits. Overlap rules apply."
            or "Attack 3 | Agility 0 | Hull 8 | Shields 0. Critical hits become two hits. At end of Combat attack the nearest Federation ship within Range 3 (360-degree arc); convert battle stations to hits."
        local data=label(asset(isPost and "listeningPost" or "weaponPlatform",title),title)
        data.Description=rules;data.Locked=true
        data.LuaScript=STA2E_MISSION_HULL_SCRIPT or ""
        data.LuaScriptState=JSON.encode({hull=8,maxHull=8,kind=kind,missionId=registry.missionId,
            runId=registry.runId,label=title,index=index,rules=rules})
        registry.plannedHullCount=registry.plannedHullCount+1
        addPlan(plans,data,point(registry.frame,site.u,site.v),{0,180+registry.frame.yaw,0},
            {kind=kind,index=index,hull=8,maxHull=8,label=title})
    end

    local function line(guide,frame,sites,color,width)
        local points={}
        for _,site in ipairs(sites) do
            local p=point(frame,site[1],site[2],STA2E_Playtest.guidePlane()-frame.y)
            local localPoint=guide.positionToLocal(p)
            points[#points+1]={localPoint.x or localPoint[1],localPoint.y or localPoint[2],localPoint.z or localPoint[3]}
        end
        return {points=points,color=color,thickness=width or 0.06}
    end

    local function drawGuide(guide,registry)
        if not guide or not guide.setVectorLines then return end
        local frame,kind=registry.frame,registry.kind
        if registry.book2 then
            local g=registry.geometry;local lines={};local fed={}
            for _,edge in ipairs(g.allianceEdges) do fed[edge]=true end
            local sides={left={{-1,-1},{-1,1}},right={{1,-1},{1,1}},top={{-1,1},{1,1}},bottom={{-1,-1},{1,-1}}}
            for edge,sites in pairs(sides) do lines[#lines+1]=line(guide,frame,sites,fed[edge] and BLUE or PURPLE,0.12) end
            for _,area in ipairs(g.playerAreas) do
                if area.kind=="polygon" then local points=clone(area.points);points[#points+1]=clone(points[1]);lines[#lines+1]=line(guide,frame,points,BLUE)
                elseif area.kind=="strip" then lines[#lines+1]=line(guide,frame,{{-1,area.v},{1,area.v}},BLUE)
                else
                    local arc={{area.u,area.v-area.v*4/9}}
                    for step=0,18 do local angle=math.pi/2*step/18
                        arc[#arc+1]={area.u-area.u*math.sin(angle)*4/9,area.v-area.v*math.cos(angle)*4/9}
                    end
                    lines[#lines+1]=line(guide,frame,arc,BLUE)
                end
            end
            for _,z in ipairs({g.obstacleZone or {},g.mineZone or {}}) do
                if z.uMin then lines[#lines+1]=line(guide,frame,{{z.uMin,z.vMin},{z.uMax,z.vMin},{z.uMax,z.vMax},{z.uMin,z.vMax},{z.uMin,z.vMin}},WHITE,0.035) end
            end
            guide.clearButtons()
            for index,a in ipairs(registry.anchors) do
                local u,v=a.u,a.v
                if a.edge=="left" then u=u-0.09 elseif a.edge=="right" then u=u+0.09 elseif a.edge=="top" then v=v+0.09 else v=v-0.09 end
                guide.createButton({function_owner=Global,click_function="STA2E_MissionGuideNoop",label=tostring(index),
                    position=guide.positionToLocal(point(frame,u,v,STA2E_Playtest.guidePlane()-frame.y+0.015)),rotation={0,0,0},width=0,height=0,font_size=260,font_color=PURPLE})
            end
            if g.obstaclePolygon then local points=clone(g.obstaclePolygon);points[#points+1]=clone(points[1]);lines[#lines+1]=line(guide,frame,points,WHITE,0.035) end
            if g.warpPoint then
                local w=g.warpPoint;local arc={};for i=0,24 do local a=math.pi/2*i/24;arc[#arc+1]={w.u+math.sin(a)*8/9,w.v-math.cos(a)*8/9} end
                lines[#lines+1]=line(guide,frame,arc,{1,0.75,0.1},0.05)
            end
            guide.setVectorLines(lines);guide.setDescription(registry.book3 and "Blue: Alliance edges/deployment. Purple: Dominion edges. White: obstacle region. Gold: Range 2 of Warp Point W. Follow this mission rules card for escape and objectives; special combat/actions remain manual." or "Blue: Alliance edges/deployment. Purple: Dominion edges. White: obstacle and minefield zones. Favor the Bold requires clearing all Cardassians before retreat and a TOP-edge escape to win. Special objective rules are manual.")
            return
        end
        local lines={}
        local fed={bottom=kind~="finale",left=kind=="listening"}
        if registry.escapeEdge then fed[registry.escapeEdge]=true end
        local sides={left={{-1,-1},{-1,1}},right={{1,-1},{1,1}},top={{-1,1},{1,1}},bottom={{-1,-1},{1,-1}}}
        for edge,sites in pairs(sides) do lines[#lines+1]=line(guide,frame,sites,fed[edge] and BLUE or PURPLE,0.12) end
        if kind=="listening" then
            local arc={{-1,-1},{-1,-1+2/3}}
            for step=1,18 do
                local angle=math.pi/2*(1-step/18)
                arc[#arc+1]={-1+math.cos(angle)*2/3,-1+math.sin(angle)*2/3}
            end
            arc[#arc+1]={-1,-1};lines[#lines+1]=line(guide,frame,arc,BLUE)
        elseif kind=="finale" then
            lines[#lines+1]=line(guide,frame,{{-1/3,-5/9},{1/3,-5/9},{1/3,-3/9},{-1/3,-3/9},{-1/3,-5/9}},BLUE)
            lines[#lines+1]=line(guide,frame,{{0,-4/9},{0,-2/9}},BLUE)
        else
            lines[#lines+1]=line(guide,frame,{{-1,-7/9},{1,-7/9}},BLUE)
        end
        local layout=layouts[kind]
        if layout.polygon then
            local closed=clone(layout.polygon);closed[#closed+1]=clone(closed[1]);lines[#lines+1]=line(guide,frame,closed,WHITE,0.035)
        elseif layout.zone then
            local z=layout.zone
            lines[#lines+1]=line(guide,frame,{{z.uMin,z.vMin},{z.uMax,z.vMin},{z.uMax,z.vMax},{z.uMin,z.vMax},{z.uMin,z.vMin}},WHITE,0.035)
        end
        if guide.clearButtons then guide.clearButtons() end
        for index,anchor in ipairs(registry.anchors) do
            local u,v=anchor.u,anchor.v
            if anchor.edge=="left" then u=u-0.09 elseif anchor.edge=="right" then u=u+0.09
            elseif anchor.edge=="top" then v=v+0.09 else v=v-0.09 end
            if guide.createButton then guide.createButton({function_owner=Global,click_function="STA2E_MissionGuideNoop",
                label=tostring(index),position=guide.positionToLocal(point(frame,u,v,STA2E_Playtest.guidePlane()-frame.y+0.015)),rotation={0,0,0},
                width=0,height=0,font_size=260,font_color=PURPLE,tooltip="Dominion deployment bearing "..index}) end
        end
        guide.setVectorLines(lines)
        guide.setDescription("Owned Alliance mission guides. Blue edges are Federation escape edges; purple edges are Dominion edges. "..
            (kind=="finale" and (registry.escapeEdge and "Escape is open on the "..registry.escapeEdge.." edge." or "No Federation escape edge until the Round 5 Beta deployment.") or "Use the outlined player deployment area."))
    end

    function M.markEscape(state,edge)
        local registry=state and state.missionObjects
        if not registry or not ({left=true,right=true,top=true,bottom=true})[edge] then return false end
        registry.escapeEdge=edge
        local guide=registry.guideGUID and getObjectFromGUID(registry.guideGUID)
        if guide then drawGuide(guide,registry) end
        return true
    end

    local function registerObject(state,registry,spec,object,ready)
        local guid=object.getGUID()
        object.setGMNotes(ownership(registry,spec.metadata.kind,spec.metadata))
        local row=clone(spec.metadata);row.guid=guid;row.missionId=registry.missionId;row.runId=registry.runId
        registry.registered=registry.registered or {}
        if not registry.registered[guid] then
            registry.registered[guid]=true
            registry.guids[#registry.guids+1]=guid;registry.objects[#registry.objects+1]=row
        end
        state.generatedGUIDs=state.generatedGUIDs or {};state.generatedGUIDs[guid]=true
        if row.maxHull or row.kind=="listeningPost" or row.kind=="weaponPlatform" then registry.hullObjects[guid]=row end
        if row.kind=="guide" then
            registry.guideGUID=guid
            if ready then drawGuide(object,registry) end
        end
        if spec.metadata.planIndex then
            registry.planGUIDs=registry.planGUIDs or {};registry.readyPlans=registry.readyPlans or {}
            local key=tostring(spec.metadata.planIndex)
            registry.planGUIDs[key]=guid
            if ready then registry.readyPlans[key]=true end
            M.attachScenarioModels(state,registry)
        end
        return guid
    end

    local function submitPlan(state,registry,spec,key)
        spec.data.GMNotes=ownership(registry,spec.metadata.kind,spec.metadata)
        local callbackDone=false
        local ok,result=pcall(function()
            return spawnObjectData({data=spec.data,position=spec.position,rotation=spec.rotation,
                sound=false,callback_function=function(object)
                    if callbackDone then return end
                    callbackDone=true
                    registry.pending=math.max(0,registry.pending-1)
                    if not object then registry.errors[#registry.errors+1]="A "..spec.metadata.kind.." did not spawn."
                    elseif not currentRun(state,registry) then
                        registry.pendingPlans[key]=nil;pcall(function() object.destruct() end)
                    else
                        local registered,message=pcall(registerObject,state,registry,spec,object,true)
                        if registered then registry.pendingPlans[key]=nil
                        else registry.errors[#registry.errors+1]=tostring(message) end
                    end
                    if registry.pending==0 and #registry.errors==0 and currentRun(state,registry) then registry.setupComplete=true end
                end})
        end)
        if not ok then
            if not callbackDone then registry.pending=math.max(0,registry.pending-1) end
            registry.errors[#registry.errors+1]=tostring(result)
        elseif result and not callbackDone and currentRun(state,registry) then
            -- TTS returns the spawning object before its callback. Register its
            -- GUID now so reset/save can own it during that interval as well.
            local registered,guid=pcall(registerObject,state,registry,spec,result,false)
            if registered then spec.guid=guid end
        end
    end

SCENARIO_OBJECT_CONTROLS_SCRIPT = [========[local scenarioMenu=false
local scenarioArc=false
local function scenarioMoves()
    if hullMemory.kind=="freighter" then return {"BL2","S2","BR2","S3"} end
    local out={}
    local speeds=hullMemory.kind=="runabout" and {1,2} or {2,3}
    for _,speed in ipairs(speeds) do for _,bearing in ipairs({"TL","BL","S","BR","TR"}) do out[#out+1]=bearing..speed end end
    return out
end
local originalHullDraw=hullDraw
hullDraw=function()
    originalHullDraw()
    self.createButton({function_owner=self,click_function="scenarioToggleMove",label=scenarioMenu and "CLOSE" or "MOVE",
        position={-0.48,0.24,-0.87},rotation={0,0,0},width=250,height=120,font_size=65,
        color={0.10,0.30,0.46,0.96},font_color={1,1,1},tooltip="Open mission ship maneuver menu"})
    self.createButton({function_owner=self,click_function="scenarioToggleArc",label=scenarioArc and "CLEAR" or "ARC",
        position={0.48,0.24,-0.87},rotation={0,0,0},width=250,height=120,font_size=65,
        color={0.10,0.30,0.46,0.96},font_color={1,1,1},tooltip="Toggle firing arc and range bands"})
    if scenarioMenu then for i,key in ipairs(scenarioMoves()) do
        local callback="scenarioMove_"..key
        _G[callback]=function(_,color)
            if Global.call("STA2E_ScenarioMove",{guid=self.getGUID(),key=key,color=color}) then scenarioMenu=false;hullDraw() end
        end
        self.createButton({function_owner=self,click_function=callback,label=key,
            position={-0.96+((i-1)%5)*0.48,0.25,-1.4-math.floor((i-1)/5)*0.4},rotation={0,0,0},width=170,height=110,font_size=55,
            color={0.10,0.30,0.46,0.96},font_color={1,1,1},tooltip="Execute "..key.."; resolve mission actions manually"})
    end end
end
function scenarioToggleMove() scenarioMenu=not scenarioMenu;hullDraw() end
function scenarioToggleArc()
    scenarioArc=not scenarioArc
    Global.call("STA2E_LegacyGuide",{guid=self.getGUID(),owner=self.getGUID(),mode=scenarioArc and (hullMemory.kind=="tenthFleet" and "front180" or "front90") or "clear"})
    hullDraw()
end
]========]
-- Shared scene-module helpers for standard bases with real attached models.
function M.scenarioHullScript()
    return (STA2E_MISSION_HULL_SCRIPT or "")
        :gsub("self.setLock%(true%)","self.setLock(false)")
        :gsub("position={0,0.23,0}","position={0,0.23,0.95}")
        :gsub("position={%-0.72,0.24,0.72}","position={-0.65,0.24,1.1}")
        :gsub("position={0.72,0.24,0.72}","position={0.65,0.24,1.1}")
        :gsub("font_size=175","font_size=85")
        :gsub("width=400,height=340,font_size=260","width=133,height=113,font_size=87")
        .."\n"..SCENARIO_OBJECT_CONTROLS_SCRIPT
end

function M.scenarioShipBase(kind,title)
    local data=clone(STANDARD_BASE)
    data.GUID=nil;data.Nickname=title;data.Locked=false;data.Grid=false;data.Snap=false
    data.LuaScript="";data.LuaScriptState="";data.XmlUI=""
    data.Transform.scaleX=1.174999;data.Transform.scaleY=1.174999;data.Transform.scaleZ=1.174999
    data.CustomMesh.DiffuseURL=STA2E_BaseTexture(kind=="freighter" and "Red" or "Blue",kind=="miranda" and "180" or "90",false,kind=="freighter")
    data.Tags={"ship","Small","Alliance Objective"}
    return data
end

function M.addScenarioModel(plans,registry,baseIndex,kind,title,position,rotation)
    local data=asset(kind.."Model",title.." Model")
    local offset=(assets[kind.."Model"] or {}).scenarioOffset or (kind=="miranda" and 0.2126 or 0.2)
    data.scenarioOffset=nil
    data.Locked=true;data.LuaScript="";data.LuaScriptState=""
    local childPosition={x=position.x,y=position.y+offset,z=position.z}
    local childIndex=#plans+1
    addPlan(plans,data,childPosition,rotation,{kind="scenarioModel",parentPlanIndex=baseIndex,shipKind=kind})
    registry.attachmentPairs=registry.attachmentPairs or {}
    registry.attachmentPairs[tostring(childIndex)]={basePlanIndex=baseIndex,modelPlanIndex=childIndex,shipKind=kind,offset=offset}
end

function M.attachScenarioModels(state,registry)
    if not currentRun(state,registry) then return end
    for _,pair in pairs(registry.attachmentPairs or {}) do
        if not pair.attached then
            local baseKey,modelKey=tostring(pair.basePlanIndex),tostring(pair.modelPlanIndex)
            local baseGUID=(registry.planGUIDs or {})[baseKey]
            local modelGUID=(registry.planGUIDs or {})[modelKey]
            local base=baseGUID and getObjectFromGUID(baseGUID)
            local model=modelGUID and getObjectFromGUID(modelGUID)
            if base and model and (registry.readyPlans or {})[baseKey] and (registry.readyPlans or {})[modelKey] then
                local ok,err=pcall(function()
                    -- The base may have been moved while assets were loading.
                    local p=base.getPosition()
                    model.setPosition({x=p.x,y=p.y+pair.offset,z=p.z})
                    model.setRotation(base.getRotation())
                    model.setLock(false)
                    base.addAttachment(model)
                end)
                if ok then
                    pair.attached=true;pair.baseGUID=baseGUID
                    -- The model is now a native attachment, not a loose object.
                    state.generatedGUIDs[modelGUID]=nil
                else registry.errors[#registry.errors+1]="Could not attach "..pair.shipKind.." model: "..tostring(err) end
            end
        end
    end
end

-- Injected inside the existing scene module to share ownership, async recovery,
-- board transforms, hull counters and teardown with Part I.
function M.book2Placements(state,sites)
    local frame=state.missionObjects.frame;local result={}
    for _,site in ipairs(sites) do
        if state.playerCount>=(site.minPlayers or 2) then
            result[#result+1]={position=point(frame,site.u,site.v,0.3),rotation=(site.rotation+frame.yaw)%360}
        end
    end
    return result
end

function M.setupBook2(definition,settings,state)
    local g=definition.geometry;local players=state.playerCount
    local registry={runId=state.runId,missionId=definition.id,kind=g.kind,book2=true,geometry=clone(g),
        frame=boardFrame(),guids={},objects={},registered={},hullObjects={},plannedHullCount=0,pending=0,
        setupComplete=false,asteroidCount=0,pendingPlans={},errors={},layoutWarnings={},cancelled=false}
    state.missionObjects=registry
    registry.anchors={}
    for i,a in ipairs(g.bearings) do
        local u,v=a.u,a.v
        if a.edge=="left" then u=u+1.55/registry.frame.halfX elseif a.edge=="right" then u=u-1.55/registry.frame.halfX
        elseif a.edge=="top" then v=v-1.55/registry.frame.halfZ else v=v+1.55/registry.frame.halfZ end
        registry.anchors[i]={position=point(registry.frame,u,v,0.3),rotation=(a.rotation+registry.frame.yaw)%360,
            edge=a.edge,bearing=i,u=a.u,v=a.v}
    end
    local plans,blocked={},{}
    local function block(site,radius) blocked[#blocked+1]={position=point(registry.frame,site.u,site.v),radius=radius or 1.55} end
    local function piece(key,title,kind,index,site,hull,rules,movable)
        local shipKind=kind=="tenthFleet" and "miranda" or kind=="freighter" and "freighter" or nil
        local data=shipKind and M.scenarioShipBase(shipKind,title) or asset(key,title)
        data.Description=rules;data.Locked=not movable
        local metadata={kind=kind,index=index,label=title}
        if hull then
            data.LuaScript=(STA2E_MISSION_HULL_SCRIPT or ""):gsub("self.setLock%(true%)",movable and "self.setLock(false)" or "self.setLock(true)")
            if shipKind then data.LuaScript=M.scenarioHullScript() end
            data.LuaScriptState=JSON.encode({hull=hull,maxHull=hull,kind=kind,missionId=state.missionId,
                runId=state.runId,label=title,index=index,rules=rules})
            metadata.hull=hull;metadata.maxHull=hull;registry.plannedHullCount=registry.plannedHullCount+1
        end
        addPlan(plans,data,point(registry.frame,site.u,site.v,site.height or 0.2),
            {0,(site.rotation or 180)+registry.frame.yaw,0},metadata)
        if shipKind then
            M.addScenarioModel(plans,registry,#plans,shipKind,title,plans[#plans].position,plans[#plans].rotation)
        end
    end
    local guide=primitive("Alliance Book II Mission Guides","BlockSquare")
    guide.Transform.scaleX=0.4;guide.Transform.scaleY=0.08;guide.Transform.scaleZ=0.4;guide.Locked=true
    addPlan(plans,guide,point(registry.frame,0,0,-0.25),{0,0,0},{kind="guide"})
    -- A readable rules reference is owned by this run and removed by Reset.
    local rules=primitive(definition.name.." - Rules","Notecard")
    rules.Description=definition.rulesText;rules.Locked=false
    addPlan(plans,rules,point(registry.frame,1.32,-1.65),{0,180,0},{kind="rules"})
    if g.planet then
        piece("planet","Alliance Mission Planet","planet",1,g.planet,nil,"Planet obstacle.",false);block(g.planet,2.8)
    end
    for index,site in ipairs(g.freighters or {}) do
        if players>=(site.minPlayers or 2) then
            piece("freighter","Dominion Freighter "..index,"freighter",index,site,3,
                "Attack 1 | Agility 1 | Hull 3 | Shields 0. Critical = 2 hits. Move before Activation, closest to E first: defense die evade = 2 straight, BS = 3 straight, blank = 2 bank toward nearest Dominion edge. Do not swerve. Gain BS after clear move; attack nearest player in arc at end Combat. Dominion-edge exit escapes. Resolve manually.",true)
            block(site)
        end
    end
    if g.minefield then
        local n=({5,7,10,12,15})[players-1]
        for index=1,n do
            piece("tokenBack","Mine "..index,"mine",index,{u=1.25+((index-1)%5)*0.07,v=0.1+math.floor((index-1)/5)*0.07},nil,
                "Distribute all mines among ship cards before player deployment. Deploy Mine uses an action after ending fully in C; prohibited if another ship within Range 1 has a deployed token beside it. End Phase: move deployed tokens to top edge. Resolve manually.",true)
        end
    end
    if g.yards then
        local number=0
        for index,site in ipairs(g.yards) do
            if players>=(site.minPlayers or 2) then
                piece("shipyard","Dominion Shipyard "..index,"shipyard",index,site,5,
                    "Attack - | Agility 0 | Hull 5 | Shields 0. Critical = 2 hits. Range 1-3 players roll one fewer defense die. On destruction, docked AS each suffer one critical damage and remain powered down. Resolve manually.",false)
                block(site,1.15)
                for _,dock in ipairs(site.docks) do
                    number=number+1
                    piece("attackShip","Powered-down Attack Ship "..number,"dockedAS",number,dock,3,
                        "Powered down: no activation/attack, Agility 0, no active shields. On matching revealed number or within Range 1 of BC, power up: Skill 1, Agility 2, 2 Shields. Use manual movement/combat; counters track hull only.",true)
                    block(dock,1.15)
                end
            end
        end
        local supply={1,2,3,10}
        local additions={{4,5},{6,11},{7,8},{9,12}}
        for column=3,players do for _,n in ipairs(additions[column-2]) do supply[#supply+1]=n end end
        shuffle(supply);registry.powerUpPool=clone(supply)
        registry.alertCount=({1,2,2,3,3})[players-1]
        for index,number in ipairs(supply) do
            local data=cardToken(number,"Power-up Supply - face down")
            data.Description="Before Planning reveal "..registry.alertCount.." tokens, then discard them. Matching numbered docked ships power up."
            addPlan(plans,data,point(registry.frame,1.24,0.1,0.18+index*0.025),{0,180+registry.frame.yaw,180},
                {kind="powerUpToken",index=index,number=number,faceDown=true})
        end
    end
    if g.sensorArray then
        piece("sensorArray","Dominion Sensor Array","sensorArray",1,g.sensorArray,4,
            "Attack - | Agility 0 | Hull 4 | Shields "..(2*players)..". Critical = 2 hits. Can be target locked. While intact give Scan to the two lowest-numbered enemy AI at start Combat. Physical shields are separate; hull counter does not absorb shield damage.",false)
        block(g.sensorArray,1.15)
        for index=1,2*players do
            piece("shield","Sensor Array Shield "..index,"objectiveShield",index,
                {u=g.sensorArray.u+((index-1)%4)*0.055,v=g.sensorArray.v+0.09+math.floor((index-1)/4)*0.055},nil,
                "Sensor array shield. Remove or flip manually when lost; hull remains separately tracked.",true)
        end
    end
    if g.escorts then
        for index=1,players do
            piece("tokenBack","Escort "..index.." - Miranda / B'Rel","escortShip",index,
                {u=-0.7+(index-1)*0.27,v=-0.88},5,
                "Attack - | Agility 2 | Hull 5 | Shields 0. Federation Miranda or Klingon B'Rel: choose matching captain faction. Place beside player, same facing; remove during maneuver then reform after action. Extra action if no Auxiliary token. May redirect attacks between pair. Critical = 2 hits. Move and resolve manually.",true)
        end
    end
    if g.mirandas then
        for index,site in ipairs(g.mirandas) do
            if players>=(site.minPlayers or 2) then
                piece("miranda","Tenth Fleet Miranda "..index,"tenthFleet",index,site,3+state.influence,
                    "Skill 0 | Attack 2 | Agility 2 | Hull "..(3+state.influence).." | Shields 0. Start Activation: speed 2/3 any normal bearing, then BS or Evade after successful maneuver. End Combat: optional front-180 attack. Critical = 2 hits. Alliance-edge exit escapes. Move/resolve manually.",true)
                block(site)
            end
        end
    end
    for _,row in ipairs(definition.formations or {}) do
        for _,site in ipairs(row.sites or {}) do if players>=(site.minPlayers or 2) then block(site) end end
        if row.round==0 and row.bearing and #row.slotProfiles>0 then
            local anchor=registry.anchors[row.bearing];local yaw=math.rad(anchor.rotation)
            for index=1,#row.slotProfiles do
                local lane=(index-(#row.slotProfiles+1)/2)*3.15
                blocked[#blocked+1]={position={x=anchor.position.x+math.cos(yaw)*lane,
                    z=anchor.position.z-math.sin(yaw)*lane},radius=1.55}
            end
        end
    end
    local layout={asteroidCount=(g.asteroidCount or 0)+(g.pulsarCount or 0),pulsarCount=g.pulsarCount,
        separationRanges=g.separationRanges or 1,zone=g.obstacleZone}
    if layout.asteroidCount>0 then obstacles(plans,registry,layout,blocked) end
    registry.pending=#plans;registry.plannedCount=#plans
    for index,spec in ipairs(plans) do spec.metadata.planIndex=index;registry.pendingPlans[tostring(index)]=spec end
    for index,spec in ipairs(plans) do submitPlan(state,registry,spec,tostring(index)) end
    if registry.pending==0 and #registry.errors==0 then registry.setupComplete=true end
    for _,warning in ipairs(registry.layoutWarnings) do broadcastToAll(warning,{1,0.62,0.22}) end
    return registry
end

-- Runs inside the shared mission scene scope: owned async plans and native attachments.
function M.book3Piece(plans,registry,key,title,kind,index,site,hull,rules,movable,modelKind)
    local data=modelKind and M.scenarioShipBase(modelKind,title) or asset(key,title)
    data.Description=rules;data.Locked=not movable
    local metadata={kind=kind,index=index,label=title}
    if hull then
        local script=STA2E_MISSION_HULL_SCRIPT or ''
        if movable then script=script:gsub('self.setLock%(true%)','self.setLock(false)') end
        if modelKind then
            script=script:gsub('position={0,0.23,0}','position={0,0.23,0.95}')
                :gsub('position={%-0.72,0.24,0.72}','position={-0.65,0.24,1.1}')
                :gsub('position={0.72,0.24,0.72}','position={0.65,0.24,1.1}')
                :gsub('font_size=175','font_size=85')
                :gsub('width=400,height=340,font_size=260','width=133,height=113,font_size=87')
        end
        data.LuaScript=script
        data.LuaScriptState=JSON.encode({hull=hull,maxHull=hull,kind=kind,missionId=registry.missionId,
            runId=registry.runId,label=title,index=index,rules=rules})
        metadata.hull=hull;metadata.maxHull=hull;registry.plannedHullCount=registry.plannedHullCount+1
    end
    addPlan(plans,data,point(registry.frame,site.u,site.v,site.height or 0.22),{0,(site.rotation or 0)+registry.frame.yaw,0},metadata)
    if modelKind then M.addScenarioModel(plans,registry,#plans,modelKind,title,plans[#plans].position,plans[#plans].rotation) end
end

function M.book3Submit(state,plans)
    local registry=state.missionObjects
    registry.setupComplete=false;registry.pending=registry.pending+#plans
    local offset=registry.plannedCount or 0
    for i,spec in ipairs(plans) do
        local index=offset+i;spec.metadata.planIndex=index;registry.pendingPlans[tostring(index)]=spec
    end
    registry.plannedCount=offset+#plans
    for i,spec in ipairs(plans) do submitPlan(state,registry,spec,tostring(offset+i)) end
    if registry.pending==0 and #registry.errors==0 then registry.setupComplete=true end
end

function M.book3Population(state,count)
    local registry=state.missionObjects;local plans={};local site=registry.geometry.planet
    for _,row in ipairs(registry.objects) do
        if row.kind=='population' then local object=getObjectFromGUID(row.guid);if object then object.destruct() end end
    end
    for i=1,count do
        local data=asset('tokenBack','Cardassian Population '..i)
        data.Description='Population, not hull. Each bombardment hit or critical removes ONE. Use the mission controller to keep the count synchronized.'
        addPlan(plans,data,point(registry.frame,site.u+((i-1)%4-1.5)*0.035,site.v+math.floor((i-1)/4)*0.035,0.36+i*0.012),
            {0,registry.frame.yaw,0},{kind='population',index=i})
    end
    M.book3Submit(state,plans)
end

function M.book3Facility(state,index)
    local registry=state.missionObjects;local site=registry.geometry.fixedAsteroids[index]
    if not site then return false end
    local plans={};local hull=2*state.playerCount
    M.book3Piece(plans,registry,'orbitalPlatform','Ketracel White Facility','facility',1,site,hull,
        'Attack - | Agility 0 | Hull '..hull..' | Shields '..hull..'. Resolve attacks manually. Critical = 2 hits against HULL only. While revealed and intact, Jem\'Hadar convert one blank to a hit. Shields are separate physical counters.',false)
    for i=1,hull do
        M.book3Piece(plans,registry,'shield','Facility Shield '..i,'objectiveShield',i,
            {u=site.u+((i-1)%4)*0.05,v=site.v+0.09+math.floor((i-1)/4)*0.05},nil,'Facility shield: flip/remove manually before applying damage to hull.',true)
    end
    for _,row in ipairs(registry.objects) do
        if row.kind=='searchToken' then local o=getObjectFromGUID(row.guid);if o then o.destruct() end end
    end
    M.book3Submit(state,plans);return true
end

function M.setupBook3(definition,settings,state)
    local g=clone(definition.geometry);local players=state.playerCount
    if g.playerAreasOverride then g.playerAreas=g.playerAreasOverride end
    local registry={runId=state.runId,missionId=definition.id,kind=g.kind,book2=true,book3=true,geometry=g,
        frame=boardFrame(),guids={},objects={},registered={},hullObjects={},plannedHullCount=0,pending=0,
        setupComplete=false,asteroidCount=0,pendingPlans={},errors={},layoutWarnings={},cancelled=false,plannedCount=0,anchors={}}
    state.missionObjects=registry
    for i,a in ipairs(g.bearings) do
        local u,v=a.u,a.v
        if a.edge=='left' then u=u+1.55/registry.frame.halfX elseif a.edge=='right' then u=u-1.55/registry.frame.halfX
        elseif a.edge=='top' then v=v-1.55/registry.frame.halfZ else v=v+1.55/registry.frame.halfZ end
        registry.anchors[i]={position=point(registry.frame,u,v,0.3),rotation=(a.rotation+registry.frame.yaw)%360,edge=a.edge,bearing=i,u=a.u,v=a.v}
    end
    local plans,blocked={},{}
    local function block(site,radius)blocked[#blocked+1]={position=point(registry.frame,site.u,site.v),radius=radius or 1.55}end
    local function piece(key,title,kind,index,site,hull,rules,movable,modelKind)
        M.book3Piece(plans,registry,key,title,kind,index,site,hull,rules,movable,modelKind)
    end
    local guide=primitive('Alliance Part III Mission Guides','BlockSquare')
    guide.Transform.scaleX=0.4;guide.Transform.scaleY=0.08;guide.Transform.scaleZ=0.4;guide.Locked=true
    addPlan(plans,guide,point(registry.frame,0,0,-0.25),{0,0,0},{kind='guide'})
    local rules=primitive(definition.name..' - Rules','Notecard');rules.Description=definition.rulesText;rules.Locked=false
    addPlan(plans,rules,point(registry.frame,1.32,-1.65),{0,180,0},{kind='rules'})
    if g.planet then
        local hull=g.kind=='raid' and 5*players or nil
        piece('planet',g.kind=='raid' and 'Planetary Installation C - Supply Storage' or 'Alliance Mission Planet','planet',1,g.planet,hull,
            g.kind=='raid' and ('Attack 3 | Agility 0 | Hull '..hull..' | Shields 0. Critical = 2 hits. End Combat: attack each player within Range 3 separately; convert all BS to hits. Supply tokens stored here are BEAMED FROM PLATFORM B, not from this planet.') or 'Planet obstacle.',false)
        block(g.planet,2.8)
    end
    for i,site in ipairs(g.platforms or {}) do
        piece('orbitalPlatform','Benzar Orbital Platform '..i,'orbitalPlatform',i,site,5,
            'Attack - | Agility 1 | Hull 5 | Shields 0. Based piece. Critical = 2 hits. Each intact platform adds one evade result when the Battleship defends.',false);block(site,1.15)
    end
    for i,site in ipairs(g.controls or {}) do
        piece('orbitalPlatform','Control Platform '..i,'controlPlatform',i,site,8,
            'Attack - | Agility 0 | Hull 8 | Shields 0. Based piece. Critical = 2 hits. Each intact Control Platform converts one BS result to a hit in Weapon Platform attacks.',false);block(site,1.15)
    end
    for i,site in ipairs(g.weapons or {}) do if players>=(site.minPlayers or 2) then
        local hull=g.kind=='cardassiaFinale' and 8 or 4
        piece('weaponPlatform','Weapon Platform '..i,'weaponPlatform',i,site,hull,
            'Attack 3 | Agility 0 | Hull '..hull..' | Shields 0. Based piece. Critical = 2 hits. End Combat: nearest player within Range 3, 360-degree arc. '..
            (g.kind=='cardassiaFinale' and 'Convert all BS to hits. Start each round use BOMBARDMENT on the mission controller.' or 'Convert one BS to a hit per intact Control Platform.'),false);block(site,1.15)
    end end
    if g.relay then
        piece('weaponPlatform','Sensor Relay A','sensorRelay',1,g.relay,nil,'End Combat, Range 1: spend assigned red target-lock tokens to reveal mission tokens. Escape carrying #1 to complete A. No normal platform attacks.',false);block(g.relay,1.15)
        local pool={1};for n=2,players+1 do pool[#pool+1]=n end;shuffle(pool)
        for i,n in ipairs(pool) do
            local data=cardToken(n,'Sensor Data - face down')
            addPlan(plans,data,point(registry.frame,g.relay.u,g.relay.v,0.35+i*0.025),{0,180+registry.frame.yaw,180},{kind='dataToken',index=i,number=n,faceDown=true})
        end
        piece('orbitalPlatform','Supply Depot B - Beam From Here','supplyDepot',1,g.depot,nil,
            'End Activation, Range 1 of this PLATFORM: spend Scan tokens, disable shields, take one supply per Scan. Supplies are physically stored on planet C. Escape with at least one supply per player collectively.',false);block(g.depot,1.15)
        for i=1,2*players do
            piece('tokenBack','Raid Supply '..i,'raidSupply',i,{u=g.planet.u+((i-1)%4-1.5)*0.035,v=g.planet.v+(math.floor((i-1)/4)-(math.ceil(2*players/4)-1)/2)*0.035,height=0.38+i*0.018},nil,
                'Stored on planet C; BEAM FROM PLATFORM B at Range 1. No #1 data token is used for supplies. Lost on destruction; cannot transfer between player ships.',true)
        end
    end
    if g.fixedAsteroids then
        local pool=shuffle({1,2,3,4,5,6});registry.searchPool=clone(pool)
        for i,site in ipairs(g.fixedAsteroids) do
            piece('asteroid','Search Asteroid '..i,'asteroid',i,site,nil,'Search at Range 1 at end Combat by spending Scan. Reveal its face-down token.',false)
            local data=cardToken(pool[i],'Asteroid '..i..' Search - face down')
            addPlan(plans,data,point(registry.frame,site.u,site.v,0.36),{0,180+registry.frame.yaw,180},{kind='searchToken',index=i,number=pool[i],faceDown=true})
        end
        registry.asteroidCount=6
    end
    if g.kind=='supplyRun' then
        local pool={12};for n=1,players-1 do pool[#pool+1]=n end;shuffle(pool);registry.contactPool=clone(pool)
        for i,n in ipairs(pool) do
            local data=cardToken(n,'Galor '..i..' Contact - face down');local p=allianceCardSlot(i)
            addPlan(plans,data,{x=p[1],y=p[2]+0.3,z=p[3]},{0,180,180},{kind='contactToken',index=i,number=n,faceDown=true})
        end
        for i=1,math.ceil(players/2) do
            piece('tokenBack','Supply Cargo '..i,'supplyCargo',i,{u=1.3+(i-1)*0.09,v=-0.5},nil,
                'Distribute onto player ship cards. Cargo has no inherent Disabled effect. If its carrier is destroyed, lose supplies and fail this mission. Contact #12 Galor using Scan; resolve transfer conditions manually.',true)
        end
    end
    if g.escorts then
        local kinds={federation='miranda',klingon='brel',romulan='scout'}
        local names={miranda='Miranda',brel="B'Rel",scout='Romulan Scout'}
        for i=1,players do
            local kind=kinds[state.book3.escortFactions[i]]
            piece('tokenBack','Escort '..i..' - '..names[kind],'escortShip',i,{u=-0.8+(i-1)*0.32,v=-0.91},5,
                'Attack - | Agility 2 | Hull 5 | Shields 0. Move by hand into formation beside its assigned player, same facing. Re-form after the player moves/acts. Extra action if no Auxiliary Power; manual attack redirection. Critical = 2 hits. Fresh escort for this mission.',true,kind)
        end
    end
    for _,row in ipairs(definition.formations) do
        if row.round==0 then for _,site in ipairs(row.sites or {}) do if players>=(site.minPlayers or 2) then block(site) end end end
    end
    if (g.asteroidCount or 0)>0 then obstacles(plans,registry,{asteroidCount=g.asteroidCount,zone=g.obstacleZone,polygon=g.obstaclePolygon},blocked) end
    M.book3Submit(state,plans)
    if g.kind=='cardassiaFinale' then M.book3Population(state,state.book3.population) end
    for _,warning in ipairs(registry.layoutWarnings) do broadcastToAll(warning,{1,0.62,0.22}) end
    return registry
end

    function M.setup(definition,settings,state)
        settings=settings or {};state=state or {}
        if state.missionObjects and not state.missionObjects.cancelled then M.teardown(state) end
        if definition.book3 then return M.setupBook3(definition,settings,state) end
        if definition.book2 then return M.setupBook2(definition,settings,state) end
        local kind=kindOf(definition)
        local layout=layouts[kind]
        local players=math.max(2,math.min(6,tonumber(settings.playerCount or state.playerCount) or 2))
        local registry={runId=state.runId,missionId=definition.id or state.missionId,kind=kind,frame=boardFrame(),
            guids={},objects={},registered={},hullObjects={},plannedHullCount=0,pending=0,setupComplete=false,
            asteroidCount=0,pendingPlans={},
            errors={},layoutWarnings={},cancelled=false}
        registry.anchors=makeAnchors(definition,registry.frame)
        state.missionObjects=registry
        local plans,blocked={},{}
        local function block(site,radius) blocked[#blocked+1]={position=point(registry.frame,site.u,site.v),radius=radius} end

        local guide=primitive("Alliance Mission Guides","BlockSquare")
        guide.Transform.scaleX=0.4;guide.Transform.scaleY=0.08;guide.Transform.scaleZ=0.4;guide.Locked=true
        addPlan(plans,guide,point(registry.frame,0,0,-0.25),{0,0,0},{kind="guide"})

        if layout.planet then
            local data=asset("planet","Alliance Mission Planet")
            data.Locked=true;data.Description="Planet obstacle, positioned according to the mission book."
            addPlan(plans,data,point(registry.frame,layout.planet.u,layout.planet.v),{0,180+registry.frame.yaw,0},{kind="planet"})
            block(layout.planet,2.8)
        end
        if kind=="patrol" then
            for index,site in ipairs(layout.sensors) do
                local data=asset(index==1 and "token9" or "token8",site.parity=="odd" and "Odd Sensor Data Site" or "Even Sensor Data Site")
                data.Description="End of Activation: spend a Scan token at Range 1 to collect matching sensor data. The site remains in play."
                addPlan(plans,data,point(registry.frame,site.u,site.v),{0,180+registry.frame.yaw,0},{kind="sensorSite",parity=site.parity})
                block(site,0.55)
            end
        elseif kind=="evacuation" then
            for index=1,players+1 do
                local data=asset("tokenBack","Survey Team "..index)
                data.Description="Survey team on the planet. End of Activation: spend Scan at Range 1 and disable shields to embark."
                addPlan(plans,data,point(registry.frame,0,0,0.16+index*0.15),{0,180+registry.frame.yaw,0},{kind="surveyTeam",index=index})
            end
        elseif kind=="search" then
            local pool={1,2,3};local optional={4,5,6,7,8,9,10,11,12};shuffle(optional)
            for index=1,players do pool[#pool+1]=optional[index] end
            shuffle(pool)
            -- Sites are filled in printed ascending order, independently of the
            -- shuffled secret token numbers. The pool is saved for reloads.
            registry.searchPool=clone(pool)
            for index,number in ipairs(pool) do
                local site=layout.search[index]
                addPlan(plans,cardToken(number,"Unrevealed Search Token"),point(registry.frame,site.u,site.v),
                    {0,180+registry.frame.yaw,180},{kind="searchToken",site=index,number=number,faceDown=true})
                block(site,0.55)
            end
        elseif kind=="escort" then
            for _,site in ipairs(layout.runabouts) do
                if players>=site.minPlayers then
                    local index=1
                    for _,entry in ipairs(plans) do if entry.metadata.kind=="runabout" then index=index+1 end end
                    local data=M.scenarioShipBase("runabout","Mission Runabout "..index)
                    data.Description="Attack - | Agility 2 | Hull 2 | Shields 2. Move speed 1 or 2 before ship Activation; gain Evade after a successful maneuver. Critical hits become two hits. Escape off a Federation edge."
                    data.LuaScript=M.scenarioHullScript()
                    data.LuaScriptState=JSON.encode({hull=2,maxHull=2,kind="runabout",missionId=state.missionId,
                        runId=state.runId,label="Mission Runabout "..index,index=index,rules=data.Description})
                    registry.plannedHullCount=registry.plannedHullCount+1
                    addPlan(plans,data,point(registry.frame,site.u,site.v,0.22),{0,registry.frame.yaw,0},{kind="runabout",index=index,hull=2,maxHull=2,shields=2})
                    M.addScenarioModel(plans,registry,#plans,"runabout","Mission Runabout "..index,plans[#plans].position,plans[#plans].rotation)
                    block(site,1.15)
                end
            end
        elseif kind=="listening" then
            for index,site in ipairs(layout.posts) do hullPiece(plans,registry,"listeningPost",index,site);block(site,1.155) end
        elseif kind=="finale" then
            local influence=math.max(0,math.min(2,tonumber(settings.influence or state.influence) or 0))
            for index=1,4-influence do hullPiece(plans,registry,"weaponPlatform",index,layout.platforms[index]) end
        end
        obstacles(plans,registry,layout,blocked)
        registry.pending=#plans
        registry.plannedCount=#plans
        -- Populate every serializable plan first, before even a synchronous
        -- callback can run. Mid-setup saves can resume any genuinely missing one.
        for index,spec in ipairs(plans) do
            spec.metadata.planIndex=index
            registry.pendingPlans[tostring(index)]=spec
        end
        for index,spec in ipairs(plans) do submitPlan(state,registry,spec,tostring(index)) end
        if registry.pending==0 and #registry.errors==0 then registry.setupComplete=true end
        for _,warning in ipairs(registry.layoutWarnings) do broadcastToAll(warning,{1,0.62,0.22}) end
        if #registry.errors>0 then broadcastToAll("Alliance scene setup needs attention: "..table.concat(registry.errors,"; "),{1,0.35,0.20}) end
        return registry
    end

    function M.reconcile(state)
        local registry=state and state.missionObjects
        if not registry or registry.cancelled then return false end
