;(function()
-- Alliance Part One: isolated, save-persistent mission sessions.
-- Append after the base Global and mission definition/object modules.
;(function()
local R={version=1,context=nil,serial=0}
local previousProcess=STA2E_AllianceProcessRound
local previousStart=STA2E_AllianceStart
local previousSpawn=spawnObjectData
local previousShields=allianceSpawnShields
local previousPhase=STA2E_PhaseUI
local previousReconcile=STA2E_Reconcile
local previousDestroy=onObjectDestroy

-- Added within the existing R module. All event state lives in the saved mission session.
function R.book3Defect(s)
    if s.book3.defected then return false end
    s.book3.defected=true
    for id in pairs(s.shipRecords or {}) do
        local ship=STA2E.ships[id]
        if ship then
            if ship.ai then ship.ai.plan=nil;ship.ai.message=nil end
            if ship.aiProfile=='GR' or ship.aiProfile=='GE' then
                ship.side='allied';ship.ai=ship.ai or {};ship.ai.enabled=true;ship.ai.intent='engage'
                ship.ai.manualMissionOrders=false;ship.ai.missionOrders='Attack';ship.missionOrders='Attack'
            end
            commit(ship);refresh(ship)
        end
    end
    R.say('Cardassians have defected. Their AI remains enabled and targets enemy Jem\'Hadar/Breen; Dominion AI now treats Cardassians as opponents.')
    return true
end

function R.book3Round(s)
    local round=tonumber(STA2E.game.round) or 0
    if s.missionId=='A9M1' and round>=(s.book3.supplyRun and 4 or 5) then R.book3Defect(s) end
    if s.missionId=='A9M2' and round>=1 and s.book3.bombardmentReminder~=round then
        s.book3.bombardmentReminder=round
        R.say('START ROUND '..round..': use BOMBARDMENT before other round effects. Population '..s.book3.population..'. Roll once; each hit/critical removes ONE.',{1,0.78,0.35})
    end
end

function STA2E_Book3Event(params)
    params=params or {};local s=R.current()
    if not R.valid(s) or not s.definition.book3 then return {ok=false,error='No active Part III mission.'} end
    local mismatch=R.checkId(s,params);if mismatch then return mismatch end
    if params.runId and params.runId~=s.runId then return {ok=false,error='Stale mission event.'} end
    if R.pending(s) then return {ok=false,error='Wait for mission spawning to finish.'} end
    local action=params.action;local state=s.book3
    if action=='battleshipDestroyed' and s.missionId=='A7M1' then
        if state.battleshipDestroyed then return {ok=false,error='Battleship destruction already recorded.'} end
        state.battleshipDestroyed=true
        for _,wave in pairs(s.waves) do
            if not wave.spawned then wave.cancelled=true;wave.spawned=true;wave.status='cancelled after Battleship destruction' end
            wave.orders='Withdraw'
        end
        for id,record in pairs(s.shipRecords) do
            local ship=STA2E.ships[id]
            if ship then
                if ship.aiProfile=='BSR' or ship.aiProfile=='BSE' then
                    ship.combat.hull=0;ship.combat.destroyed=true;record.destroyed=true
                else
                    ship.missionOrders='Withdraw';ship.ai.missionOrders='Withdraw';ship.ai.enabled=false;ship.ai.manualMissionOrders=true;ship.ai.plan=nil
                end
                commit(ship);refresh(ship)
            end
        end
        R.say('Battleship destroyed: undeployed waves cancelled. Resolve Withdraw movement/actions/attacks manually. Finish after adjudicating survival and the printed early-end rule.')
    elseif action=='facilityRevealed' and s.missionId=='A8M1' then
        if state.facilityIndex then return {ok=false,error='Facility already revealed; use Retry Waves for blocked reinforcements.'} end
        local index=tonumber(params.asteroid)
        if not index or index~=math.floor(index) or index<1 or index>6 then return {ok=false,error='Choose discovered asteroid 1-6.'} end
        if STA2E.game.phase~='combat' then return {ok=false,error='Reveal the facility at the end of Combat after finding the third echo.'} end
        local site=s.definition.geometry.fixedAsteroids[index];local frame=s.missionObjects.frame
        local angle=math.rad(frame.yaw);local x,z=site.u*frame.halfX,site.v*frame.halfZ
        local location={x=frame.x+x*math.cos(angle)+z*math.sin(angle),z=frame.z-x*math.sin(angle)+z*math.cos(angle)}
        local choices,best={},nil
        for i,a in ipairs(s.missionObjects.anchors) do
            local d=(a.position.x-location.x)^2+(a.position.z-location.z)^2
            if not best or d>best+0.0001 then best=d;choices={i} elseif math.abs(d-best)<0.0001 then choices[#choices+1]=i end
        end
        local bearing=choices[math.random(1,#choices)]
        state.facilityIndex=index;state.facilityRound=STA2E.game.round;state.facilityBearing=bearing
        for _,row in ipairs(s.definition.formations) do if row.event=='facility' then
            row.round=STA2E.game.round+1;row.bearing=bearing;s.waves[row.id].round=row.round;s.waves[row.id].status='scheduled after reveal'
        end end
        STA2E.MissionObjects.book3Facility(s,index)
        R.say('Facility on asteroid '..index..'. Dominion Alpha arrives next round at furthest bearing '..bearing..'. While intact, Jem\'Hadar convert one blank attack result to a hit (manual).')
    elseif action=='defect' and s.missionId=='A9M1' then
        if STA2E.game.round<(state.supplyRun and 4 or 5) then return {ok=false,error='Cardassian defection is not due yet.'} end
        R.book3Defect(s)
    elseif (action=='bombardment' or action=='populationPlus' or action=='populationMinus') and s.missionId=='A9M2' then
        local population=state.population
        if action=='bombardment' then
            local round=tonumber(STA2E.game.round) or 0
            if round<1 or STA2E.game.phase~='planning' then return {ok=false,error='Bombardment is resolved at the start of the round (Planning).'} end
            if state.lastBombardmentRound>=round then return {ok=false,error='Bombardment already rolled this round. Use population +/- to correct manual results.'} end
            local platforms=0
            for _,row in ipairs(R.hulls(s)) do if row.kind=='weaponPlatform' and (tonumber(row.hull) or 0)>0 then platforms=platforms+1 end end
            local loss,results=0,{}
            for i=1,platforms+1 do
                local die=math.random(1,8);local result=die<=3 and 'hit' or die==4 and 'critical' or die<=6 and 'BS' or 'blank'
                results[#results+1]=result;if result=='hit' or result=='critical' then loss=loss+1 end
            end
            population=math.max(0,population-loss);state.lastBombardmentRound=round
            state.lastBombardment={round=round,dice=platforms+1,results=results,loss=loss}
            R.say('Bombardment Round '..round..': '..table.concat(results,', ')..'; '..loss..' population lost; '..population..' remain.')
        else population=math.max(0,math.min(50,population+(action=='populationPlus' and 1 or -1))) end
        state.population=population;STA2E.MissionObjects.book3Population(s,population)
        if population==0 then R.say('Cardassian population is zero: campaign failure. Resolve with FINISH.',{1,0.35,0.25}) end
    else return {ok=false,error='This event is not available in this mission.'} end
    return STA2E_MissionStatus({id=s.missionId})
end

function R.current()
    local s=allianceState()
    return s and s.runtimeVersion==R.version and s or nil
end
function R.valid(s) return type(s)=="table" and R.current()==s and s.active==true and not s.resetting end
function R.say(text,color) broadcastToAll("[Alliance] "..text,color or {0.75,0.65,1}) end
function R.destroy(object) if object then pcall(function() object.destruct() end) end end
function R.remember(s,object)
    if not object then return end
    s.generatedGUIDs=s.generatedGUIDs or {}
    s.generatedGUIDs[object.getGUID()]=true
end
function R.findSlot(s,id)
    for _,wave in pairs(s.waves or {}) do
        for _,slot in ipairs(wave.slots or {}) do if slot.instanceId==id then return slot,wave end end
    end
end
function R.numberKey(value) return tostring(math.floor(tonumber(value) or 0)) end
function R.count(row,players)
    local playerNumber=math.floor(tonumber(players) or 0)
    local n=tonumber((row.counts or {})[playerNumber] or (row.counts or {})[R.numberKey(playerNumber)]) or 0
    return math.max(0,math.floor(n))
end
function R.checkId(s,params)
    if params and params.id and s and params.id~=s.missionId then return {ok=false,error="This controller belongs to a different mission. Use the active mission's controller."} end
end
function R.record(s,id)
    s.shipRecords=s.shipRecords or {}
    s.shipRecords[id]=s.shipRecords[id] or {instanceId=id,shieldGUIDs={},pendingObjects=0,pendingShields=0}
    return s.shipRecords[id]
end
function R.applyOrders(s,id)
    local ship=STA2E.ships[id];local slot,wave=R.findSlot(s,id)
    if not ship or not slot then return end
    ship.missionRunId=s.runId;ship.missionFormationId=wave.id;ship.missionOrders=wave.orders
    ship.side=(s.definition.book3 and s.book3 and s.book3.defected and (ship.aiProfile=="GR" or ship.aiProfile=="GE")) and "allied" or "enemy";ship.ai=ship.ai or {intent="engage"}
    if s.definition.book3 and s.book3 and s.book3.battleshipDestroyed then wave.orders="Withdraw";ship.missionOrders="Withdraw" end
    ship.ai.missionOrders=wave.orders
    ship.ai.manualMissionOrders=wave.orders~="Attack"
    if ship.ai.manualMissionOrders then ship.ai.enabled=false elseif s.definition.book3 then ship.ai.enabled=true end
    commit(ship);refresh(ship)
end

-- Guard the legacy asynchronous card/component callbacks with session identity.
-- Unrelated fleet spawns pass straight through this adapter.
function spawnObjectData(params)
    local s=R.current();local m
    if s and params and params.data and params.data.LuaScriptState then
        local ok,value=pcall(JSON.decode,params.data.LuaScriptState)
        if ok and type(value)=="table" then m=value end
    end
    local id=m and (m.instanceId or (m.transaction and m.transaction:match("^alliance:(.+)$")))
    local context=R.context
    if not s or not id or not ((s.shipRecords or {})[id] or (context and context.state==s)) then return previousSpawn(params) end
    local record=R.record(s,id)
