end

function R.shieldCount(s,record)
    local count=0
    for guid in pairs(record.shieldGUIDs or {}) do if obj(guid) then count=count+1 else record.shieldGUIDs[guid]=nil end end
    return count
end
function R.shields(s,ship)
    local record=R.record(s,ship.instanceId)
