-- Book II definitions retain the printed per-column class and Elite markers.
function STA2E_Book2Prepare(source,players,difficulty)
    local d=copy(source)
    if not d.book2 then return d end
    d.adjusted=difficulty=="adjusted"
    for _,row in ipairs(d.formations) do
        row.slotProfiles={};row.counts={}
        if not row.hardOnly or d.adjusted then
            for column=2,players do
                for _,entry in ipairs(row.columns[tostring(column)] or {}) do
                    local elite=entry.elite=="always" or (entry.elite=="difficulty_only" and d.adjusted)
                    for i=1,entry.quantity do row.slotProfiles[#row.slotProfiles+1]=entry.ship_class..(elite and "E" or "R") end
                end
            end
        end
        row.counts[tostring(players)]=#row.slotProfiles
    end
    return d
end

