-- Clear transient hover help when a dial disappears or the save reloads.
;(function()
    local previousDestroy=onObjectDestroy
    function onObjectDestroy(object)
        if object then local guid=object.getGUID();STA2E.DialHover.clear(guid);STA2E.DialHover.objects[guid]=nil end
        if previousDestroy then return previousDestroy(object) end
    end
    local previousLoad=onLoad
    function onLoad(saved)
        STA2E.DialHover.clear();STA2E.DialHover.objects={};STA2E.DialHover.players={}
        return previousLoad(saved)
    end
end)()

-- ALLIANCE_INTERACTIVE_CAPTAINS_20261013
;(function()
    local A={}
    STA2E.AllianceCaptain=A
    function A.progress(value)
        if type(value)~="table" or (value.version~=nil and value.version~=2) then return nil,"Invalid Alliance captain tracker." end
        if value.name~=nil and (type(value.name)~="string" or #value.name>400) then return nil,"Invalid captain name." end
        local state={version=2,name=value.name or ""}
        for track,maximum in pairs({Elite=6,Skill=14,Crew=10,Weapon=10,Tech=10}) do
            local n=value[track]
            if n==nil then n=0 end
            if type(n)~="number" or n~=n or n<0 or n>maximum or n~=math.floor(n) then return nil,"Invalid "..track.." XP." end
            state[track]=n
        end
        local choices={None=true,Crew=true,Weapon=true,Tech=true}
        for _,field in ipairs({"ExpansionOne","ExpansionTwo"}) do
            local choice=value[field]
            if choice==nil then choice="None" end
            if type(choice)~="string" or not choices[choice] then return nil,"Invalid captain expansion slot." end
            state[field]=choice
        end
        return state
    end
    function A.pendingState(data,color,transaction,progress)
        local state=progress and assert(A.progress(progress)) or decode(data.LuaScriptState) or {version=2}
        state.memory={schemaVersion=1,role="pending",transaction=transaction}
        local player=Player[color]
        if not progress or state.name=="" then state.name=player and player.steam_name and player.steam_name~="" and player.steam_name or "Alliance Captain" end
        data.Nickname=state.name
        return JSON.encode(state)
    end
    function A.apply(s,entry,snapshot)
        if type(snapshot)~="table" then return false end
        local name=tostring(snapshot.name or "")
        local skill=tonumber(snapshot.skill)
        if not skill or skill~=skill then return false end
        skill=math.max(2,math.min(9,math.floor(skill)))
        local xp=math.max(0,math.floor(tonumber(snapshot.xp) or 0))
        local old=s.allianceCaptain
        if old and old.guid==entry.guid and old.name==name and old.skill==skill and old.xp==xp then return false end
        if old and old.guid==entry.guid and old.skill~=skill then s.skillOverride=nil end
        s.allianceCaptain={guid=entry.guid,cardId=entry.cardId,name=name,skill=skill,xp=xp}
        return true
    end
    function A.syncCaptain(s)
        for _,entry in ipairs(s.upgrades or {}) do
            local card=CATALOG[entry.cardId]
            if card and card.type=="captain" then
                if not card.interactiveCaptain then return false end
                local object=obj(entry.guid)
                if not object then return false end
                local ok,snapshot=pcall(function() return object.call("STA2E_CaptainSnapshot") end)
                return ok and A.apply(s,entry,snapshot) or false
            end
        end
        return false
    end
    function A.syncShipName(s)
        local card=obj(s.cardGUID)
        if not card then return false end
        local actual=tostring(card.getName() or "")
        if s.observedShipCardName==nil then s.observedShipCardName=actual;return false end
        if actual==s.observedShipCardName then return false end
        s.observedShipCardName=actual
        local cleaned=actual:match("^%s*(.-)%s*$")
        local name=cleaned~="" and cleaned or importedShipName(CATALOG[s.definitionId])
        if name==s.name then return false end
        s.name=name
        return true
    end
    function A.scan()
        for _,s in pairs(STA2E.ships or {}) do
            local shipChanged=A.syncShipName(s)
            local captainChanged=A.syncCaptain(s)
            if shipChanged or captainChanged then refresh(s) end
        end
    end
    function STA2E_AllianceCaptainChanged(params)
        local object=params and params.object
        local m=metadata(object)
        local s=m and STA2E.ships[m.instanceId]
        if not s or m.role~="upgrade" or m.cardGUID~=s.cardGUID then return end
        for _,entry in ipairs(s.upgrades or {}) do
            local card=CATALOG[entry.cardId]
            if entry.guid==object.getGUID() and card and card.interactiveCaptain then
                if A.apply(s,entry,params.snapshot) then refresh(s) end
                return
            end
        end
    end
    local previousUpdate=onUpdate
    local nextCheck=0
    function onUpdate()
        if previousUpdate then previousUpdate() end
        if not STA2E.ready or STA2E.loading or STA2E.reconciling or Time.time<nextCheck then return end
        nextCheck=Time.time+0.5
        A.scan()
    end
    local previousReconcile=STA2E_Reconcile
    function STA2E_Reconcile()
        previousReconcile()
        A.scan()
    end
    local previousSave=onSave
    function onSave()
        if STA2E.ready and not STA2E.loading then A.scan() end
        return previousSave()
    end
end)()

-- Playtest pass 2026-10-19. Enhanced AI remains the primary controller.
-- Kept inside the packaged Global chunk so existing lexical helpers are shared.
STA2E_Playtest={version=1}
;(function()
local P=STA2E_Playtest
function P.actionLabel(id,text)
 local key=id:match("^action_(.+)$") or id:match("^ai_action_(.+)$")
 local labels={EVA="◇ Evade",BS="▦ Stations",TL="⊕ Target Lock",SCN="◎ Scan",CLK="◈ Cloak",REG="+ Regenerate",ECHO="↔ Sensor Echo"}
 return key and labels[key] or text
end
function P.cooperative()
 local mission=allianceState()
 return mission and mission.active==true and not mission.finished
end
function P.canManage(s,color)
 if not s then return false end
 if color==s.owner or color=="Black" or (Player[color] and Player[color].host) then return true end
 return own(color) and P.cooperative() and aiSide(s)=="allied" or false
end
function P.visibility(s)
 local colors={}
 for _,color in ipairs(PLAYER_COLORS) do if P.canManage(s,color) then colors[#colors+1]=color end end
 colors[#colors+1]="Black"
 return table.concat(colors,"|")
end
function P.frame()
 local mission=allianceState()
 if mission and mission.missionObjects and mission.missionObjects.frame then return mission.missionObjects.frame end
 local board=obj("ae9c49")
 local p=board and board.getPosition() or {x=0,y=1,z=0}
 local r=board and board.getRotation() or {y=90}
 local scale=board and board.getScale() or {x=1.89,z=1.89}
 return {x=p.x,z=p.z,y=p.y,yaw=r.y-90,halfX=18.1*scale.x/1.89,halfZ=18.1*scale.z/1.89}
end
function P.edgeRisk(finish,shape)
 local f=P.frame();local a=math.rad(f.yaw)
 local dx,dz=finish.x-f.x,finish.z-f.z
 local x,z=dx*math.cos(a)-dz*math.sin(a),dx*math.sin(a)+dz*math.cos(a)
 local yaw=math.rad(finish.yaw-f.yaw)
 local hx=math.abs(math.cos(yaw))*shape.x+math.abs(math.sin(yaw))*shape.z
 local hz=math.abs(math.sin(yaw))*shape.x+math.abs(math.cos(yaw))*shape.z
 local clearance=math.min(f.halfX-math.abs(x)-hx,f.halfZ-math.abs(z)-hz)
 if clearance<0 then return 100-clearance*25 end
 return clearance<1.0 and (1.0-clearance)*12 or 0
end
function P.hostile(a,b)
 return a and b and a.instanceId~=b.instanceId and aiSide(a)~=aiSide(b)
  and not (b.combat and b.combat.destroyed) and not (b.state and b.state.destroyed)
  and member(b,"base")~=nil
end
function P.damage(s)
 local c=s.combat
 if c and type(c.hull)=="number" and type(c.maxHull)=="number" then return math.max(0,c.maxHull-c.hull) end
 return 0
end
function P.selectTarget(s)
 if not member(s,"base") then return nil end
 local candidates={};local nonTouchingInRange=false
 for _,target in pairs(STA2E.ships) do if P.hostile(s,target) then
  local m=MeasurementGeometry.measure(s,target)
  if m then
   if m.range>=1 and m.range<=3 then nonTouchingInRange=true end
   local zone=AllianceAI.zone(m.attackerBoundary,m.targetBoundary.center)
   local damage=P.damage(target)
   -- Distance dominates; prefer a useful firing solution and a damaged target
   -- only when distances are reasonably close. Never use a private player dial.
   local score=m.baseEdgeDistance+(zone-1)*0.45
   if m.range>0 and m.range<=3 and (m.arcs.primary or m.arcs.rear or m.arcs.secondary) then score=score-1.25 end
   score=score-math.min(1.5,damage*0.3)
   candidates[#candidates+1]={target=target,measure=m,zone=zone,score=score,
    reason="distance / available arc / exposed damage"}
  end
 end end
 table.sort(candidates,function(a,b)
  local at=a.measure.range==0 and nonTouchingInRange
  local bt=b.measure.range==0 and nonTouchingInRange
  if at~=bt then return not at end
  if math.abs(a.score-b.score)>0.00001 then return a.score<b.score end
  return tostring(a.target.instanceId)<tostring(b.target.instanceId)
 end)
 return candidates[1]
end
function P.project(boundary,finish)
 local origin=boundary.origin or boundary.center
 local a=math.rad(finish.yaw-boundary.yaw)
 local ox,oz=boundary.center.x-origin.x,boundary.center.z-origin.z
 local b={origin={x=finish.x,z=finish.z},center={x=finish.x+ox*math.cos(a)+oz*math.sin(a),z=finish.z-ox*math.sin(a)+oz*math.cos(a)},yaw=finish.yaw,footprint=boundary.footprint,points={}}
 for _,p in ipairs(boundary.points) do
  local x,z=p.x-origin.x,p.z-origin.z
  b.points[#b.points+1]={x=finish.x+x*math.cos(a)+z*math.sin(a),z=finish.z-x*math.sin(a)+z*math.cos(a)}
 end
 return b
end
function P.moveScore(s,entry,snapshot,finish,targetBoundary,stop)
 local b=P.project(snapshot.boundary,finish)
 local d=MeasurementGeometry.nearestPoints(b,targetBoundary).distance
 local profile=definition(s.definitionId)
 local arcs=MeasurementGeometry.validateArc(b,targetBoundary,profile and profile.arc or "90")
 local shot=d>0.02 and d<=RANGE_SEGMENT*3 and (arcs.primary or arcs.rear or arcs.secondary)
 local desired=math.deg(math.atan2(-(targetBoundary.center.x-finish.x),-(targetBoundary.center.z-finish.z)))
 local score
 if s.ai.intent=="escape" then
  score=-math.min(d,RANGE_SEGMENT*4)*0.8+aiAngleDistance(finish.yaw,desired+180)*0.018
 elseif s.ai.intent=="chase" then
  score=d*0.9+aiAngleDistance(finish.yaw,desired)*0.035
 else
  score=math.abs(d-RANGE_SEGMENT*1.5)*0.55+aiAngleDistance(finish.yaw,desired)*0.045
 end
 if shot then score=score-6 end
 if entry.difficulty=="red" then score=score+3.5 end
 if entry.difficulty=="green" and #aiAuxTokens(s)>0 then score=score-1 end
 if stop<0.999 then score=score+8 end
 return score
end
-- Public target state drives automatic tactics. Legacy saved intent keys remain
-- compatible, while explicit overrides are confined to Ship Controls.
local evaluate=aiEvaluate
aiEvaluate=function(s)
 local selected=P.selectTarget(s)
 if not selected then s.ai.lastDecision=nil end
 if s.ai.manualMissionOrders then
  s.ai.plan=nil;s.ai.message="Mission order: "..tostring(s.missionOrders or s.ai.missionOrders)..". Select the mission objective and move manually using Ship Tools.";return
 end
 local intent=s.ai.tacticOverride
 if intent~="engage" and intent~="chase" and intent~="escape" then
  intent="engage"
  if selected and selected.measure.baseEdgeDistance>RANGE_SEGMENT*3 then intent="chase" end
  local c=s.combat
  if selected and c and type(c.hull)=="number" and type(c.maxHull)=="number" and c.maxHull>0
   and c.hull>0 and c.hull<=c.maxHull/3 and (c.shields or 0)<=0 and selected.measure.range<=3 then intent="escape" end
 end
 s.ai.intent=intent
 evaluate(s)
 if s.ai.plan then
  local plan=s.ai.plan
  local reason=intent=="chase" and "closing into weapon range" or intent=="escape" and "opening distance while avoiding hazards" or "turning / spacing to get a shot"
  s.ai.message=(selected and ("Target: "..selected.target.name.." ["..aiSide(selected.target).."]") or "No target")..
   " | Range "..tostring(plan.range).." | sector "..tostring(plan.zone).."\n"..
   (s.ai.tacticOverride and "Manual tactic: " or "Auto: ")..reason.."\n"..
   maneuverLabel(s,plan.key)..(plan.avoidance and (" | "..plan.avoidance) or "")
  s.ai.lastDecision={targetId=plan.targetId,targetName=selected and selected.target.name,range=plan.range,
   key=plan.key,reason=reason,avoidance=plan.avoidance,round=STA2E.game.round}
  plan.environment=P.environment()
 end
end
function P.environment()
 local rows={}
 for id,s in pairs(STA2E.ships) do
  local base=member(s,"base")
  if base then local p,r=base.getPosition(),base.getRotation();rows[#rows+1]=string.format("%s|%.3f|%.3f|%.3f|%s|%s",id,p.x,p.z,r.y,aiSide(s),tostring(s.combat and s.combat.destroyed or false)) end
 end
 for _,item in ipairs(terrainSnapshot(nil)) do
  rows[#rows+1]=string.format("terrain|%s|%.3f|%.3f|%.3f|%.3f|%.3f",item.kind,item.pose.x,item.pose.z,item.pose.yaw,item.shape.x,item.shape.z)
 end
 local f=P.frame();rows[#rows+1]=string.format("map|%.3f|%.3f|%.3f|%.3f|%.3f",f.x,f.z,f.yaw,f.halfX,f.halfZ)
 table.sort(rows);return table.concat(rows,";")
end
-- Check all opponents for action opportunities instead of assuming the chosen
-- navigation target is also the only firing / defensive consideration.
aiActionContext=function(s)
 local tokens=aiTokenSnapshot();local selected=P.selectTarget(s)
 local target=selected and selected.target;local measure=target and MeasurementGeometry.measure(s,target)
 local threats,shot,near=0,false,false;local firingTarget,firingMeasure
 for _,enemy in pairs(STA2E.ships) do if P.hostile(s,enemy) then
  local outgoing=MeasurementGeometry.measure(s,enemy)
  if outgoing and outgoing.range>=1 and outgoing.range<=3 then
   near=true
   if outgoing.arcs.primary or outgoing.arcs.rear or outgoing.arcs.secondary then
    shot=true
    if not firingMeasure or outgoing.baseEdgeDistance<firingMeasure.baseEdgeDistance then firingTarget,firingMeasure=enemy,outgoing end
   end
  end
  local incoming=MeasurementGeometry.measure(enemy,s)
  if incoming and incoming.range>=1 and incoming.range<=3 and (incoming.arcs.primary or incoming.arcs.rear or incoming.arcs.secondary) then threats=threats+1 end
 end end
 if firingTarget then target,measure=firingTarget,firingMeasure end
 return {tokens=tokens,target=target,measure=measure,enemyIn12=measure and measure.range>=1 and measure.range<=3 or false,
  enemyInRange=near,meaningfulAttack=shot,threats=threats,intent=s.ai.intent or "engage",
  cloakedTarget=target and (target.state.action=="CLK" or aiHasToken(target,"CLK",tokens)) or false,
  higherSkill=target and skillFor(target)>skillFor(s) or false}
end
local chooseAction=STA2E_AllianceChooseAction
function STA2E_AllianceChooseAction(params)
 local s=params and params.ship
 if not s or not (s.ai and s.ai.enabled) or s.ai.manualMissionOrders or s.state.aiSkipAction then return nil end
 if #aiAuxTokens(s)>0 then return {key="CLEAR_AUX",reason="Auxiliary Power must be removed first",score=200} end
 local result=chooseAction(params)
 if result and result.key=="TL" then
  local m=result.context and result.context.measure
  if not m or m.range<1 or m.range>3 then return nil end
 end
 return result
end
-- Do not select offensive tokens when no legal shot exists; defensive actions
-- remain useful. Regeneration requires known damage rather than guessing.
AllianceAI.registerActionEvaluator("BS",function(s,c)
 if aiHasToken(s,"BS",c.tokens) or (not c.meaningfulAttack and c.threats==0) then return nil end
 return (c.meaningfulAttack and 85 or 48)+math.min(c.threats,2)*3,"usable firing / defense solution"
end)
AllianceAI.registerActionEvaluator("TL",function(s,c)
 if not c.target or not c.enemyIn12 or not c.meaningfulAttack or aiHasToken(s,"TL",c.tokens) then return nil end
 return c.measure.range>=2 and 88 or 76,"target in weapon range; improve the attack"
end)
AllianceAI.registerActionEvaluator("REG",function(s,c)
 if aiHasToken(s,"REG",c.tokens) or P.damage(s)<=0 then return nil end
 return c.threats>0 and 96 or 80,"known hull damage can be repaired"
end)
local afterMove=STA2E_AI_AfterMove
function STA2E_AI_AfterMove(s,key)
 if s.ai and s.ai.enabled and not (s.m5 and s.m5.controlled) and not s.state.lastMoveBlocked then
  local entry=maneuver(s,key)
  if not (entry and entry.difficulty=="red") then
   local tokens=aiAuxTokens(s)
   if #tokens>0 then
    if s.undo then s.undo.aiRemovedAux=tokens[1].getData() end
    tokens[1].destruct();s.state.action="CLEAR_AUX";s.state.status="complete";s.ai.plan=nil
    s.ai.lastAction={key="CLEAR_AUX",reason="remove Auxiliary Power before other actions",round=STA2E.game.round}
    broadcastToAll("[AI] "..s.name..": removed 1 Auxiliary Power as its action.",{0.7,0.85,1});return
   end
  end
 end
 return afterMove(s,key)
end
function P.range(s,color)
 s.state.guideRange=s.state.guideRange==3 and 0 or 3
 drawShipGuides(s);P.collect={color=color,lines={}};STA2E_ReportMeasurements(s,color)
 if #P.collect.lines>0 then
  local lines=P.collect.lines
  if #lines>5 then for i=#lines,6,-1 do table.remove(lines,i) end;lines[#lines+1]="More results in chat." end
  P.notice[color]={text=table.concat(lines,"\n"),at=Time.time}
 end
 P.collect=nil;refresh(s)
end
function P.aiArcs(s)
 local base=member(s,"base");if not base then return end
 s.state.aiSectors=not s.state.aiSectors
 STA2E_LegacyGuide({guid=base.getGUID(),owner="playtest-ai-"..s.instanceId,mode=s.state.aiSectors and "ai" or "clear"})
 refresh(s)
end
function P.transfer(s,color)
 if not own(color) then return false end
 s.owner=color
 local seen={}
 for _,object in ipairs(getAllObjects()) do
  local m=metadata(object)
  if m and m.instanceId==s.instanceId and m.cardGUID==s.cardGUID and not seen[object.getGUID()] then
   seen[object.getGUID()]=true;m.owner=color
   if m.role=="card" then object.call("STA2E_SetMemory",copy(s))
   else object.call("STA2E_SetMemory",m) end
  end
 end
 local base=member(s,"base")
 local profile=definition(s.definitionId)
 if base then
  local texture=STA2E_BaseTexture(color,profile and profile.arc or "90",baseShape(base).x>2,s.ai and s.ai.enabled)
  if texture and base.getCustomObject and base.setCustomObject then
   local custom=base.getCustomObject();custom.diffuse=texture;base.setCustomObject(custom)
   -- TTS custom texture changes require reload. The persistent metadata is
   -- committed first so the reloaded object can register its existing identity.
   refresh(s)
   if base.reload then
    P.reloading=P.reloading or {};local guid=base.getGUID();P.reloading[guid]=true
    base.reload();Wait.frames(function()P.reloading[guid]=nil end,3)
   end
  end
 end
 refresh(s);hud();return true
end
function P.remove(s)
 local id=s.instanceId;local objects={}
 for _,object in ipairs(getAllObjects()) do
  local m=metadata(object);local notes=object.getGMNotes() or ""
  if (m and m.instanceId==id and m.cardGUID==s.cardGUID) or notes:sub(1,#("STA2E_SHIP_TOKEN|"..id.."|"))=="STA2E_SHIP_TOKEN|"..id.."|" or notes=="STA2E_ALLIANCE_SHIELD|"..id then objects[#objects+1]=object end
 end
 STA2E.pending[id]=nil;STA2E.pendingMoves[id]=nil
 -- Card is last so existing mission destruction hooks see the ship record.
 table.sort(objects,function(a,b)return a.getGUID()~=s.cardGUID and b.getGUID()==s.cardGUID end)
 for _,object in ipairs(objects) do if obj(object.getGUID()) then object.destruct() end end
 STA2E.ships[id]=nil;hud()
end
function P.settings(s)
 local out={'<Panel width="700" height="820" position="0 0 -120" rotation="0 0 180" scale="0.4 0.4 1" color="#102432F5">',
 '<Text text="'..xml(s.name)..' · SHIP CONTROLS" position="0 365 0" width="670" height="40" fontSize="24" color="#FFFFFF"/>',
 '<Text text="Owner: '..xml(s.owner)..' | Allegiance: '..xml(aiSide(s))..'" position="0 320 0" width="670" height="35" fontSize="21" color="#FFD86B"/>'}
 local function b(id,label,x,y,color,width)out[#out+1]=dialButton(id,label,x,y,color or "#375A78",width or 205)end
 for i,color in ipairs(PLAYER_COLORS) do b("owner_"..color,color,-220+((i-1)%3)*220,260-math.floor((i-1)/3)*60) end
 b("set_allied","ALLIED",-170,125,nil,300);b("set_enemy","ENEMY",170,125,nil,300)
 b("tactic_auto","AUTO TACTICS",0,55,"#256348",600)
 b("tactic_engage","GET A SHOT",-220,-10);b("tactic_chase","CLOSE DISTANCE",0,-10);b("tactic_escape","OPEN DISTANCE",220,-10)
 out[#out+1]='<Text text="'..xml(s.ai and s.ai.tacticOverride and "Manual override active" or "Automatic target and tactic selection")..'" position="0 -60 0" width="650" height="32" fontSize="17" color="#C8D9E8"/>'
 b("deploy","DEPLOY / REPAIR",-170,-120,"#256348",300);b("reposition_dial","BRING DIAL HERE",170,-120,nil,300)
 b("remove_ship",s.state.removeUntil and s.state.removeUntil>Time.time and "CONFIRM REMOVE SHIP" or "REMOVE SHIP",0,-195,"#863B3B",500)
 out[#out+1]='<Text text="Remove clears this ship and its linked pieces. Click twice to confirm." position="0 -245 0" width="650" height="40" fontSize="15" color="#C8D9E8"/>'
 b("tool_home","SHIP TOOLS",-170,-325,nil,300);b("tool_phase","BACK TO PHASE",170,-325,nil,300)
 out[#out+1]='</Panel>';return table.concat(out)
end
local oldRender=render
render=function(s)
 oldRender(s)
 local dial=member(s,"dial")
 if dial and s.state.dialOpen and s.state.toolsPage=="ownership" then STA2E_SetDialXml(dial,P.settings(s))
 elseif dial and s.state.dialOpen and s.state.toolsPage and s.ai and s.ai.enabled then STA2E_SetDialXml(dial,toolsMarkup(s)) end
 if s.ai and s.ai.enabled and not s.state.cardMenuOpen then
  local card=obj(s.cardGUID)
  if card then
   local actions={}
   for _,key in ipairs((s.capabilities and s.capabilities.actions) or {}) do actions[#actions+1]=P.actionLabel("ai_action_"..key,key) end
   local info=s.ai.lastAction and s.ai.lastAction.round==STA2E.game.round and ("Action: "..P.actionLabel("ai_action_"..s.ai.lastAction.key,s.ai.lastAction.key).." · "..s.ai.lastAction.reason) or (s.ai.lastDecision and ("Target: "..tostring(s.ai.lastDecision.targetName)) or "ACT AI chooses target, maneuver and action")
   card.UI.setXml(objectPanelRoot(card,700,160)..'<Panel width="700" height="160" color="#102432EF"><Text text="'..xml(table.concat(actions,"   "))..'" position="0 40 0" width="670" height="60" fontSize="22" color="#FFD86B"/><Text text="'..xml(info)..'" position="0 -35 0" width="660" height="65" fontSize="18" color="#FFFFFF"/></Panel></Panel>')
  end
 end
end
local command=STA2E_Command
function STA2E_Command(params)
 if not params or not params.object then return end
 local s=shipFor(params.object);if not s then return command(params) end
 local cmd=params.command or ""
 if cmd=="ship_settings" then
  s.state.dialOpen=true;s.state.toolsPage="ownership";refresh(s);return
 end
 if cmd=="quick_range" then return P.range(s,params.color) end
 if cmd=="quick_ai_arcs" then return P.aiArcs(s) end
 if cmd=="reposition_dial" then
  local dial,card=member(s,"dial"),obj(s.cardGUID)
  if dial and card then local t=playerSideTransform(s.owner,card.getPosition(),{side=4.2,up=0.3});dial.setPosition(t.position);dial.setRotation(t.rotation) end
  return
 end
 if cmd:match("^owner_") or cmd:match("^set_") or cmd:match("^tactic_") or cmd=="remove_ship" then
  if not P.canManage(s,params.color) then tell(params.color,"Only the owner, host, or cooperative teammate can change ship controls.");return end
  if STA2E.pendingMoves[s.instanceId] or STA2E.pending[s.instanceId] or next(STA2E.imports or {}) then tell(params.color,"Wait for deployment or movement to finish.");return end
  if cmd:match("^owner_") then P.transfer(s,cmd:sub(7))
  elseif cmd=="set_allied" or cmd=="set_enemy" then s.side=cmd=="set_allied" and "allied" or "enemy";if s.ai then s.ai.plan=nil end
  elseif cmd:match("^tactic_") then
   s.ai=s.ai or {enabled=false,intent="engage"};local choice=cmd:sub(8)
   if choice=="auto" then s.ai.tacticOverride=nil
   elseif choice=="engage" or choice=="chase" or choice=="escape" then s.ai.tacticOverride=choice else return end
   s.ai.plan=nil
  elseif cmd=="remove_ship" then
   if s.state.removeUntil and s.state.removeUntil>Time.time then return P.remove(s) end
   s.state.removeUntil=Time.time+10
  end
  refresh(s);return
 end
 -- Manual objective orders cannot accidentally enter generic attack logic.
 if (cmd=="ai_evaluate" or cmd=="ai_execute") and s.ai and s.ai.manualMissionOrders then
  tell(params.color,"Resolve "..tostring(s.missionOrders or s.ai.missionOrders).." mission objectives using Ship Tools.");return
 end
 if s.ai and s.ai.enabled and cmd=="ai_evaluate" then s.state.toolsPage=nil end
 if cmd=="ai_execute" and s.ai and s.ai.plan and s.ai.plan.environment and s.ai.plan.environment~=P.environment() then
  s.ai.plan=nil;s.ai.message="Board positions changed. Press PLAN again to update the route.";refresh(s);tell(params.color,s.ai.message);return
 end
 return command(params)
end
-- Persistent, readable result panel: TTS broadcast fade duration is engine-owned.
-- This panel retains the last result until replaced or explicitly closed.
P.notice={}
local message=tell
tell=function(color,text)
 message(color,text)
 if type(text)=="string" and (text:find("base-edge",1,true) or text:find("Range ",1,true)) then
  if P.collect and P.collect.color==color then P.collect.lines[#P.collect.lines+1]=text end
  P.notice[color]={text=text,at=Time.time};hud()
 end
end
local broadcast=broadcastToAll
function broadcastToAll(text,color)
 broadcast(text,color)
 if type(text)=="string" and (text:find("has executed",1,true) or text:find("immediate maneuver",1,true) or text:sub(1,4)=="[AI]") then
  P.notice.All={text=text,at=Time.time};hud()
 end
end
local modify=modifyPanel
modifyPanel=function()
 local markup=modify()
 for color,notice in pairs(P.notice) do
  local visibility=color=="All" and "" or (' visibility="'..xml(color)..'"')
  local y=color=="All" and -150 or -240
  local _,lineCount=notice.text:gsub("\n","");local height=math.min(180,math.max(80,35+24*(lineCount+1)))
  if color~="All" then y=-300 end
  markup=markup..'<Panel id="playtest_notice_'..xml(color)..'"'..visibility..' rectAlignment="UpperCenter" offsetXY="0 '..y..'" width="700" height="'..height..'" color="#102432EC"><Text text="'..xml(notice.text)..'" width="640" height="'..(height-10)..'" fontSize="17" color="#FFFFFF"/><Button id="notice_'..xml(color)..'" onClick="STA2E_PlaytestCloseNotice" position="330 '..(height/2-20)..' 0" width="32" height="32" fontSize="17">X</Button></Panel>'
 end
 return markup
end
function STA2E_PlaytestCloseNotice(player,value,id)
 local color=id and id:match("^notice_(.+)$")
 if color and (color=="All" or (player and player.color==color)) then P.notice[color]=nil;hud() end
end
local destroy=onObjectDestroy
function onObjectDestroy(object)
 if P.reloading and P.reloading[object.getGUID()] then return end
 return destroy(object)
end
local loadPrevious=onLoad
function onLoad(saved)
 P.notice={};return loadPrevious(saved)
end
-- Normal imported card formats are standardized. Interactive captain boards,
-- references, and M5 cards retain their custom physical formats.
local dataPrevious=cardData
cardData=function(card)
 local data=dataPrevious(card)
 if data and card and not card.interactiveCaptain and not card.m5Program and data.Name=="CardCustom" then
  local scale=card.type=="ship" and 1.2 or 1
  data.Transform.scaleX=scale;data.Transform.scaleZ=scale
 end
 return data
end
end)()

