-- Returned-save refinements: settled model following, flat guides and generic
-- ship references. No base position or velocity is changed by the follower.
;(function()
local P=STA2E_Playtest
local F={jobs={},references={},epoch=0}
P.follow=F
function P.guidePlane()
 local board=obj("ae9c49")
 if board then
  local p=board.getPosition()
  local bounds=board.getVisualBoundsNormalized and board.getVisualBoundsNormalized()
  if bounds and bounds.size and bounds.size.y then
   local center=(bounds.center and bounds.center.y) or (p.y+(bounds.offset and bounds.offset.y or 0))
   return center+bounds.size.y/2+0.015
  end
  return p.y+0.515
 end
 return 1.015
end
function STA2E_GuidePlane()return P.guidePlane()end
function P.guideY(object)
 local p=object.getPosition()
 if object.positionToLocal then
  local v=object.positionToLocal({x=p.x,y=P.guidePlane(),z=p.z})
  return v.y or v[2]
 end
 local scale=object.getScale()
 return (P.guidePlane()-p.y)/math.max(0.001,math.abs(scale.y))
end
local syncNow=sync
local colors={"White","Brown","Red","Orange","Yellow","Green","Teal","Blue","Purple","Pink","Grey","Black"}
local function restoreModel(s,model)
 if model and model.setInvisibleTo then model.setInvisibleTo(s.state.modelFollowHidden or {}) end
 s.state.modelFollowPending=nil;s.state.modelFollowHidden=nil
end
local function movingSmoothly(base)
 if type(base.isSmoothMoving)=="function" then return base.isSmoothMoving() end
 return base.isSmoothMoving==true
end
local function held(object)
 return type(object.held_by_color)=="string" and object.held_by_color~=""
end
function F.request(s)
 local base,model=member(s,"base"),member(s,"model")
 if not base or not model or held(model) then return end
 if base.getGUID()==model.getGUID() then
  if s.state.guideArc or (s.state.guideRange or 0)>0 or s.state.aiSectors then
   local function redraw(attempt)
    if not obj(base.getGUID()) or STA2E.ships[s.instanceId]~=s then return end
    if base.resting~=false and not base.held_by_color then drawShipGuides(s)
    elseif attempt<100 then Wait.frames(function()redraw(attempt+1)end,3) end
   end
   Wait.frames(function()redraw(1)end,3)
  end
  return
 end
 local existing=F.jobs[s.instanceId]
 if existing and existing.base==base.getGUID() and existing.model==model.getGUID() then
  existing.stable=0;existing.last=nil;return
 end
 local p=base.getPosition()
 local job={base=base.getGUID(),model=model.getGUID(),stable=0,polls=0,epoch=F.epoch,
  oldPosition=model.getPosition(),oldRotation=model.getRotation()}
 F.jobs[s.instanceId]=job
 -- Temporarily remove only the decorative miniature from the base's fall path.
 -- Its parked state is persisted so a save during a drag can recover on load.
 if not s.state.modelFollowPending then
  s.state.modelFollowHidden=model.getInvisibleTo and model.getInvisibleTo() or {}
 end
 s.state.modelFollowPending=true;s.state.basePlaneY=nil
 commit(s)
 if model.setInvisibleTo then model.setInvisibleTo(colors) end
 if model.setLock then model.setLock(true) end
 model.setPosition({p.x,-1000,p.z})
 local function poll()
  if F.jobs[s.instanceId]~=job or F.epoch~=job.epoch then return end
  local b,m=obj(job.base),obj(job.model)
  if not b or not m or STA2E.ships[s.instanceId]~=s then
   F.jobs[s.instanceId]=nil
   if m then m.setPosition(job.oldPosition);m.setRotation(job.oldRotation);restoreModel(s,m) end
   return
  end
  job.polls=job.polls+1
  local q,r=b.getPosition(),b.getRotation()
  local heldBase=held(b) or held(m)
  if heldBase or movingSmoothly(b) or STA2E.pendingMoves[s.instanceId] then job.stable=0;job.last=nil
  else
   local last=job.last
   local stable=last and math.abs(q.x-last.x)<0.01 and math.abs(q.y-last.y)<0.01 and math.abs(q.z-last.z)<0.01
    and aiAngleDistance(r.y,last.yaw)<0.2 and aiAngleDistance(r.x,last.pitch)<0.2 and aiAngleDistance(r.z,last.roll)<0.2
   if b.getVelocity then local v=b.getVelocity();stable=stable and v.x*v.x+v.y*v.y+v.z*v.z<0.0025 end
   job.stable=stable and job.stable+1 or 0
   job.last={x=q.x,y=q.y,z=q.z,yaw=r.y,pitch=r.x,roll=r.z}
   if (job.stable>=4 and b.resting~=false) or job.stable>=20 then
    F.jobs[s.instanceId]=nil;syncNow(s);restoreModel(s,m);commit(s)
    if s.state.guideArc or (s.state.guideRange or 0)>0 or s.state.aiSectors then drawShipGuides(s) end
    return
   end
  end
  if job.polls>=600 then
   F.jobs[s.instanceId]=nil
   -- Never force the base to settle. A held ship will get a fresh job on Drop.
   if not heldBase and job.stable>=4 then syncNow(s);restoreModel(s,m);commit(s) end
   return
  end
  Wait.frames(poll,3)
 end
 Wait.frames(poll,3)
end
function STA2E_FollowModel(s)return F.request(s)end
sync=function(s)
 if s.state.modelFollowPending and not STA2E.pendingMoves[s.instanceId] then return end
 return syncNow(s)
end
local pickup=onObjectPickUp
function onObjectPickUp(color,object)
 if pickup then pickup(color,object) end
 local s=shipFor(object);local m=metadata(object)
 if s and m and (m.role=="base" or m.role=="baseModel") then F.request(s) end
end
-- Pickup/drop callbacks are an optimization, not the only way to notice a
-- manual placement. Also recover interrupted jobs and direct transform edits.
F.observed={};F.nextScan=0
function F.scan()
 for id,s in pairs(STA2E.ships or {}) do
  local b,m=member(s,"base"),member(s,"model")
  if b and m and not F.jobs[id] and not held(m) and not STA2E.pendingMoves[id] and not STA2E.pending[id] then
   local p,r,q=b.getPosition(),b.getRotation(),m.getPosition()
   local d=SHIP_DEFINITIONS[s.definitionId]
   local offset=d and d.model and d.model.offsetY or -1.2
   local mr=m.getRotation()
   local mismatch=b.getGUID()~=m.getGUID() and (math.abs(q.x-p.x)>.02 or math.abs(q.z-p.z)>.02 or math.abs(q.y-p.y-offset)>.02
    or aiAngleDistance(r.y,mr.y)>.2 or aiAngleDistance(r.x,mr.x)>.2 or aiAngleDistance(r.z,mr.z)>.2)
   local last=F.observed[id]
   local changed=not last or math.abs(last.x-p.x)>.01 or math.abs(last.z-p.z)>.01 or math.abs(last.y-p.y)>.01 or aiAngleDistance(last.yaw,r.y)>.2
   F.observed[id]={x=p.x,y=p.y,z=p.z,yaw=r.y}
   if mismatch or s.state.modelFollowPending or held(b) or (changed and (s.state.guideArc or (s.state.guideRange or 0)>0 or s.state.aiSectors)) then F.request(s) end
  end
 end
 for id in pairs(F.observed) do if not STA2E.ships[id] then F.observed[id]=nil end end
end
local updatePrevious=onUpdate
function onUpdate()
 if updatePrevious then updatePrevious() end
 if not STA2E.ready or STA2E.loading or STA2E.reconciling or Time.time<F.nextScan then return end
 F.nextScan=Time.time+.2;F.scan()
end

-- These are real generic ship-card routes from the bundled catalog, independent
-- references rather than imported fleet ships, captains, or AI loadout decks.
function F.generic(s)
 local ship=SHIP_DEFINITIONS[s.definitionId]
 local source=STA2E_GENERIC_REFERENCES.factions[s.definitionId] or {}
 if not ship then return nil end
 local options={}
 for _,card in ipairs(STA2E_GENERIC_REFERENCES.generic) do
  if card.class==ship.class and CATALOG[card.id] then
   local score=card.alliance==source.alliance and 2 or 0
   for _,a in ipairs(source.factions or {}) do for _,b in ipairs(card.factions) do if a==b then score=score+5 end end end
   if card.id==s.definitionId then score=score+20 end
   options[#options+1]={id=card.id,score=score}
  end
 end
 table.sort(options,function(a,b)if a.score~=b.score then return a.score>b.score end return a.id>b.id end)
 return options[1] and options[1].id,ship.class
end
function F.ensureReference(s)
 if member(s,"classReference") or F.references[s.instanceId] then return end
 local cardId,class=F.generic(s)
 local card=obj(s.cardGUID)
 if not cardId or not card then return end
 local data=cardData(CATALOG[cardId]);if not data then return end
 local ticket={epoch=F.epoch};F.references[s.instanceId]=ticket
 data.Nickname=class.." — Generic Ship Reference"
 data.Value=0
 data.Description="Generic class reference ("..cardId.."). Reference only; this is not an additional fleet ship. "..(data.Description or "")
 data.LuaScript=MEMBER_SCRIPT
 local memory={schemaVersion=1,role="classReference",instanceId=s.instanceId,cardGUID=s.cardGUID,owner=s.owner,referenceId=cardId}
 data.LuaScriptState=JSON.encode(memory)
 local t=playerSideTransform(s.owner,card.getPosition(),{side=3.15,forward=-5.2,up=0.15})
 local ok,error=pcall(function()
  spawnObjectData({data=data,position=t.position,rotation=t.rotation,callback_function=function(object)
   if not object then F.references[s.instanceId]=nil;return end
   if F.references[s.instanceId]~=ticket or ticket.epoch~=F.epoch or STA2E.ships[s.instanceId]~=s or not obj(s.cardGUID) then object.destruct();return end
   F.references[s.instanceId]=nil;s.refs.classReference=object.getGUID()
   object.call("STA2E_SetMemory",memory);commit(s)
  end})
 end)
 if not ok then F.references[s.instanceId]=nil;print("Class reference could not spawn: "..tostring(error)) end
end
local deployPrevious=deploy
deploy=function(s)
 local result=deployPrevious(s)
 if s.deployedOnce or member(s,"base") or STA2E.pending[s.instanceId] then F.ensureReference(s) end
 return result
end
local commandPrevious=STA2E_Command
function STA2E_Command(params)
 local s=params and shipFor(params.object)
 if s and params.command=="class_reference" then return F.ensureReference(s) end
 local result=commandPrevious(params)
 if s and (params.command=="undo" or params.command=="tool_undo" or params.command=="ai_undo") then F.request(s) end
 return result
end
local loadPrevious=onLoad
function onLoad(saved)
 F.epoch=F.epoch+1;F.jobs={};F.references={};F.observed={};F.nextScan=0
 local epoch=F.epoch
 loadPrevious(saved)
 local function restore(attempt)
  if epoch~=F.epoch then return end
  if STA2E.loading or not STA2E.ready then if attempt<1000 then Wait.frames(function()restore(attempt+1)end,3) end;return end
  for _,token in ipairs(getAllObjects()) do
   if token.getGMNotes and (token.getGMNotes() or ""):match("^STA2E_SHIP_TOKEN|[^|]+|CLK$") then STA2E_InstallCloakEcho(token) end
  end
  for _,s in pairs(STA2E.ships) do
   s.state.basePlaneY=nil
   if s.state.modelFollowPending or s.deployedOnce then F.request(s) end
   if s.deployedOnce then F.ensureReference(s) end
  end
 end
 Wait.frames(function()restore(1)end,3)
end
end)()
